test('Opening Act Pinkadot source-confirmed colours remain discoverable without the unknown colour category',()=>{
 const id='p-a78d88d48f5e',query='オープニングアクト ピンクアドット';assert.deepEqual(CATALOG[id].colors,['white','pink','mixed']);for(const color of['all','white','pink','mixed'])assert.deepEqual(searchCatalog(CATALOG,{query,color}).map(([key])=>key),[id]);for(const color of['unknown','blue','orange'])assert.deepEqual(searchCatalog(CATALOG,{query,color}),[]);assert.equal(CATALOG[id].appearance.flowerPattern,'openingActStar');assert.equal(CATALOG[id].appearance.sources[2].url,'https://provenwinners.jp/product/phlox/');assert.deepEqual(CATALOG['p-a86ec7d82580'].colors,['pink']);
});

test('Annual phlox references retain domestic one or two year qualifications and never revive after one planned flowering cycle',()=>{
 for(const[id,sku]of[['p-9dede15d4dab','303is'],['p-040a45429ccc','303cc']]){const c=CATALOG[id],a=c.appearance;assert.equal(c.life,'annual');assert.deepEqual(c.height,[.15,.25]);assert.deepEqual(c.spread,[.2,.3]);assert.deepEqual(c.bloom,[5,6,7,8,9,10,11]);assert.equal(c.bloomKnown,false);assert.equal(c.source,'https://item.rakuten.co.jp/ogis/'+sku+'/');assert.equal(c.sourceChecked,'2026-10-26');assert.equal(a.status,'partial');assert.equal(a.architecture,'annualPhloxReferences');assert.equal(a.arrangement,'lowerOppositeUpperAlternate');assert.equal(a.leafShape,'annualPhloxLeaf');assert.equal(a.inflorescence,'cyme');assert.equal(a.persistence,'coolSeasonAnnual');assert.equal(a.sources[a.basis.arrangement].url,'https://plants.ces.ncsu.edu/plants/phlox-drummondii/');assert.ok(a.unconfirmed.some(n=>/一・二年草/.test(n)));assert.ok(a.unconfirmed.some(n=>/9月以降.*計画上の仮定/.test(n)));assert.ok(a.unconfirmed.some(n=>/夏越しできた一例/.test(n)));assert.ok(a.unconfirmed.some(n=>/こぼれ種.*自動追加しません/.test(n)));assert.ok(!c.colors.includes('unknown'));assert.ok(a.unconfirmed.every(n=>!/Float32|RNG|HTTP|行列/.test(n)));
  const p={...makePlant(id,84500,3,3),height:.2,spread:.25,leafHeight:.11,start:9},copy=structuredClone(p);for(const[year,month,present,bloom,expired]of[[0,9,false,false,false],[0,10,true,false,false],[0,12,true,false,false],[1,1,true,false,false],[1,3,true,false,false],[1,5,true,true,false],[1,10,true,true,false],[1,11,true,true,false],[1,12,false,false,true],[2,5,false,false,true]]){const v={year,month,reference:false},s=stateAt(p,v);assert.equal(s.present,present,id+' '+year+'/'+month+' presence');assert.equal(s.bloom,bloom,id+' '+year+'/'+month+' bloom');assert.equal(s.expired,expired,id+' '+year+'/'+month+' expiry');assert.equal(inspectionSeasonActive(p,v),present&&bloom);if(present&&!bloom)assert.ok(s.leafDensity>0);if(expired)assert.equal(s.groundDormant,true);}assert.deepEqual(p,copy);
  const spring={...p,start:0};assert.equal(stateAt(spring,{year:0,month:5,reference:false}).bloom,true);assert.equal(stateAt(spring,{year:0,month:12,reference:false}).present,false);assert.equal(stateAt(spring,{year:1,month:5,reference:false}).bloom,false);
 }
});

test('Annual phlox real clasping blades lower pairs upper alternate leaves cymes and indexed corollas fit selected dimensions and cycle limits',()=>{
 const eps=1e-7,distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),onSegment=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),len=d.reduce((n,x)=>n+x*x,0),t=len?Math.max(0,Math.min(1,d.reduce((n,x,i)=>n+x*(p[i]-a[i]),0)/len)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};let models=0,actualVertices=0,leafJoins=0,openModels=0,cameraPoses=0,expiredModels=0,maxSurfaceAttempts=0;
 for(const[id,variant]of[['p-9dede15d4dab','isabellina'],['p-040a45429ccc','cherryCaramel']]){const sizes=[[.2,.25,.11],[.03,.18,.012],[.2,.25,.005]],cases=[...sizes.flatMap(dims=>[1,5,10,12].map(month=>({dims,month,year:1,reference:false}))),...[[.005,.08,.005],[.2,.005,.005],[.005,.3,.005]].flatMap(dims=>[1,5].map(month=>({dims,month,year:1,reference:false}))),{dims:sizes[0],month:5,year:1,reference:true},{dims:sizes[0],month:5,year:2,reference:false}];
  for(const{dims,month,year,reference}of cases){models++;const p={...makePlant(id,84510,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2],start:9},copy=structuredClone(p),v={month,year,reference},s=stateAt(p,v),g=plantModel(p,v),label=JSON.stringify({id,dims,month,year,reference}),matrix=new Matrix4(),stems=[],leaves=[];let lo=Infinity,hi=-Infinity,radial=0,leafTop=-Infinity;
   try{if(!s.present){expiredModels++;assert.equal(s.expired,true);assert.equal(g.children.length,0);assert.equal(flowerInspectionView(g,.8,40),null);continue;}assert.equal(g.userData.architecture,'annualPhloxReferences');assert.equal(flowerInspectionDistanceFloor(g),.08);assert.ok(!g.children.some(m=>/petiole|dry-stem|fruit|seed|anther|filament|style/.test(m.userData.component)),label+' no fabricated petioles winterdeadstems or internalorgans');const count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),paired=count('leaf-annual-phlox-ref-paired'),alternate=count('leaf-annual-phlox-ref-alternate'),petal='petal-annual-phlox-'+variant,n=Math.max(3,Math.min(10,Math.round(6*Math.pow(s.spread/.3,.60))));assert.ok(paired>0);assert.equal(paired%2,0);if(s.bloom){assert.equal(paired,n*10);assert.equal(alternate,n*3);assert.ok(count('cyme-annual-phlox')>0);}assert.equal(count(petal),count('tube-panicle-phlox')*5);assert.equal(count('sepal-panicle-phlox'),count('tube-panicle-phlox')*5);assert.equal(count('eye-panicle-phlox'),count('tube-panicle-phlox'));assert.equal(count(petal)>0,s.bloom);assert.equal(!!g.userData.flowerTargets?.length,s.bloom);g.updateMatrixWorld(true);
    for(const mesh of g.children){const kind=mesh.userData.component,pos=mesh.geometry.attributes.position,leaf=kind.startsWith('leaf-annual-phlox-ref-');for(const arr of[pos.array,mesh.geometry.attributes.normal.array,mesh.instanceMatrix.array,mesh.instanceColor.array])assert.ok(arr.every(Number.isFinite),label+' finite actualdata');if(leaf||kind===petal){const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};mesh.material.onBeforeCompile(shader,{});assert.equal(shader.fragmentShader.includes('annualPhloxFuzz'),leaf);assert.equal(shader.fragmentShader.includes('annualPhloxEye'),kind===petal);assert.ok(!shader.fragmentShader.includes('openingActRay'));assert.ok(!shader.fragmentShader.includes('phloxRefEye'));assert.ok(!shader.fragmentShader.includes('\\n'));if(leaf){assert.equal(pos.count,555);assert.equal(mesh.geometry.index.count,3024);assert.equal(mesh.geometry.userData.annualPhloxLeaf,true);}else{assert.equal(pos.count,315);assert.equal(mesh.geometry.index.count,1680);}}
     for(let i=0;i<mesh.count;i++){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);const e=matrix.elements;if(leaf)leaves.push([e[12],e[13],e[14]]);if(kind==='stem-panicle-phlox')stems.push([-.5,.5].map(t=>[e[12]+e[4]*t,e[13]+e[5]*t,e[14]+e[6]*t]));for(let j=0;j<pos.count;j++){const point=new Vector3().fromBufferAttribute(pos,j).applyMatrix4(matrix);actualVertices++;lo=Math.min(lo,point.y);hi=Math.max(hi,point.y);radial=Math.max(radial,Math.hypot(point.x,point.z));if(leaf)leafTop=Math.max(leafTop,point.y);}}
    }
    assert.ok(lo>=-eps,label+' ground '+lo);assert.ok(hi<=s.height+eps,label+' height '+hi);assert.ok(radial*2<=s.spread+eps,label+' width '+radial*2);assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+eps,label+' independentleafcap '+leafTop);for(const origin of leaves){assert.ok(stems.some(line=>onSegment(origin,...line)<eps),label+' sessile leaf origin joins actualstem');leafJoins++;}
    if(s.bloom){openModels++;const anchor=g.userData.flowerTargets[0],surface=anchor.surface,mesh=g.children.find(m=>m.userData.component===surface.component);assert.equal(surface.component,petal);assert.ok(g.userData.surfaceSelection.matched,label+' visible indexedcorolla');maxSurfaceAttempts=Math.max(maxSurfaceAttempts,g.userData.surfaceSelection.attempts);mesh.getMatrixAt(surface.instanceId,matrix);const points=surface.vertices.map(i=>new Vector3().fromBufferAttribute(mesh.geometry.attributes.position,i).applyMatrix4(matrix)),centroid=points.reduce((n,p)=>n.add(p),new Vector3()).multiplyScalar(1/3);assert.ok(centroid.distanceTo(new Vector3(...anchor.origin))<2e-7);assert.deepEqual(surface.vertices,[0,1,2].map(i=>mesh.geometry.index.getX(surface.faceIndex*3+i)));g.position.set(-2,.012,-1);g.updateMatrixWorld(true);for(const aspect of[.8,1.65]){cameraPoses++;const pose=flowerInspectionView(g,aspect,40),camera=new PerspectiveCamera(40,aspect,.01,650);assert.ok(pose);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(hit=>{const z=-hit.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.equal(hit?.object.userData.component,surface.component,label+' firstcomponent');assert.equal(hit.instanceId,surface.instanceId,label+' firstinstance');assert.equal(hit.faceIndex,surface.faceIndex,label+' firsttriangle');assert.ok(hit.point.distanceTo(new Vector3(...pose.target))<2e-6);}}
    else assert.equal(flowerInspectionView(g,.8,40),null);
   }finally{assert.deepEqual(p,copy,label+' savedinputstable');dispose(g);}
  }
 }assert.equal(models,40);assert.equal(expiredModels,8);assert.equal(openModels,20);assert.equal(cameraPoses,40);console.log('ANNUAL_PHLOX_845_BOUNDARIES '+JSON.stringify({models,actualVertices,leafJoins,openModels,cameraPoses,expiredModels,maxSurfaceAttempts}));
});

test('Three retail panicle phlox source references preserve cultivar identity domestic ranges edge variegation and cold nursery winter scope',()=>{
 const rows=[['p-cb54d631958f','eva','312ec',[.45,.6]],['p-124e604bade4','elizabeth','312ez',[.5,.7]],['p-d67e09b6a869','olympus','312op',[.5,.7]]];
 for(const[id,variant,sku,height]of rows){const c=CATALOG[id],a=c.appearance;assert.deepEqual(c.height,height);assert.deepEqual(c.spread,[.4,.6]);assert.deepEqual(c.bloom,[6,7,8]);assert.equal(c.bloomKnown,false);assert.match(c.bloomText,/数値月の明記はなく/);assert.equal(c.source,'https://item.rakuten.co.jp/ogis/'+sku+'/');assert.equal(c.sourceChecked,'2026-10-26');assert.equal(a.status,'partial');assert.equal(a.arrangement,'opposite');assert.equal(a.persistence,'winterDormant');assert.equal(a.standingWinter,false);assert.equal(a.phenologyRegion,'grower-cold');assert.equal(a.flowerPalette.retailPanicle,variant);assert.equal(a.sources[a.basis.persistence].url,c.source);assert.equal(a.sources[a.basis.leafShape].url,'https://plants.ces.ncsu.edu/plants/phlox-paniculata/');assert.ok(a.unconfirmed.some(n=>/寒冷地・低温管理苗/.test(n)));assert.ok(a.unconfirmed.some(n=>/自動剪定/.test(n)));assert.ok(a.unconfirmed.every(n=>!/Float32|RNG|HTTP|行列/.test(n)));if(variant==='eva')assert.equal(a.leafPattern,undefined);else{assert.equal(a.leafPattern,'margin');assert.equal(a.sources[a.basis.leafPattern].url,c.source);}const p={...makePlant(id,84400,3,3),height:.6,spread:.5,leafHeight:.3},copy=structuredClone(p);for(let month=1;month<=12;month++){const s=stateAt(p,{month,year:1,reference:false});assert.equal(s.bloom,[6,7,8].includes(month));assert.equal(s.groundDormant,[12,1,2].includes(month));assert.equal(s.seedHeads,false);}assert.deepEqual(p,copy);}
 assert.match(CATALOG['p-d67e09b6a869'].latin,/Orinpas/);assert.match(CATALOG['p-d67e09b6a869'].appearance.unconfirmed.join(' '),/登録名.*未確認/);
});

test('Three retail panicle phlox connected actual leaf pairs cultivar shaders and indexed flowers fit selected dimensions and nursery dormancy',()=>{
 const eps=1e-7,distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),onSegment=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),len=d.reduce((n,x)=>n+x*x,0),t=len?Math.max(0,Math.min(1,d.reduce((n,x,i)=>n+x*(p[i]-a[i]),0)/len)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};let models=0,actualVertices=0,leafJoins=0,openModels=0,cameraPoses=0,winterModels=0,maxSurfaceAttempts=0;
 for(const[id,variant,normal]of[['p-cb54d631958f','eva',[.525,.5,.3]],['p-124e604bade4','elizabeth',[.6,.5,.3]],['p-d67e09b6a869','olympus',[.6,.5,.3]]]){const sizes=[normal,[.03,.18,.012],[normal[0],normal[1],.005]],cases=[...sizes.flatMap(dims=>[7,4,10,1].map(month=>({dims,month,reference:false}))),...[[.005,.08,.005],[.6,.005,.005],[.005,.8,.005]].flatMap(dims=>[7,1].map(month=>({dims,month,reference:false}))),{dims:normal,month:7,reference:true}];
  for(const{dims,month,reference}of cases){models++;const p={...makePlant(id,84410,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},copy=structuredClone(p),v={month,year:1,reference},s=stateAt(p,v),g=plantModel(p,v),label=JSON.stringify({id,dims,month,reference}),matrix=new Matrix4(),leaves=[],petioles=[],stems=[];let lo=Infinity,hi=-Infinity,radial=0,leafTop=-Infinity;
   try{if(s.groundDormant){winterModels++;assert.equal(g.children.length,0,label+' cold nursery aboveground absent');assert.equal(flowerInspectionView(g,.8,40),null);continue;}assert.equal(g.userData.architecture,'paniclePhlox');assert.equal(flowerInspectionDistanceFloor(g),.08);const count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),petal='petal-panicle-phlox-ref-'+variant,leafMeshes=g.children.filter(m=>m.userData.component.startsWith('leaf-panicle-phlox-ref-'+variant+'-')),leafCount=leafMeshes.reduce((n,m)=>n+m.count,0);assert.ok(leafCount>0);assert.equal(leafCount,count('petiole-panicle-phlox'));assert.equal(leafCount%2,0);assert.equal(count(petal),count('tube-panicle-phlox')*5);assert.equal(count('sepal-panicle-phlox'),count('tube-panicle-phlox')*5);assert.equal(count('eye-panicle-phlox'),count('tube-panicle-phlox'));assert.equal(count(petal)>0,s.bloom);assert.equal(!!g.userData.flowerTargets?.length,s.bloom);assert.ok(!g.children.some(m=>/fruit|seed|anther|filament|style/.test(m.userData.component)));if(variant==='olympus')assert.ok(leafMeshes.some(m=>m.userData.component.endsWith('-young')));g.updateMatrixWorld(true);
    for(const mesh of g.children){const kind=mesh.userData.component,pos=mesh.geometry.attributes.position,leaf=kind.startsWith('leaf-panicle-phlox-ref-'),foliage=leaf||kind==='petiole-panicle-phlox';for(const arr of[pos.array,mesh.geometry.attributes.normal.array,mesh.instanceMatrix.array,mesh.instanceColor.array])assert.ok(arr.every(Number.isFinite),label+' finite actual data');if(leaf||kind===petal){const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};mesh.material.onBeforeCompile(shader,{});assert.equal(shader.fragmentShader.includes('phloxVarEdge'),leaf&&variant!=='eva');assert.equal(shader.fragmentShader.includes('phloxRefEye'),kind===petal);assert.ok(!shader.fragmentShader.includes('openingActRay'));assert.ok(!shader.fragmentShader.includes('\\n'));if(leaf){assert.equal(pos.count,555);assert.equal(mesh.geometry.index.count,3024);}else{assert.equal(pos.count,315);assert.equal(mesh.geometry.index.count,1680);}}
     for(let i=0;i<mesh.count;i++){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);const e=matrix.elements;if(leaf)leaves.push([e[12],e[13],e[14]]);if(kind==='petiole-panicle-phlox'||kind==='stem-panicle-phlox'){const line=[-.5,.5].map(t=>[e[12]+e[4]*t,e[13]+e[5]*t,e[14]+e[6]*t]);(kind==='petiole-panicle-phlox'?petioles:stems).push(line);}for(let j=0;j<pos.count;j++){const point=new Vector3().fromBufferAttribute(pos,j).applyMatrix4(matrix);actualVertices++;lo=Math.min(lo,point.y);hi=Math.max(hi,point.y);radial=Math.max(radial,Math.hypot(point.x,point.z));if(foliage)leafTop=Math.max(leafTop,point.y);}}
    }
    assert.ok(lo>=-eps,label+' ground '+lo);assert.ok(hi<=s.height+eps,label+' height '+hi);assert.ok(radial*2<=s.spread+eps,label+' width '+radial*2);assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+eps,label+' leaf/petiole cap '+leafTop);const used=new Set();for(const origin of leaves){let best=Infinity,at=-1;for(let j=0;j<petioles.length;j++)if(!used.has(j)){const d=distance(origin,petioles[j][1]);if(d<best){best=d;at=j;}}assert.ok(at>=0&&best<eps,label+' blade unique petiole join');used.add(at);leafJoins++;assert.ok(stems.some(line=>onSegment(petioles[at][0],...line)<eps),label+' petiole connected to actual stem');}for(let i=0;i<petioles.length;i+=2)assert.ok(distance(petioles[i][0],petioles[i+1][0])<eps,label+' opposite pair shared node');
    if(s.bloom){openModels++;const anchor=g.userData.flowerTargets[0],surface=anchor.surface,mesh=g.children.find(m=>m.userData.component===surface.component);assert.equal(surface.component,petal);assert.ok(g.userData.surfaceSelection.matched,label+' visible actual triangle');maxSurfaceAttempts=Math.max(maxSurfaceAttempts,g.userData.surfaceSelection.attempts);mesh.getMatrixAt(surface.instanceId,matrix);const vertices=surface.vertices.map(i=>new Vector3().fromBufferAttribute(mesh.geometry.attributes.position,i).applyMatrix4(matrix)),centroid=vertices.reduce((n,p)=>n.add(p),new Vector3()).multiplyScalar(1/3);assert.ok(centroid.distanceTo(new Vector3(...anchor.origin))<2e-7);assert.deepEqual(surface.vertices,[0,1,2].map(i=>mesh.geometry.index.getX(surface.faceIndex*3+i)));g.position.set(-2,.012,-1);g.updateMatrixWorld(true);for(const aspect of[.8,1.65]){cameraPoses++;const pose=flowerInspectionView(g,aspect,40),camera=new PerspectiveCamera(40,aspect,.01,650);assert.ok(pose);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(hit=>{const z=-hit.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.equal(hit?.object.userData.component,surface.component,label+' first visible component');assert.equal(hit.instanceId,surface.instanceId,label+' visible actual instance');assert.equal(hit.faceIndex,surface.faceIndex,label+' visible actual triangle');assert.ok(hit.point.distanceTo(new Vector3(...pose.target))<2e-6);}}
    else assert.equal(flowerInspectionView(g,.8,40),null);
   }finally{assert.deepEqual(p,copy,label+' saved input preserved');dispose(g);}
  }
 }assert.equal(models,57);assert.equal(winterModels,18);assert.equal(openModels,21);assert.equal(cameraPoses,42);console.log('RETAIL_PANICLE_844_BOUNDARIES '+JSON.stringify({models,actualVertices,leafJoins,openModels,cameraPoses,winterModels,maxSurfaceAttempts}));
});

test('Opening Act phlox source-qualified seasons distinguish the two colours winter conditions and conditional rebloom',()=>{
 for(const[id,profile]of[['p-a78d88d48f5e','openingActPinkadot'],['p-a86ec7d82580','openingActRomance']]){
  const c=CATALOG[id],a=c.appearance;assert.deepEqual(c.height,[.5,.7]);assert.deepEqual(c.spread,[.7,.9]);assert.deepEqual(c.bloom,[3,4,5,6,7,8,9,10,11]);assert.equal(c.bloomKnown,false);assert.equal(c.sourceChecked,'2026-10-26');assert.match(c.bloomText,/切り戻し/);assert.equal(a.shootProfile,profile);assert.equal(a.status,'partial');assert.equal(a.arrangement,'opposite');assert.equal(a.persistence,'semiDormant');assert.equal(a.standingWinter,true);assert.equal(a.flowerTiming,'season-reference');assert.equal(a.sources[a.basis.arrangement].url,'https://provenwinners.jp/product/phlox/');assert.ok(a.unconfirmed.some(n=>/自動剪定/.test(n)));assert.ok(a.unconfirmed.some(n=>/暖地|関東以西/.test(n)));assert.ok(a.unconfirmed.some(n=>/未計測/.test(n)));assert.ok(a.unconfirmed.every(n=>!/Float32|RNG|HTTP|行列/.test(n)));
  const p={...makePlant(id,84300,3,3),height:.6,spread:.8,leafHeight:.35},copy=structuredClone(p);for(let month=1;month<=12;month++){const s=stateAt(p,{month,year:1,reference:false});assert.equal(s.bloom,month>=3&&month<=11);assert.equal(s.groundDormant,false);if([12,1,2].includes(month))assert.ok(s.leafDensity>0&&s.leafDensity<.2);assert.equal(s.shootScale,1);}assert.deepEqual(p,copy);
 }
 const pink=CATALOG['p-a78d88d48f5e'].appearance,romance=CATALOG['p-a86ec7d82580'].appearance;assert.equal(pink.flowerPattern,'openingActStar');assert.equal(romance.flowerPattern,undefined);assert.match(romance.unconfirmed.join(' '),/ウルトラピンク.*転用していません/);
});

test('Opening Act phlox actual paired leaves fused flowers and indexed observation fit selected seasons independent caps and minimum inputs',()=>{
 const eps=1e-7,distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),onSegment=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),len=d.reduce((n,x)=>n+x*x,0),t=len?Math.max(0,Math.min(1,d.reduce((n,x,i)=>n+x*(p[i]-a[i]),0)/len)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};let models=0,actualVertices=0,leafJoins=0,openModels=0,cameraPoses=0,maxSurfaceAttempts=0;
 for(const[id,variant]of[['p-a78d88d48f5e','pinkadot'],['p-a86ec7d82580','romance']]){
  const sizes=[[.6,.8,.35],[.03,.18,.012],[.6,.8,.005]],cases=[...sizes.flatMap(dims=>[5,3,10,1].map(month=>({dims,month,reference:false}))),...[[.005,.08,.005],[.6,.005,.005],[.005,.8,.005]].flatMap(dims=>[5,1].map(month=>({dims,month,reference:false}))),{dims:[.6,.8,.35],month:5,reference:true}];
  for(const{dims,month,reference}of cases){models++;const p={...makePlant(id,84310,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},copy=structuredClone(p),v={month,year:1,reference},s=stateAt(p,v),g=plantModel(p,v),label=JSON.stringify({id,dims,month,reference}),matrix=new Matrix4(),leaves=[],petioles=[],stems=[];let lo=Infinity,hi=-Infinity,radial=0,leafTop=-Infinity;
   try{assert.equal(g.userData.architecture,'paniclePhlox');assert.equal(flowerInspectionDistanceFloor(g),.08);const count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),petal='petal-opening-act-'+variant;assert.equal(count(petal),count('tube-panicle-phlox')*5);assert.equal(count('sepal-panicle-phlox'),count('tube-panicle-phlox')*5);assert.equal(count('eye-panicle-phlox'),count('tube-panicle-phlox'));assert.ok(count('leaf-panicle-phlox')>0,label+' paired leaves retained, including winter basal reference');assert.equal(count('leaf-panicle-phlox'),count('petiole-panicle-phlox'));assert.equal(count('leaf-panicle-phlox')%2,0);assert.ok(!g.children.some(m=>/fruit|seed|anther|filament|style/.test(m.userData.component)));if(month===1)assert.ok(count('dry-stem-panicle-phlox')>0);assert.equal(count(petal)>0,s.bloom);assert.equal(!!g.userData.flowerTargets?.length,s.bloom);g.updateMatrixWorld(true);
    for(const mesh of g.children){const kind=mesh.userData.component,pos=mesh.geometry.attributes.position,foliage=kind==='leaf-panicle-phlox'||kind==='petiole-panicle-phlox';for(const arr of[pos.array,mesh.geometry.attributes.normal.array,mesh.instanceMatrix.array,mesh.instanceColor.array])assert.ok(arr.every(Number.isFinite),label+' finite mesh data');if(kind===petal){assert.equal(pos.count,315);assert.equal(mesh.geometry.index.count,1680);const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};mesh.material.onBeforeCompile(shader,{});assert.equal(shader.fragmentShader.includes('openingActRay'),variant==='pinkadot');assert.ok(!shader.fragmentShader.includes('\\n'));}
     for(let i=0;i<mesh.count;i++){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);const e=matrix.elements;if(kind==='leaf-panicle-phlox')leaves.push([e[12],e[13],e[14]]);if(kind==='petiole-panicle-phlox'||kind==='stem-panicle-phlox'||kind==='dry-stem-panicle-phlox'){const line=[-.5,.5].map(t=>[e[12]+e[4]*t,e[13]+e[5]*t,e[14]+e[6]*t]);(kind==='petiole-panicle-phlox'?petioles:stems).push(line);}for(let j=0;j<pos.count;j++){const point=new Vector3().fromBufferAttribute(pos,j).applyMatrix4(matrix);actualVertices++;lo=Math.min(lo,point.y);hi=Math.max(hi,point.y);radial=Math.max(radial,Math.hypot(point.x,point.z));if(foliage)leafTop=Math.max(leafTop,point.y);}}
    }
    assert.ok(lo>=-eps,label+' ground '+lo);assert.ok(hi<=s.height+eps,label+' height '+hi);assert.ok(radial*2<=s.spread+eps,label+' width '+radial*2);assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+eps,label+' independent leaf cap '+leafTop);const used=new Set();for(let i=0;i<leaves.length;i+=2){const pair=leaves.slice(i,i+2).map(origin=>{let best=Infinity,at=-1;for(let j=0;j<petioles.length;j++)if(!used.has(j)){const d=distance(origin,petioles[j][1]);if(d<best){best=d;at=j;}}assert.ok(at>=0&&best<eps,label+' blade joins unique petiole');used.add(at);leafJoins++;return petioles[at];});assert.ok(distance(pair[0][0],pair[1][0])<eps,label+' opposite shared node');assert.ok(stems.some(line=>onSegment(pair[0][0],...line)<eps),label+' attached to own rendered stem');}
    if(s.bloom){openModels++;const anchor=g.userData.flowerTargets[0],surface=anchor.surface,mesh=g.children.find(m=>m.userData.component===surface.component);assert.equal(surface.component,petal);assert.ok(g.userData.surfaceSelection.matched,label+' visible indexed petal');maxSurfaceAttempts=Math.max(maxSurfaceAttempts,g.userData.surfaceSelection.attempts);mesh.getMatrixAt(surface.instanceId,matrix);const vertices=surface.vertices.map(j=>new Vector3().fromBufferAttribute(mesh.geometry.attributes.position,j).applyMatrix4(matrix)),centroid=vertices.reduce((n,p)=>n.add(p),new Vector3()).multiplyScalar(1/3);assert.ok(centroid.distanceTo(new Vector3(...anchor.origin))<2e-7,label+' exact indexed centroid');assert.deepEqual(surface.vertices,[0,1,2].map(j=>mesh.geometry.index.getX(surface.faceIndex*3+j)));g.position.set(-2,.012,-1);g.updateMatrixWorld(true);for(const aspect of[.8,1.65]){cameraPoses++;const pose=flowerInspectionView(g,aspect,40),camera=new PerspectiveCamera(40,aspect,.01,650);assert.ok(pose);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(hit=>{const z=-hit.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.equal(hit?.object.userData.component,surface.component,label+' first visible component');assert.equal(hit.instanceId,surface.instanceId,label+' first instance');assert.equal(hit.faceIndex,surface.faceIndex,label+' first triangle');assert.ok(hit.point.distanceTo(new Vector3(...pose.target))<2e-6,label+' unobstructed target');}}
    else assert.equal(flowerInspectionView(g,.8,40),null);assert.deepEqual(p,copy,label+' saved input stable');
   }finally{dispose(g);}
  }
 }
 assert.equal(models,38);assert.equal(openModels,26);assert.equal(cameraPoses,52);console.log('OPENING_ACT_843_BOUNDARIES '+JSON.stringify({models,actualVertices,leafJoins,openModels,cameraPoses,maxSurfaceAttempts}));
});
import {meadowTrifoliumPoint,bronzeArmeriaPoint,asclepiasPoint,parrotBranchTulipPoint,pinkRainLilyPoint,DOUBLE_TULIP_PROFILES,doubleTulipPoint,MINOR_TULIP_TYPES,minorTulipPoint,slenderTulipPoint,SINGLE_TULIP_PROFILES,singleTulipPoint,cannaReferencePoint,gardenAnemonePoint,alliumReferencePoint,daylilyReferencePoint,iridSpikePoint,irisReferencePoint,retailLilyPoint,freesiaReferencePoint,miniIrisPoint,hyacinthReferencePoint,narcissusCupPoint,nativeLilyPoint,martagonReferencePoint,narcissusReferencePoint,borderTulipPoint,retailTulipPoint,camassiaPoint,autumnCyclamenPoint,coumPoint,convallariaPoint,fritillariaPoint,spanishBluebellPoint,englishBluebellPoint,tecophilaeaPoint,acisPoint,fawnLilyPoint,earlySquillPoint,grapeHyacinthPoint,snowdropPoint,resedaPoint,acaenaPoint,chloranthusPoint,berzeliaPoint,asteliaPoint,convolvulusPoint,trainedVineSurfacePoint,eryngoSurfacePoint,soapwortPoint,balloonPoint,detailedFlower,drawDetailedHerb,fescueReferencePoint,otherCarexPoint,blueCarexPoint,fineCarexPoint,oshimensisPoint,ophiopogonPoint,liriopePoint,hakonechloaPoint,stipoidPoint,calamagrostisPoint,panicumPoint,tallEupatorieaePoint,muhlenbergiaPoint,eupatorieaePoint,aegopodiumPoint,ligulariaPoint,oxypetalumPoint,patriniaPoint,heleniumPoint,heliopsisPoint,echinopsPoint,oreganoPoint,swanAnemonePoint,echinaceaPoint,veronicaPoint,veronicastrumPoint,baptisiaPoint,BAPTISIA_PROFILES,tanacetumPoint,arctotisPoint,emperorDahliaPoint,darkDahliaPoint,decorativeDahliaPoint,maxiDahliaPoint,MAXI_DAHLIA_PROFILES,rudyPoint,eucomisPoint,paraneePoint,somekawaPoint,queenMoonPoint,moonCupGeometry,rustySagePoint,gardenBellPoint,coniferShootGeometry,CONIFER_SHOOTS,hamamelidPoint,syringaLeafPoint,camelliaLeafPoint,namedTreeSkeleton,roseLeafPoint,vincaPoint,syneilesisPoint,artichokePoint,dianthusPetalPoint,raggedRobinPoint} from '../site/plant-detail.js';
