test('Three white edge gold Hosta references preserve empty Latin unknown sizes and flower colours alongside twisted and round glossy leaves',()=>{
 const rows=[['p-659e689d5005',[.3,.4,.11],[.15,.22,.05],null,null,'hcBunLeafRef'],['p-a1e577c05179',[.55,.65,.36],[.28,.35,.17],null,null,'hcTwistAgainLeafRef'],['p-2bc7c62c71df',[.4,.6,.29],[.2,.32,.14],null,null,'hcLemonSnapLeafRef']];
 for(const [id,adult,small,h,w]of rows){assert.deepEqual(CATALOG[id].height,h);assert.deepEqual(CATALOG[id].spread,w);assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(CATALOG[id].bloomKnown,false);assert.match(CATALOG[id].appearance.sourceConflict,/未確認|確定でき/);}assert.equal(CATALOG[rows[0][0]].latin,'');assert.equal(CATALOG[rows[1][0]].latin,'');assert.equal(CATALOG[rows[0][0]].appearance.leafPattern,'margin');assert.equal(CATALOG[rows[1][0]].appearance.leafPattern,'margin');assert.equal(CATALOG[rows[2][0]].appearance.leafPattern,undefined);assert.equal(CATALOG[rows[1][0]].appearance.leafLength,undefined);assert.equal(CATALOG[rows[0][0]].appearance.flowerMonths,undefined);assert.deepEqual(CATALOG[rows[0][0]].bloom,[]);assert.deepEqual(CATALOG[rows[1][0]].appearance.flowerMonths,[6,7,8]);
 for(const [id,adult,small,h,w,shape]of rows)for(const size of [adult,small])for(let month=1;month<=12;month++){
  const p={...makePlant(id,51000,2,2),height:size[0],spread:size[1],leafHeight:size[2]},old=structuredClone(p),s=stateAt(p,view(month)),type=CATALOG[id].appearance.shootProfile;assert.equal(s.bloom,id==='p-a1e577c05179'?month>=6&&month<=8:id==='p-2bc7c62c71df'&&month>=5&&month<=8);assert.equal(s.groundDormant,[11,12,1,2,3].includes(month));assert.equal(s.seedHeads,false);assert.deepEqual(p,old);if(![1,4,5,6,7,8,9,10,11].includes(month))continue;
  const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component.startsWith(k)).reduce((n,m)=>n+m.count,0);try{if(s.groundDormant)assert.equal(g.children.length,0);else{assert.equal(g.userData.architecture,'hostaCultivarReferences');assert.ok(count('blade-hosta-ref-'+type)>0);assert.equal(count('petiole-hosta-ref-'),count('blade-hosta-ref-'));assert.equal(count('corolla-hosta-ref-')>0,s.bloom);assert.equal(count('anther-hosta-ref'),count('corolla-hosta-ref-')*6);assert.equal(count('style-hosta-ref'),count('corolla-hosta-ref-'));assert.equal(count('bract-hosta-ref'),count('scape-hosta-ref-')*9);
   const blade=g.children.find(m=>m.userData.component.startsWith('blade-hosta-ref-'));assert.equal(blade.geometry.userData.hostaCultivarOrgan,shape);const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};blade.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/hcEdgeGoldVein/);assert.equal(shader.fragmentShader.includes('hcEdgeGoldMask'),type!=='lemonSnap');assert.ok(!shader.fragmentShader.includes('\\n'));if(type==='buntyoukou')assert.ok(!g.children.some(m=>/corolla|scape|bud|anther|style/.test(m.userData.component)));if(type==='lemonSnap'){const petiole=g.children.find(m=>m.userData.component.startsWith('petiole-hosta-ref-')),col=new Color();petiole.getColorAt(0,col);assert.equal(col.getHexString(),'98505c');}}
   assert.equal(!!g.userData.flowerTargets?.length,s.bloom);assert.equal(inspectionSeasonActive(p,view(month)),s.bloom);assert.ok(!g.children.some(m=>/seed|fruit|glume|awn/.test(m.userData.component)));for(const m of g.children)for(const a of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok(a.every(Number.isFinite));}finally{dispose(g);}
 }
});
