test('Three white variegated Hosta references keep compact stable centres broad island leaves and strong early yellow margins',()=>{
 const rows=[['p-8d513f95eb98',[.45,.45,.27],[.22,.25,.13],[.4,.5],[.4,.5],'hcLoyalLeafRef'],['p-b7c0bc1d8703',[.35,.6,.27],[.18,.32,.13],[.3,.4],[.5,.7],'hcIslandLeafRef'],['p-f31ac2c9e2a2',[.35,.6,.25],[.18,.3,.12],[.3,.4],[.4,.7],'hcGlacierLeafRef']];
 for(const [id,adult,small,h,w]of rows){assert.deepEqual(CATALOG[id].height,h);assert.deepEqual(CATALOG[id].spread,w);assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(CATALOG[id].bloomKnown,false);assert.match(CATALOG[id].appearance.sourceConflict,/花丈/);}assert.equal(CATALOG[rows[0][0]].appearance.leafPattern,'center');assert.equal(CATALOG[rows[1][0]].appearance.leafPattern,'center');assert.equal(CATALOG[rows[2][0]].appearance.leafPattern,'margin');assert.equal(CATALOG[rows[1][0]].appearance.monthlyPatternColors[4],'#e0dda2');assert.equal(CATALOG[rows[1][0]].appearance.monthlyPatternColors[6],'#eeebd3');assert.equal(CATALOG[rows[2][0]].appearance.monthlyPatternColors[6],'#e1d681');assert.equal(CATALOG[rows[2][0]].appearance.monthlyPatternColors[8],'#ece6cd');
 for(const [id,adult,small,h,w,shape]of rows)for(const size of [adult,small])for(let month=1;month<=12;month++){
  const p={...makePlant(id,50400,2,2),height:size[0],spread:size[1],leafHeight:size[2]},old=structuredClone(p),s=stateAt(p,view(month)),type=CATALOG[id].appearance.shootProfile;assert.equal(s.bloom,month>=5&&month<=8);assert.equal(s.groundDormant,[11,12,1,2,3].includes(month));assert.equal(s.seedHeads,false);assert.deepEqual(p,old);if(![1,4,5,6,7,8,9,10,11].includes(month))continue;
  const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component.startsWith(k)).reduce((n,m)=>n+m.count,0);try{if(s.groundDormant)assert.equal(g.children.length,0);else{assert.equal(g.userData.architecture,'hostaCultivarReferences');assert.ok(count('blade-hosta-ref-'+type)>0);assert.equal(count('petiole-hosta-ref-'),count('blade-hosta-ref-'));assert.equal(count('corolla-hosta-ref-')>0,s.bloom);assert.equal(count('anther-hosta-ref'),count('corolla-hosta-ref-')*6);assert.equal(count('style-hosta-ref'),count('corolla-hosta-ref-'));assert.equal(count('bract-hosta-ref'),count('scape-hosta-ref-')*9);
   const blade=g.children.find(m=>m.userData.component.startsWith('blade-hosta-ref-'));assert.equal(blade.geometry.userData.hostaCultivarOrgan,shape);const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};blade.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/hcWhiteVein/);assert.equal(shader.fragmentShader.includes('hcWhiteEdge'),true);assert.ok(!shader.fragmentShader.includes('\\n'));if(type==='loyalist'&&s.bloom){const scape=g.children.find(m=>m.userData.component.startsWith('scape-hosta-ref-')),col=new Color();scape.getColorAt(0,col);assert.equal(col.getHexString(),'b58e90');}if(type==='valleysGlacier')assert.ok(shader.fragmentShader.includes(month<=6?'vec3(.74,.67,.30)':month===7?'vec3(.82,.77,.48)':'vec3(.86,.84,.73)'));}
   assert.equal(!!g.userData.flowerTargets?.length,s.bloom);assert.equal(inspectionSeasonActive(p,view(month)),s.bloom);assert.ok(!g.children.some(m=>/seed|fruit|glume|awn/.test(m.userData.component)));for(const m of g.children)for(const a of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok(a.every(Number.isFinite));}finally{dispose(g);}
 }
});
