test('Released Hosta leaf petioles and flower scapes retain visible radius above ground',()=>{
 const rows=[["p-7a7602c87348",[0.35,0.7,0.18],[0.18,0.35,0.09]],["p-f241568e8fcf",[0.8,1.1,0.52],[0.35,0.55,0.24]],["p-62dbb3f12caa",[0.35,0.6,0.23],[0.18,0.3,0.12]],["p-a579fca3590c",[0.55,0.6,0.3],[0.25,0.3,0.14]],["p-8094c4f1d466",[0.35,0.6,0.23],[0.18,0.3,0.12]],["p-2966c4337e4a",[0.55,1,0.4],[0.25,0.5,0.18]],["p-444ac337c553",[0.35,0.5,0.25],[0.18,0.3,0.12]],["p-68ad3901f2d9",[0.8,0.5,0.3],[0.35,0.3,0.15]],["p-34896a3ab98a",[0.7,0.9,0.45],[0.3,0.45,0.2]],["p-e20f41ad372b",[0.5,0.75,0.34],[0.25,0.4,0.16]],["p-56fc0d54e567",[0.4,0.65,0.25],[0.2,0.35,0.12]],["p-055d5475615a",[0.5,0.9,0.32],[0.25,0.45,0.16]],["p-2ef58e6ebbc0",[0.35,0.6,0.23],[0.18,0.3,0.12]],["p-d7725e5d46dc",[0.35,0.6,0.23],[0.18,0.3,0.12]],["p-9ba43ad256b8",[0.35,0.6,0.23],[0.18,0.3,0.12]],["p-2cc0b4b5f9b7",[0.25,0.4,0.17],[0.13,0.22,0.08]],["p-03614cb3183b",[0.55,0.5,0.31],[0.25,0.28,0.14]],["p-f1fe838a9c09",[0.45,0.7,0.29],[0.22,0.35,0.14]]];
 for(const [kind,adult,small]of rows)for(const size of [adult,small]){const p={...makePlant(kind,50390,2,2),height:size[0],spread:size[1],leafHeight:size[2]},before=structuredClone(p),g=plantModel(p,view(6)),mat=new Matrix4();try{assert.equal(g.userData.architecture,'hostaCultivarReferences');for(const [prefix,minRadius]of [['petiole-hosta-ref-',.0005],['scape-hosta-ref-',.0003]]){const mesh=g.children.find(m=>m.userData.component.startsWith(prefix));assert.ok(mesh&&mesh.count>0,kind+' '+prefix);mesh.getMatrixAt(0,mat);assert.ok(Math.hypot(mat.elements[0],mat.elements[1],mat.elements[2])>minRadius,kind+' '+size+' '+prefix+' collapsed at ground');}assert.deepEqual(p,before);}finally{dispose(g);}const winter=plantModel(p,view(1));try{assert.equal(winter.children.length,0);}finally{dispose(winter);}}
});
