test('Three season-changing Hosta independent tiny dimensions bound actual leaf ribs flower tubes and scapes',()=>{
 for(const id of ['p-95ef4d4f4911','p-8993e03dc3df','p-1d8c7d9a1f0b'])for(const size of [[.005,.08,.005],[.12,.005,.005],[.7,.8,.005]])for(const month of (id==='p-1d8c7d9a1f0b'?[5,6,1]:[6,1])){
  const p={...makePlant(id,50299,2,2),height:size[0],spread:size[1],leafHeight:size[2]},g=plantModel(p,view(month)),mat=new Matrix4(),v=new Vector3();try{let leafMax=0;for(const m of g.children){const pos=m.geometry.attributes.position;for(let k=0;k<m.count;k++){m.getMatrixAt(k,mat);for(let j=0;j<pos.count;j++){v.set(pos.getX(j),pos.getY(j),pos.getZ(j)).applyMatrix4(mat);assert.ok(v.toArray().every(Number.isFinite));assert.ok(v.y>=-1e-7&&v.y<=p.height*1.05+.00001,id+' '+size+' '+month+' height '+m.userData.component+' '+v.y);assert.ok(Math.hypot(v.x,v.z)<=p.spread*.54+.00001,id+' '+size+' '+month+' footprint '+m.userData.component+' '+Math.hypot(v.x,v.z));if(/^(blade|petiole)-hosta-ref/.test(m.userData.component))leafMax=Math.max(leafMax,v.y);}}}assert.ok(leafMax<=.005001,'leaf ceiling '+id+' '+size+' '+month+' '+leafMax);}finally{dispose(g);}
 }
});
test('Three season-changing Hosta macro cameras target a rendered corolla surface above the leaf mass',()=>{
 for(const [id,adult,small]of [['p-95ef4d4f4911',[.35,.35,.22],[.18,.20,.11]],['p-8993e03dc3df',[.175,.35,.11],[.09,.20,.05]],['p-1d8c7d9a1f0b',[.55,.6,.31],[.25,.3,.14]]])for(const size of [adult,small]){
  const p={...makePlant(id,50290,2,2),height:size[0],spread:size[1],leafHeight:size[2]},g=plantModel(p,view(6));try{g.updateMatrixWorld(true);const pose=flowerInspectionView(g,.8,40);assert.ok(pose);assert.ok(pose.position[1]>0);const camera=new PerspectiveCamera(40,.8,.0001,100);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObjects(g.children,false)[0];assert.ok(hit,id+' '+size+' no hit');assert.match(hit.object.userData.component,/^corolla-hosta-ref-/,id+' '+size+' hit '+hit.object.userData.component);}finally{dispose(g);}
 }
});
test('Three contrasting Hosta references distinguish changing centres giant leaves and long upright petioles with silver undersides',()=>{
 const rows=[['p-9715b3ec6ca7',[.4,.7,.27],[.2,.35,.13],[.3,.5],[.6,.8],'hcFruitLeafRef'],['p-a8b7f9f1e81c',[.8,1.5,.58],[.4,.8,.28],[.7,.9],[1.2,1.8],'hcEarthLeafRef'],['p-13988b85d68f',[.7,.85,.52],[.3,.45,.23],[.6,.8],[.7,1],'hcRegalLeafRef']];
 for(const [id,adult,small,h,w]of rows){assert.deepEqual(CATALOG[id].height,h);assert.deepEqual(CATALOG[id].spread,w);assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(CATALOG[id].bloomKnown,false);assert.match(CATALOG[id].appearance.sourceConflict,/花丈/);}assert.equal(CATALOG[rows[0][0]].appearance.leafPattern,'center');assert.equal(CATALOG[rows[1][0]].appearance.leafPattern,'margin');assert.equal(CATALOG[rows[2][0]].appearance.leafPattern,'margin');assert.match(CATALOG[rows[2][0]].latin,/Regal Splender/);assert.match(CATALOG[rows[2][0]].appearance.sourceConflict,/Regal Splendor/);assert.equal(CATALOG[rows[1][0]].appearance.leafLength,.375);
 for(const [id,adult,small,h,w,shape]of rows)for(const size of [adult,small])for(let month=1;month<=12;month++){
  const p={...makePlant(id,50100,2,2),height:size[0],spread:size[1],leafHeight:size[2]},old=structuredClone(p),s=stateAt(p,view(month)),type=CATALOG[id].appearance.shootProfile;assert.equal(s.bloom,month>=5&&month<=8);assert.equal(s.groundDormant,[11,12,1,2,3].includes(month));assert.equal(s.seedHeads,false);assert.deepEqual(p,old);if(![1,4,5,6,9,10,11].includes(month))continue;
  const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component.startsWith(k)).reduce((n,m)=>n+m.count,0);try{if(s.groundDormant)assert.equal(g.children.length,0);else{assert.equal(g.userData.architecture,'hostaCultivarReferences');assert.ok(count('blade-hosta-ref-'+type)>0);assert.equal(count('petiole-hosta-ref-'),count('blade-hosta-ref-'));assert.equal(count('corolla-hosta-ref-')>0,s.bloom);assert.equal(count('anther-hosta-ref'),count('corolla-hosta-ref-')*6);assert.equal(count('style-hosta-ref'),count('corolla-hosta-ref-'));assert.equal(count('bract-hosta-ref'),count('scape-hosta-ref-')*9);
   const blade=g.children.find(m=>m.userData.component.startsWith('blade-hosta-ref-'));assert.equal(blade.geometry.userData.hostaCultivarOrgan,shape);const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};blade.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/hcContrastVein/);assert.equal(shader.fragmentShader.includes('hcContrastEdge'),true);assert.ok(!shader.fragmentShader.includes('\\n'));assert.equal(shader.fragmentShader.includes('!gl_FrontFacing'),type==='regalSplendor');if(type==='regalSplendor'){let top=0;const mat=new Matrix4(),v=new Vector3();for(const mesh of g.children.filter(m=>m.userData.component.startsWith('petiole-hosta-ref-'))){const pos=mesh.geometry.attributes.position;for(let k=0;k<mesh.count;k++){mesh.getMatrixAt(k,mat);for(let j=0;j<pos.count;j++){v.set(pos.getX(j),pos.getY(j),pos.getZ(j)).applyMatrix4(mat);top=Math.max(top,v.y);}}}assert.ok(top>p.leafHeight*s.leafScale*.68);}}
   if(!s.groundDormant){const petiole=g.children.find(m=>m.userData.component.startsWith('petiole-hosta-ref-')),shaft=new Matrix4();petiole.getMatrixAt(0,shaft);assert.ok(Math.hypot(shaft.elements[0],shaft.elements[1],shaft.elements[2])>.0005,'petiole must remain visible above the ground boundary');if(s.bloom){const scape=g.children.find(m=>m.userData.component.startsWith('scape-hosta-ref-'));scape.getMatrixAt(0,shaft);assert.ok(Math.hypot(shaft.elements[0],shaft.elements[1],shaft.elements[2])>.0003,'scape must not collapse at ground contact');}}assert.equal(!!g.userData.flowerTargets?.length,s.bloom);assert.equal(inspectionSeasonActive(p,view(month)),s.bloom);assert.ok(!g.children.some(m=>/seed|fruit|glume|awn/.test(m.userData.component)));for(const m of g.children)for(const a of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok(a.every(Number.isFinite));}finally{dispose(g);}
 }
});
