test('Three pale centre Hosta references preserve white centres upright leaves pale scapes and autumn edge colour',()=>{
 const rows=[['p-2cc0b4b5f9b7',[.25,.4,.17],[.13,.22,.08],[.2,.3],[.3,.5],'hcRememberLeafRef'],['p-03614cb3183b',[.55,.5,.31],[.25,.28,.14],[.45,.6],[.4,.6],'hcIceLeafRef'],['p-f1fe838a9c09',[.45,.7,.29],[.22,.35,.14],[.4,.5],[.6,.8],'hcCandyLeafRef']];
 for(const [id,adult,small,h,w]of rows){assert.deepEqual(CATALOG[id].height,h);assert.deepEqual(CATALOG[id].spread,w);assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(CATALOG[id].bloomKnown,false);assert.match(CATALOG[id].appearance.sourceConflict,/花丈/);}for(const [id]of rows)assert.equal(CATALOG[id].appearance.leafPattern,'center');assert.equal(CATALOG[rows[0][0]].appearance.monthlyPatternColors[4],'#e8dd8b');assert.equal(CATALOG[rows[0][0]].appearance.monthlyPatternColors[6],'#ede8cf');assert.equal(CATALOG[rows[1][0]].appearance.monthlyPatternColors[4],'#eeeddf');assert.equal(CATALOG[rows[2][0]].appearance.monthlyLeafColors[10],'#c3ad67');
 for(const [id,adult,small,h,w,shape]of rows)for(const size of [adult,small])for(let month=1;month<=12;month++){
  const p={...makePlant(id,50000,2,2),height:size[0],spread:size[1],leafHeight:size[2]},old=structuredClone(p),s=stateAt(p,view(month)),type=CATALOG[id].appearance.shootProfile;assert.equal(s.bloom,month>=5&&month<=8);assert.equal(s.groundDormant,[11,12,1,2,3].includes(month));assert.equal(s.seedHeads,false);assert.deepEqual(p,old);if(![1,4,5,6,9,10,11].includes(month))continue;
  const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component.startsWith(k)).reduce((n,m)=>n+m.count,0);try{if(s.groundDormant)assert.equal(g.children.length,0);else{assert.equal(g.userData.architecture,'hostaCultivarReferences');assert.ok(count('blade-hosta-ref-'+type)>0);assert.equal(count('petiole-hosta-ref-'),count('blade-hosta-ref-'));assert.equal(count('corolla-hosta-ref-')>0,s.bloom);assert.equal(count('anther-hosta-ref'),count('corolla-hosta-ref-')*6);assert.equal(count('style-hosta-ref'),count('corolla-hosta-ref-'));assert.equal(count('bract-hosta-ref'),count('scape-hosta-ref-')*9);
   const blade=g.children.find(m=>m.userData.component.startsWith('blade-hosta-ref-'));assert.equal(blade.geometry.userData.hostaCultivarOrgan,shape);const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};blade.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/hcPaleVein/);assert.equal(shader.fragmentShader.includes('hcPaleEdge'),true);assert.ok(!shader.fragmentShader.includes('\\n'));if(type==='fireAndIce'&&s.bloom){const scape=g.children.find(m=>m.userData.component.startsWith('scape-hosta-ref-')),col=new Color();scape.getColorAt(0,col);assert.equal(col.getHexString(),'e2dfcc');}if(type==='christmasCandy'&&month===10)assert.match(shader.fragmentShader,/vec3\(.65,.56,.19\)/);}
   assert.equal(!!g.userData.flowerTargets?.length,s.bloom);assert.equal(inspectionSeasonActive(p,view(month)),s.bloom);assert.ok(!g.children.some(m=>/seed|fruit|glume|awn/.test(m.userData.component)));for(const m of g.children)for(const a of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok(a.every(Number.isFinite));}finally{dispose(g);}
 }
});
