 for(const [id,adult,small,h,w]of rows){assert.deepEqual(CATALOG[id].height,h);assert.deepEqual(CATALOG[id].spread,w);assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(CATALOG[id].bloomKnown,false);assert.match(CATALOG[id].appearance.sourceConflict,/花丈/);}for(const [id]of rows)assert.equal(CATALOG[id].appearance.leafPattern,'margin');assert.equal(CATALOG[rows[1][0]].appearance.monthlyPatternColors[6],'#eeead6');assert.equal(CATALOG[rows[2][0]].appearance.monthlyPatternColors[6],'#dfd37e');assert.equal(CATALOG[rows[2][0]].appearance.monthlyPatternColors[7],'#e7dfaa');assert.equal(CATALOG[rows[2][0]].appearance.monthlyPatternColors[9],'#efebd7');
