test('Three fragrant and centre Hosta references distinguish large white flowers seasonal central colour and spring leaf waves',()=>{
 const rows=[['p-e20f41ad372b',[.5,.75,.34],[.25,.4,.16],[.4,.6],[.6,.9],'hcFragrantLeafRef'],['p-56fc0d54e567',[.4,.65,.25],[.2,.35,.12],[.3,.5],[.5,.8],'hcStainedLeafRef'],['p-055d5475615a',[.5,.9,.32],[.25,.45,.16],[.4,.6],[.8,1],'hcGreatLeafRef']];
 for(const [id,adult,small,h,w]of rows){assert.deepEqual(CATALOG[id].height,h);assert.deepEqual(CATALOG[id].spread,w);assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(CATALOG[id].bloomKnown,false);assert.match(CATALOG[id].appearance.sourceConflict,/花丈/);}assert.equal(CATALOG[rows[0][0]].appearance.leafPattern,'margin');assert.equal(CATALOG[rows[1][0]].appearance.leafPattern,'center');assert.equal(CATALOG[rows[2][0]].appearance.leafPattern,'center');assert.equal(CATALOG[rows[1][0]].appearance.leafTexture,'glossy');assert.match(CATALOG[rows[2][0]].appearance.sourceConflict,/自然変異/);assert.equal(CATALOG[rows[0][0]].appearance.monthlyPatternColors[4],'#e7df98');assert.equal(CATALOG[rows[0][0]].appearance.monthlyPatternColors[6],'#eeedda');assert.equal(CATALOG[rows[2][0]].appearance.monthlyPatternColors[6],'#e1e4c4');
 for(const [id,adult,small,h,w,shape]of rows)for(const size of [adult,small])for(let month=1;month<=12;month++){
  const p={...makePlant(id,49800,2,2),height:size[0],spread:size[1],leafHeight:size[2]},old=structuredClone(p),s=stateAt(p,view(month)),type=CATALOG[id].appearance.shootProfile;assert.equal(s.bloom,month>=5&&month<=8);assert.equal(s.groundDormant,[11,12,1,2,3].includes(month));assert.equal(s.seedHeads,false);assert.deepEqual(p,old);if(![1,4,5,6,9,10,11].includes(month))continue;
  const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component.startsWith(k)).reduce((n,m)=>n+m.count,0);try{if(s.groundDormant)assert.equal(g.children.length,0);else{assert.equal(g.userData.architecture,'hostaCultivarReferences');assert.ok(count('blade-hosta-ref-'+type)>0);assert.equal(count('petiole-hosta-ref-'),count('blade-hosta-ref-'));assert.equal(count('corolla-hosta-ref-')>0,s.bloom);assert.equal(count('anther-hosta-ref'),count('corolla-hosta-ref-')*6);assert.equal(count('style-hosta-ref'),count('corolla-hosta-ref-'));assert.equal(count('bract-hosta-ref'),count('scape-hosta-ref-')*9);
   const blade=g.children.find(m=>m.userData.component.startsWith('blade-hosta-ref-'));assert.equal(blade.geometry.userData.hostaCultivarOrgan,type==='greatExpectations'&&month<=5?'hcGreatSpringLeafRef':shape);const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};blade.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/hcFragrantVein/);assert.equal(shader.fragmentShader.includes('hcFragrantEdge'),true);assert.ok(!shader.fragmentShader.includes('\\n'));}
   assert.equal(!!g.userData.flowerTargets?.length,s.bloom);assert.equal(inspectionSeasonActive(p,view(month)),s.bloom);assert.ok(!g.children.some(m=>/seed|fruit|glume|awn/.test(m.userData.component)));for(const m of g.children)for(const a of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok(a.every(Number.isFinite));}finally{dispose(g);}
 }
});
test('Three fragrant-centre Hosta independent tiny dimensions bound actual leaf ribs flower tubes and scapes',()=>{
 for(const id of ['p-e20f41ad372b','p-56fc0d54e567','p-055d5475615a'])for(const size of [[.005,.08,.005],[.12,.005,.005],[.7,.8,.005]])for(const month of [6,1]){
  const p={...makePlant(id,49899,2,2),height:size[0],spread:size[1],leafHeight:size[2]},g=plantModel(p,view(month)),mat=new Matrix4(),v=new Vector3();try{let leafMax=0;for(const m of g.children){const pos=m.geometry.attributes.position;for(let k=0;k<m.count;k++){m.getMatrixAt(k,mat);for(let j=0;j<pos.count;j++){v.set(pos.getX(j),pos.getY(j),pos.getZ(j)).applyMatrix4(mat);assert.ok(v.toArray().every(Number.isFinite));assert.ok(v.y>=-1e-7&&v.y<=p.height*1.05+.00001,id+' '+size+' '+month+' height '+m.userData.component+' '+v.y);assert.ok(Math.hypot(v.x,v.z)<=p.spread*.54+.00001,id+' '+size+' '+month+' footprint '+m.userData.component+' '+Math.hypot(v.x,v.z));if(/^(blade|petiole)-hosta-ref/.test(m.userData.component))leafMax=Math.max(leafMax,v.y);}}}assert.ok(leafMax<=.005001,'leaf ceiling '+id+' '+size+' '+month+' '+leafMax);}finally{dispose(g);}
 }
});
test('Three fragrant-centre Hosta macro cameras target a rendered corolla surface above the leaf mass',()=>{
 for(const [id,adult,small]of [['p-e20f41ad372b',[.5,.75,.34],[.25,.4,.16]],['p-56fc0d54e567',[.4,.65,.25],[.2,.35,.12]],['p-055d5475615a',[.5,.9,.32],[.25,.45,.16]]])for(const size of [adult,small]){
  const p={...makePlant(id,49890,2,2),height:size[0],spread:size[1],leafHeight:size[2]},g=plantModel(p,view(6));try{g.updateMatrixWorld(true);const pose=flowerInspectionView(g,.8,40);assert.ok(pose);assert.ok(pose.position[1]>0);const camera=new PerspectiveCamera(40,.8,.0001,100);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObjects(g.children,false)[0];assert.ok(hit,id+' '+size+' no hit');assert.match(hit.object.userData.component,/^corolla-hosta-ref-/,id+' '+size+' hit '+hit.object.userData.component);}finally{dispose(g);}
 }
});
test('Three red and gold Hosta references preserve lime-yellow summer leaves red petioles and broad stable margins',()=>{
 const rows=[['p-444ac337c553',[.35,.5,.25],[.18,.3,.12],[.3,.4],[.4,.6],'hcFireLeafRef'],['p-68ad3901f2d9',[.8,.5,.3],[.35,.3,.15],[.7,.9],[.4,.6],'hcBrimLeafRef'],['p-34896a3ab98a',[.7,.9,.45],[.3,.45,.20],[.6,.8],[.8,1],'hcLibertyLeafRef']];
 for(const [id,adult,small,h,w]of rows){assert.deepEqual(CATALOG[id].height,h);assert.deepEqual(CATALOG[id].spread,w);assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(CATALOG[id].bloomKnown,false);assert.match(CATALOG[id].appearance.sourceConflict,/花丈/);}assert.equal(CATALOG[rows[0][0]].appearance.leafPattern,undefined);assert.equal(CATALOG[rows[0][0]].variegated,false);assert.equal(CATALOG[rows[1][0]].appearance.leafPattern,'margin');assert.equal(CATALOG[rows[2][0]].appearance.leafPattern,'margin');assert.equal(CATALOG[rows[0][0]].appearance.monthlyLeafColors[6],'#c8d778');assert.equal(CATALOG[rows[0][0]].appearance.monthlyLeafColors[4],'#e1dc68');assert.match(CATALOG[rows[2][0]].appearance.sourceConflict,/上限は未確認/);
 for(const [id,adult,small,h,w,shape]of rows)for(const size of [adult,small])for(let month=1;month<=12;month++){
  const p={...makePlant(id,49700,2,2),height:size[0],spread:size[1],leafHeight:size[2]},old=structuredClone(p),s=stateAt(p,view(month)),type=CATALOG[id].appearance.shootProfile;assert.equal(s.bloom,month>=5&&month<=8);assert.equal(s.groundDormant,[11,12,1,2,3].includes(month));assert.equal(s.seedHeads,false);assert.deepEqual(p,old);if(![1,4,5,6,9,10,11].includes(month))continue;
  const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component.startsWith(k)).reduce((n,m)=>n+m.count,0);try{if(s.groundDormant)assert.equal(g.children.length,0);else{assert.equal(g.userData.architecture,'hostaCultivarReferences');assert.ok(count('blade-hosta-ref-'+type)>0);assert.equal(count('petiole-hosta-ref-'),count('blade-hosta-ref-'));assert.equal(count('corolla-hosta-ref-')>0,s.bloom);assert.equal(count('anther-hosta-ref'),count('corolla-hosta-ref-')*6);assert.equal(count('style-hosta-ref'),count('corolla-hosta-ref-'));assert.equal(count('bract-hosta-ref'),count('scape-hosta-ref-')*9);
   const blade=g.children.find(m=>m.userData.component.startsWith('blade-hosta-ref-'));assert.equal(blade.geometry.userData.hostaCultivarOrgan,shape);const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};blade.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/hcGoldVein/);assert.equal(shader.fragmentShader.includes('hcGoldEdge'),type!=='fireIsland');assert.ok(!shader.fragmentShader.includes('\\n'));if(type==='fireIsland'){const petiole=g.children.find(m=>m.userData.component.startsWith('petiole-hosta-ref-'));const red=new Color();petiole.getColorAt(0,red);assert.equal(red.getHexString(),'98555e');}}
   assert.equal(!!g.userData.flowerTargets?.length,s.bloom);assert.equal(inspectionSeasonActive(p,view(month)),s.bloom);assert.ok(!g.children.some(m=>/seed|fruit|glume|awn/.test(m.userData.component)));for(const m of g.children)for(const a of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok(a.every(Number.isFinite));}finally{dispose(g);}
 }
});
