test('Three Hosta macro cameras target a rendered corolla surface above the leaf mass',()=>{
 for(const [id,adult,small]of [['p-7a7602c87348',[.35,.7,.18],[.18,.35,.09]],['p-f241568e8fcf',[.8,1.1,.52],[.35,.55,.24]],['p-62dbb3f12caa',[.35,.6,.23],[.18,.3,.12]]])for(const size of [adult,small]){
  const p={...makePlant(id,49590,2,2),height:size[0],spread:size[1],leafHeight:size[2]},g=plantModel(p,view(6));try{g.updateMatrixWorld(true);const pose=flowerInspectionView(g,.8,40);assert.ok(pose);assert.ok(pose.position[1]>0);const camera=new PerspectiveCamera(40,.8,.0001,100);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObjects(g.children,false)[0];assert.ok(hit,id+' '+size+' no hit');assert.match(hit.object.userData.component,/^corolla-hosta-ref-/,id+' '+size+' hit '+hit.object.userData.component);}finally{dispose(g);}
 }
});
test('Three crested and eared fern references distinguish forked narrow pinnae variable crossing and warm winter leaves',()=>{
 const rows=[['p-873ade54edcb',[1,1.2,.92],[.4,.55,.34],[.8,1.2],[.8,1.5]],['p-1344e31f00e7',[.5,.6,.44],[.25,.35,.21],[.3,.6],[.4,.7]],['p-5697a5ead122',[.4,.5,.35],[.2,.3,.16],[.3,.5],[.4,.6]]];
 for(const [id,adult,small,h,w]of rows){assert.deepEqual(CATALOG[id].height,h);assert.deepEqual(CATALOG[id].spread,w);assert.equal(CATALOG[id].appearance.status,'partial');}
 assert.equal(CATALOG[rows[0][0]].latin,"Dryopteris filix-mas 'Linearis Polydactylon'");assert.match(CATALOG[rows[0][0]].appearance.sourceConflict,/Polydactyla/);assert.match(CATALOG[rows[1][0]].appearance.sourceConflict,/混在/);assert.match(CATALOG[rows[2][0]].appearance.sourceConflict,/推測/);
 for(const [id,adult,small]of rows)for(const size of [adult,small])for(let month=1;month<=12;month++){
  const p={...makePlant(id,49400,2,2),height:size[0],spread:size[1],leafHeight:size[2]},old=structuredClone(p),s=stateAt(p,view(month)),type=CATALOG[id].appearance.shootProfile;assert.equal(s.bloom,false);assert.equal(s.seedHeads,false);assert.equal(s.groundDormant,type!=='okanum'&&[12,1,2].includes(month));assert.equal(inspectionSeasonActive(p,view(month)),false);assert.match(s.timingBasis,/花をつけないシダ/);assert.deepEqual(p,old);if(![1,3,5,6,9,11].includes(month))continue;
  const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);try{if(s.groundDormant)assert.equal(g.children.length,0);else{assert.equal(g.userData.architecture,'crestedEaredFernReferences');
   if(type==='linearis'){assert.ok(count('pinnule-linearis')>0);assert.equal(count('pinnule-linearis'),count('pinna-axis-crested-linearis')*14);assert.equal(count('fork-pinna-linearis'),count('pinna-axis-crested-linearis')*6);assert.ok(count('crest-frond-linearis')>0);}
   else if(type==='victoriae'){assert.ok(count('pinna-victoriae-crossed')>0);assert.ok(count('pinna-victoriae-flat')>0);assert.equal(count('crest-pinna-victoriae'),(count('pinna-victoriae-crossed')+count('pinna-victoriae-flat'))*3);assert.ok(count('crest-frond-victoriae')>0);}
   else{assert.ok(count('pinnule-okanum')>0);assert.equal(count('pinnule-okanum'),count('pinna-axis-crested-okanum')*12);assert.equal(count('crest-frond-okanum'),0);assert.equal(g.children.find(m=>m.userData.component==='pinnule-okanum').material.roughness,.47);}}
   assert.equal(!!g.userData.flowerTargets?.length,false);assert.equal(flowerInspectionView(g,1,40),null);assert.ok(!g.children.some(m=>/petal|flower|anther|ovary|pollen|fruit|seed|glume|awn/.test(m.userData.component)));for(const m of g.children)for(const a of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok(a.every(Number.isFinite));
  }finally{dispose(g);}
 }
});
test('Three crested and eared fern independent tiny dimensions bound actual pinna forks lobes and axes',()=>{
 for(const id of ['p-873ade54edcb','p-1344e31f00e7','p-5697a5ead122'])for(const size of [[.005,.08,.005],[.12,.005,.005],[.7,.8,.005]])for(const month of [6,1]){
  const p={...makePlant(id,49499,2,2),height:size[0],spread:size[1],leafHeight:size[2]},g=plantModel(p,view(month)),mat=new Matrix4(),v=new Vector3();try{let leafMax=0;for(const m of g.children){const pos=m.geometry.attributes.position;for(let k=0;k<m.count;k++){m.getMatrixAt(k,mat);for(let j=0;j<pos.count;j++){v.set(pos.getX(j),pos.getY(j),pos.getZ(j)).applyMatrix4(mat);assert.ok(v.toArray().every(Number.isFinite));assert.ok(v.y>=-1e-7&&v.y<=p.height*1.05+.00001,id+' '+size+' '+month+' height '+m.userData.component+' '+v.y);assert.ok(Math.hypot(v.x,v.z)<=p.spread*.54+.00001,id+' '+size+' '+month+' footprint '+m.userData.component);leafMax=Math.max(leafMax,v.y);}}}assert.ok(leafMax<=.005001,'frond ceiling '+id+' '+size+' '+month+' '+leafMax);}finally{dispose(g);}
 }
});
test('Three painted fern profiles retain domestic dimensions silver gradients and red new-frond reference without flowers',()=>{
 const rows=[['p-86680c796bf4',[.28,.55,.25],[.15,.3,.12]],['p-02374b6a8a96',[.28,.55,.25],[.15,.3,.12]],['p-1ae79dc9da12',[.28,.55,.25],[.15,.3,.12]]];for(const [id]of rows){assert.deepEqual(CATALOG[id].height,[.2,.3]);assert.deepEqual(CATALOG[id].spread,[.4,.6]);assert.equal(CATALOG[id].appearance.status,'partial');}assert.equal(CATALOG[rows[0][0]].latin,"Athyrium niponicum 'Ghost'");assert.match(CATALOG[rows[0][0]].appearance.sourceConflict,/交雑/);
 for(const [id,...sizes]of rows)for(const size of sizes)for(let month=1;month<=12;month++){
  const p={...makePlant(id,49300,2,2),height:size[0],spread:size[1],leafHeight:size[2]},old=structuredClone(p),s=stateAt(p,view(month)),type=CATALOG[id].appearance.shootProfile;assert.equal(s.bloom,false);assert.equal(s.seedHeads,false);assert.equal(s.groundDormant,[12,1,2].includes(month));assert.equal(inspectionSeasonActive(p,view(month)),false);assert.match(s.timingBasis,/花をつけないシダ/);assert.deepEqual(p,old);if(![1,3,5,6,9,11].includes(month))continue;const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component.startsWith(k)).reduce((n,m)=>n+m.count,0);try{if(s.groundDormant)assert.equal(g.children.length,0);else{assert.equal(g.userData.architecture,'paintedFernReferences');assert.ok(count('pinnule-painted-'+type)>0);assert.equal(count('pinnule-painted-'+type),count('pinna-axis-painted-'+type)*14);assert.equal(count('apical-pinnule-painted-'+type),count('rachis-painted-'+type)/20);const leaf=g.children.find(m=>m.userData.component.startsWith('pinnule-painted-')),shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};leaf.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/pfMid/);assert.match(shader.fragmentShader,/pfVein/);assert.ok(!shader.fragmentShader.includes('\\n'));if(type==='burgundy'){assert.ok(count('pinnule-painted-burgundy-fresh')>0);assert.ok(count('pinnule-painted-burgundy-mature')>0);}}
   assert.equal(!!g.userData.flowerTargets?.length,false);assert.equal(flowerInspectionView(g,1,40),null);assert.ok(!g.children.some(m=>/petal|flower|anther|ovary|pollen|fruit|seed|glume|awn/.test(m.userData.component)));for(const m of g.children)for(const a of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok(a.every(Number.isFinite));}finally{dispose(g);}
 }
});
