 for(const [id,...sizes]of rows)for(const size of sizes)for(let month=1;month<=12;month++){
  const p={...makePlant(id,49200,2,2),height:size[0],spread:size[1],leafHeight:size[2]},old=structuredClone(p),s=stateAt(p,view(month)),type=CATALOG[id].appearance.shootProfile;assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(s.bloom,false);assert.equal(s.seedHeads,false);assert.equal(s.groundDormant,[12,1,2].includes(month));assert.equal(inspectionSeasonActive(p,view(month)),false);assert.match(s.timingBasis,/花をつけないシダ/);assert.deepEqual(p,old);if(![1,3,5,6,9,11].includes(month))continue;const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);try{if(s.groundDormant)assert.equal(g.children.length,0);else{assert.equal(g.userData.architecture,'athyriumFormReferences');if(type==='goldenVidalii'){assert.ok(count('pinnule-vidalii')>0);assert.equal(count('pinnule-vidalii'),count('pinna-axis-athyrium-goldenVidalii')*14);}else if(type==='dagger'){assert.ok(count('pinna-dagger')>0);assert.equal(count('crest-pinna-dagger'),count('pinna-dagger')*3);assert.ok(count('crest-frond-dagger')>0);assert.equal(count('pinna-frizelliae'),0);}else{assert.ok(count('pinna-frizelliae')>0);assert.equal(count('pinna-frizelliae')/36,count('rachis-athyrium-frizelliae')/20);assert.equal(count('pinna-axis-athyrium-frizelliae'),0);}}assert.equal(!!g.userData.flowerTargets?.length,false);assert.equal(flowerInspectionView(g,1,40),null);assert.ok(!g.children.some(m=>/petal|flower|anther|ovary|pollen|fruit|seed|glume|awn/.test(m.userData.component)));for(const m of g.children)for(const a of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok(a.every(Number.isFinite));}finally{dispose(g);}
 }
