     assert.equal(count('bract-jacobaea-woolly'),heads*12,tag);assert.equal(count('supplementary-bract-jacobaea'),heads*4,tag);
     assert.ok(!g.children.some(m=>/fruit|seed|pappus/.test(m.userData.component||'')),tag);
