    const petals=g.children.filter(m=>m.userData.component.startsWith('petal-rose-campion'));assert.equal(petals.length>0,[3,4,5,6].includes(month));
    if(petals.length){assert.ok(petals.every(m=>index?m.geometry.userData.roseCampionDoublePetal:m.geometry.userData.roseCampionSinglePetal));const count=petals.reduce((n,m)=>n+m.count,0),calyx=g.children.find(m=>m.userData.component==='calyx-rose-campion'),buds=g.children.find(m=>m.userData.component==='bud-rose-campion');assert.equal(count,(calyx.count-(buds?.count||0))*(index?32:5));if(!index){assert.equal(g.children.find(m=>m.userData.component==='filament-rose-campion').count,count*2);assert.equal(g.children.find(m=>m.userData.component==='style-rose-campion').count,count);assert.equal(g.children.find(m=>m.userData.component==='appendage-rose-campion').count,count*2);}}
