test('Linaria keeps spurred bilabiate racemes and replaces winter flower stems with basal shoots',()=>{
 const ids=['p-09ed8dd7efa0','p-09efc8a12a41','p-4b3b0014747e'];
 const colours=['#9474ad','#d99aaa','#ece8d8'];
 for(const [i,id] of ids.entries()){
  const info=CATALOG[id],a=info.appearance,p=makePlant(id,17200+i,1,1);p.height=i?.6:.7;p.spread=.3;p.leafHeight=p.height*.65;
  assert.equal(a.status,'partial');assert.equal(a.architecture,'linariaRacemes');assert.equal(info.flower,colours[i]);
  assert.deepEqual(a.flowerMonths,info.bloom);assert.deepEqual(info.bloom,i===2?[5,6,7,8,9,10,11]:[5,6]);
  assert.ok(a.unconfirmed.some(x=>x.includes('実測')));assert.ok(a.unconfirmed.some(x=>x.includes('冬')));assert.ok(a.unconfirmed.some(x=>x.includes('内部器官')));
  assert.ok(a.leafWidth/a.leafLength<.15);assert.ok(a.flowerLength<=.015);
  let winterLeaves=0,summerLeaves=0;
  const checkBounds=g=>{
   for(const mesh of g.children){
    assert.ok([...mesh.instanceMatrix.array].every(Number.isFinite));assert.ok([...mesh.geometry.attributes.position.array].every(Number.isFinite));assert.ok([...mesh.geometry.attributes.normal.array].every(Number.isFinite));
    mesh.computeBoundingBox();for(const axis of ['x','y','z']){assert.ok(Number.isFinite(mesh.boundingBox.min[axis]));assert.ok(Number.isFinite(mesh.boundingBox.max[axis]));}
    assert.ok(mesh.boundingBox.min.y>=-.006);assert.ok(mesh.boundingBox.max.y<=p.height*1.10);
    assert.ok(Math.max(Math.abs(mesh.boundingBox.min.x),Math.abs(mesh.boundingBox.max.x),Math.abs(mesh.boundingBox.min.z),Math.abs(mesh.boundingBox.max.z))<p.spread*.70);
   }
  };
  for(let month=1;month<=12;month++){
   const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),winter=[12,1,2].includes(month),flowers=count('corolla-linaria');
   assert.equal(g.userData.architecture,'linariaRacemes');assert.equal(g.scale.x,1);assert.equal(g.scale.y,1);assert.equal(seasonAt(info,month).shootScale,1);
   assert.ok(count('shoot-linaria-basal')>0);assert.ok(count('leaf-linaria-basal')>0);assert.equal(count('stem-linaria')>0,!winter);
   assert.equal(flowers>0,info.bloom.includes(month));assert.equal(count('raceme-linaria')>0,info.bloom.includes(month));
   assert.equal(count('spur-linaria'),flowers);assert.equal(count('petal-linaria-upper'),flowers);assert.equal(count('petal-linaria-lower'),flowers);assert.equal(count('sepal-linaria'),flowers*5);
   if(flowers){assert.ok(count('bud-linaria')>0);assert.ok(count('calyx-linaria-spent')>0);assert.ok(g.children.find(m=>m.userData.component==='spur-linaria').geometry.userData.linariaSpur);}
   const leaves=count('leaf-linaria')+count('leaf-linaria-basal');if(month===1)winterLeaves=leaves;if(month===6)summerLeaves=leaves;
   if(winter){assert.match(seasonAt(info,month).phase,/花茎なし.*仮表示.*未確認/);assert.equal(count('leaf-linaria'),0);for(const mesh of g.children){mesh.computeBoundingBox();assert.ok(mesh.boundingBox.max.y<p.height*.10);}}
   checkBounds(g);dispose(g);
  }
  assert.ok(winterLeaves<summerLeaves);
  let smallLeaves=0;
  for(const width of [.15,.6]){
   p.spread=width;const g=plantModel(p,view(6)),leaves=g.children.filter(m=>m.userData.component.startsWith('leaf-linaria')).reduce((n,m)=>n+m.count,0);
   if(width===.15)smallLeaves=leaves;else{assert.ok(leaves>smallLeaves);assert.ok(leaves<500);}
   checkBounds(g);dispose(g);
  }
 }
});
test('Lamium distinguishes compact Sterling shoots from Galeobdolon runners with paired leaves',()=>{
 const ids=['p-c309c35b2f9c','p-7084ea19721c'];
 for(const [i,id] of ids.entries()){
  const info=CATALOG[id],a=info.appearance,p=makePlant(id,17100+i,1,1);p.height=.2;p.spread=.42;p.leafHeight=.12;
  assert.equal(a.status,'partial');assert.equal(a.architecture,'lamiumRunners');assert.equal(a.arrangement,'opposite');assert.equal(info.variegated,true);
  assert.deepEqual(a.flowerMonths,info.bloom);assert.ok(a.unconfirmed.some(x=>x.includes('実測')));assert.ok(a.unconfirmed.some(x=>x.includes('冬')));
  assert.ok(a.leafLength>.02&&a.leafLength<.10);assert.ok(a.leafWidth>.01&&a.leafWidth<a.leafLength);assert.ok(a.petioleLength>=.002&&a.petioleLength<=.08);assert.ok(a.flowerRadius>0&&a.flowerRadius<.0127);assert.ok(a.flowerLength>0&&a.flowerLength<.0254);
  let winterLeaves=0,summerLeaves=0;
  for(let month=1;month<=12;month++){
   const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);
   const hood=count('petal-lamium-'+(i?'yellow':'purple')+'-hood'),leafMeshes=g.children.filter(m=>m.userData.component.startsWith('leaf-lamium-'));
   assert.equal(g.userData.architecture,'lamiumRunners');assert.ok(g.scale.x>0&&g.scale.x<=1&&g.scale.y>0&&g.scale.y<=1);assert.equal(seasonAt(info,month).shootScale,1);
   if(i){assert.ok(count('stolon-lamium')>0);assert.equal(count('root-lamium'),0);}else{assert.equal(count('stolon-lamium'),0);assert.equal(count('root-lamium'),0);assert.ok(count('branch-lamium-sterling')>0);}assert.equal(count('stem-lamium')>0,info.bloom.includes(month));
   assert.equal(hood>0,info.bloom.includes(month));assert.equal(count('sepal-lamium'),hood*5);assert.equal(count('anther-lamium'),hood*4);assert.equal(count('style-lamium'),hood);assert.equal(count('stigma-lamium'),hood*2);
   assert.equal(count('petal-lamium-'+(i?'yellow':'purple')+'-lower'),hood);assert.equal(count('petal-lamium-'+(i?'yellow':'purple')+'-side'),hood*2);
   assert.ok(leafMeshes.length);for(const mesh of leafMeshes)assert.equal(mesh.count%2,0);
   const leaves=leafMeshes.reduce((n,m)=>n+m.count,0);if(month===1)winterLeaves=leaves;if(month===7)summerLeaves=leaves;
   if([12,1,2].includes(month))assert.match(seasonAt(info,month).phase,/仮表示.*未確認/);
   for(const mesh of g.children){
    assert.ok([...mesh.instanceMatrix.array].every(Number.isFinite));assert.ok([...mesh.geometry.attributes.position.array].every(Number.isFinite));assert.ok([...mesh.geometry.attributes.normal.array].every(Number.isFinite));
    mesh.computeBoundingBox();for(const axis of ['x','y','z']){assert.ok(Number.isFinite(mesh.boundingBox.min[axis]));assert.ok(Number.isFinite(mesh.boundingBox.max[axis]));}
    assert.ok(mesh.boundingBox.min.y>=-.008);assert.ok(mesh.boundingBox.max.y<=p.height*1.3);
    assert.ok(Math.max(Math.abs(mesh.boundingBox.min.x),Math.abs(mesh.boundingBox.max.x),Math.abs(mesh.boundingBox.min.z),Math.abs(mesh.boundingBox.max.z))<p.spread*.8);
   }dispose(g);
  }
  assert.ok(winterLeaves<summerLeaves);
  // Width changes add connected runner nodes without shrinking individual mature leaves.
  let smallLeaves=0;
  for(const width of [.15,.6]){
   p.spread=width;const g=plantModel(p,view(7)),leaves=g.children.filter(m=>m.userData.component.startsWith('leaf-lamium-')).reduce((n,m)=>n+m.count,0);
   if(width===.15)smallLeaves=leaves;else{assert.ok(leaves>smallLeaves);assert.ok(leaves<220);}
   for(const mesh of g.children){mesh.computeBoundingBox();assert.ok(Math.max(Math.abs(mesh.boundingBox.min.x),Math.abs(mesh.boundingBox.max.x),Math.abs(mesh.boundingBox.min.z),Math.abs(mesh.boundingBox.max.z))<width*.8);}dispose(g);
  }
 }
 assert.notEqual(CATALOG[ids[0]].appearance.leafShape,CATALOG[ids[1]].appearance.leafShape);assert.notEqual(CATALOG[ids[0]].appearance.leafPattern,CATALOG[ids[1]].appearance.leafPattern);
});
