   const p=makePlant(id,10400+i,2,2);p.height=1.3;p.spread=1.1;const g=plantModel(p,view(month)),count=key=>g.children.filter(m=>m.userData.component.startsWith(key)).reduce((n,m)=>n+m.count,0);
   assert.equal(g.userData.architecture,'berryShrub');assert.equal(count('leaf-berry')>0,i===1?month>=4&&month<=11:true);assert.equal(count(i===2?'sepal-berry':'petal-berry')>0,a.flowerMonths.includes(month));assert.equal(count('fruit-glossy-berry')>0,a.fruitMonths.includes(month));
