test('Sun-facing leaves expose their upper surface instead of the pale underside',()=>{
 for(const id of ['p-cdffaab2bff1','p-b6065ca96f6d','p-c9af173c63cd']){
  const p=makePlant(id,9980,2,2);p.height=1;p.spread=1;const g=plantModel(p,view(6));
  const leaves=g.children.filter(m=>/^leaf-(southern|cape|banksia)/.test(m.userData.component));assert.ok(leaves.length>0);
  for(const mesh of leaves){const normal=mesh.geometry.attributes.normal,uv=mesh.geometry.attributes.uv;let checked=0;
   for(let j=0;j<normal.count;j++)if(uv.getY(j)>.35&&uv.getY(j)<.65&&Math.abs(uv.getX(j)-.5)<.1){assert.ok(normal.getZ(j)<-.5);checked++;}
   assert.ok(checked>0);
  }dispose(g);
 }
});

test('Southern shrubs retain distinct compound whorled and forked leaves and source specific flower months',()=>{
 const entries=Object.entries(CATALOG).filter(([,q])=>q.appearance?.architecture==='southernShrubs');assert.equal(entries.length,6);
 for(const [i,[id,info]] of entries.entries()){
  const a=info.appearance,type=a.shootProfile;let skeleton,leaves;
  for(let month=1;month<=12;month++){
   const p=makePlant(id,9900+i,2,2);p.height=type==='isopogon'||type==='nanum'?.4:1;p.spread=1;const st=stateAt(p,view(month)),g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component.startsWith(k)).reduce((n,m)=>n+m.count,0);
   assert.equal(g.userData.architecture,'southernShrubs');assert.ok(count('leaf-southern')>0);assert.ok(count('wood-southern')>0);assert.equal(st.groundDormant,false);
   const flowering=count(type==='drummondii'?'stamens-acacia':type==='westringia'?'corolla-westringia':type==='nanum'||type==='fancy'?'petal-manuka':'perianth-southern');assert.equal(flowering>0,a.flowerMonths.includes(month));assert.equal(count('fruit'),0);
   if(type==='drummondii'){assert.equal(count('pinna-acacia'),count('rachis-acacia')*4);assert.equal(count('leaf-southern-drummondii'),count('rachis-acacia')*24);}if(type==='westringia'){assert.equal(count('lip-westringia'),count('corolla-westringia')*5);assert.equal(count('anther-westringia'),count('corolla-westringia')*2);}if(type==='fancy'||type==='nanum')assert.equal(count('petal-manuka'),count('receptacle-manuka')*(type==='fancy'?20:5));
   const wood=g.children.filter(m=>m.userData.component.startsWith('wood-southern')).map(m=>[...m.instanceMatrix.array]);if(!skeleton)skeleton=wood;else assert.deepEqual(wood,skeleton);if(!leaves)leaves=count('leaf-southern');else assert.equal(count('leaf-southern'),leaves);
   for(const m of g.children){assert.ok([...m.instanceMatrix.array].every(Number.isFinite));assert.ok([...m.geometry.attributes.position.array].every(Number.isFinite));}dispose(g);
  }
 }
 assert.deepEqual(CATALOG['p-b5e083225817'].bloom,[4,5]);assert.deepEqual(CATALOG['p-16f3aff4be1f'].bloom,[11,12,1,2,3]);assert.equal(CATALOG['p-4036541d96e6'].appearance.leafPattern,'margin');
});

