   const matrices=g.children.filter(m=>/^(wood-camellia|stem-camellia)/.test(m.userData.component)).map(m=>[m.userData.component,[...m.instanceMatrix.array]]);assert.ok(matrices.length);if(!wood)wood=matrices;else assert.deepEqual(matrices,wood,id+': stable branch skeleton');
   for(const m of g.children){assert.ok([...m.instanceMatrix.array].every(Number.isFinite));assert.ok([...m.geometry.attributes.position.array].every(Number.isFinite));}dispose(g);
