 assert.ok(stateAt(makePlant('p-95f782c628f5',7470,2,2),view(1)).groundDormant);
 for(const id of ['p-017d82b884dc','p-2b6a663c5570'])assert.equal(stateAt(makePlant(id,7471,2,2),view(1)).groundDormant,false);
