test('seven double tulip references distinguish semi-double white green marks purple cream pink and dark cups without invented reproductive counts',()=>{
 const ids=['p-b4f52be1e245','p-bb5064dce07c','p-2daef940908b','p-37deb641db46','p-20a73e3b3143','p-dd67aa4f6898','p-9a8bf5938747'],types=Object.keys(DOUBLE_TULIP_PROFILES),innerDensity={};
 for(const [ci,id]of ids.entries())for(const small of [false,true])for(let month=1;month<=12;month++){
  const type=types[ci],p={...makePlant(id,40500+ci*10+(small?1:0),2,2),height:(small?[.08,.16,.18,.16,.14,.16,.16]:[.20,.45,.50,.45,.40,.45,.45])[ci],spread:(small?[.28,.28,.28,.28,.28,.28,.25]:[.40,.45,.45,.45,.45,.45,.40])[ci],leafHeight:(small?[.067,.11,.12,.11,.10,.11,.11]:[.17,.28,.28,.27,.26,.27,.27])[ci]},g=plantModel(p,view(month)),label=id+' small='+small+' month='+month,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),parts=kind=>g.children.filter(m=>m.userData.component.startsWith('petaloid-double-tulip-'+type+'-'+kind+'-')).reduce((n,m)=>n+m.count,0),flowers=parts('outer')/6,leaves=count('leaf-double-tulip');
  try{
   assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(CATALOG[id].bloomKnown,[0,1,5].includes(ci));assert.equal(CATALOG[id].appearance.petals,undefined);assert.equal(CATALOG[id].appearance.flowerLayers,undefined);assert.equal(CATALOG[id].appearance.stamenCount,undefined);assert.equal(CATALOG[id].spread,null);assert.equal(CATALOG[id].latin,'');assert.equal(g.scale.x,1,label);assert.equal(flowers>0,CATALOG[id].bloom.includes(month),label);if(flowers){assert.ok(parts('inner')>flowers*6,label);innerDensity[ci]=parts('inner')/flowers;}assert.equal(count('sheath-double-tulip'),leaves,label);assert.equal(count('vein-double-tulip'),leaves*80,label);if([1,7,8,9,10,11,12].includes(month))assert.equal(g.children.length,0,label);assert.ok(!g.children.some(m=>/fruit|seed|capsule|anther|filament|stigma|ovary|style|nectar/.test(m.userData.component)),label);
   for(const m of g.children){for(const arr of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok([...arr].every(Number.isFinite),label);m.computeBoundingBox();const b=m.boundingBox,within=(x,y,z)=>y>=-.003&&y<p.height*1.15&&Math.max(Math.abs(x),Math.abs(z))<p.spread*.75;if(!within(b.min.x,b.min.y,b.min.z)||!within(b.max.x,b.max.y,b.max.z)){const matrix=new Matrix4(),pos=m.geometry.attributes.position;for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);const e=matrix.elements;for(let j=0;j<pos.count;j++){const x=pos.getX(j),y=pos.getY(j),z=pos.getZ(j);assert.ok(within(e[0]*x+e[4]*y+e[8]*z+e[12],e[1]*x+e[5]*y+e[9]*z+e[13],e[2]*x+e[6]*y+e[10]*z+e[14]),label+' actual vertex '+m.userData.component);}}}}
  }finally{dispose(g);}
 }
 for(const type of types.flatMap(k=>[k+'InnerDoubleTepal',k+'OuterDoubleTepal']))for(let i=0;i<=24;i++)for(const u of [-1,0,1])assert.ok(doubleTulipPoint(type,i/24,u).every(Number.isFinite));assert.ok(innerDensity[1]<innerDensity[2],'source semi-double White Valley has fewer inner pieces than full double Lilac Blue');assert.equal(CATALOG[ids[4]].height,null,'do not infer missing Foxtrot mature height');assert.deepEqual(CATALOG[ids[2]].colors,['purple'],'blue trade label retains observed purple colour');assert.equal(CATALOG[ids[1]].appearance.flowerShape,'semiDoubleTulipCup');assert.deepEqual(CATALOG[ids[0]].bloom,[3,4]);assert.deepEqual(CATALOG[ids[1]].bloom,[3,4]);
});

