test('three arctotis references keep distinct silver leaves ray colours and five-lobed disc florets with conditional evergreen foliage',()=>{
 const ids=['p-75f4daf3ed15','p-b8d319c2b9b8','p-6285bd68799a'],types=['grandis','burgundy','sugar'];
 for(const [ci,id]of ids.entries())for(const small of [false,true])for(let month=1;month<=12;month++){
  const info=CATALOG[id],a=info.appearance,p={...makePlant(id,42700+ci*10+(small?1:0),2,2),height:small?(ci===0?.16:.09):(ci===0?.35:.18),spread:small?(ci===0?.20:.27):(ci===0?.25:.45),leafHeight:small?(ci===0?.07:.045):(ci===0?.12:.09)},g=plantModel(p,view(month)),label=id+' small='+small+' month='+month,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),heads=count('receptacle-arctotis'),leaves=count('leaf-arctotis-'+types[ci])+count('cauline-leaf-arctotis-'+types[ci]);
  try{
   assert.equal(a.status,'partial');assert.equal(g.userData.architecture,'arctotisReferences');assert.equal(a.petals,undefined);assert.equal(a.flowerLayers,undefined);assert.equal(a.compoundType,undefined);assert.equal(info.bloomKnown,false);assert.equal(a.flowerTiming,'season-reference');assert.match(info.care,/寒冷地/);assert.match(a.unconfirmed.join(' '),/閉花/);assert.equal(g.scale.x,1,label);assert.ok(leaves>0,label);assert.equal(heads>0,month>=3&&month<=11,label);
   assert.equal(count('midrib-arctotis'),leaves*10,label);assert.equal(count('petiole-arctotis'),leaves,label);assert.equal(count('disc-floret-arctotis-'+types[ci]),heads*128,label);for(let row=0;row<3;row++)assert.equal(count('involucre-arctotis-'+row),heads*(8+row*2),label);assert.ok(count('ray-arctotis-'+types[ci])>=heads*24&&count('ray-arctotis-'+types[ci])<=heads*28,label);assert.ok(!g.children.some(m=>/fruit|seed|compound|capsule/.test(m.userData.component)),label);
   for(const m of g.children){for(const arr of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok([...arr].every(Number.isFinite),label);m.computeBoundingBox();const box=m.boundingBox,within=(x,y,z)=>y>=-.003&&y<p.height*1.15&&Math.max(Math.abs(x),Math.abs(z))<p.spread*.65;if(!within(box.min.x,box.min.y,box.min.z)||!within(box.max.x,box.max.y,box.max.z)){const matrix=new Matrix4(),pos=m.geometry.attributes.position;for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);const e=matrix.elements;for(let j=0;j<pos.count;j++){const x=pos.getX(j),y=pos.getY(j),z=pos.getZ(j);assert.ok(within(e[0]*x+e[4]*y+e[8]*z+e[12],e[1]*x+e[5]*y+e[9]*z+e[13],e[2]*x+e[6]*y+e[10]*z+e[14]),label+' '+m.userData.component);}}}}
  }finally{dispose(g);}
 }
 const p={...makePlant(ids[0],42700,2,2),height:.35,spread:.25,leafHeight:.12},branches=[],leaves=[];
 drawDetailedHerb({branch:(from,to,r,color,kind)=>branches.push({from,to,kind}),add:(shape,kind,color,x,y,z)=>{if(/^(?:cauline-)?leaf-arctotis-/.test(kind))leaves.push([x,y,z]);}},{info:CATALOG[ids[0]],s:stateAt(p,view(5)),p,detail:1,rand:()=>.5,month:5},{bud:'bud',shade:(_,c)=>c});
 assert.ok(leaves.length>0);for(const at of leaves)assert.ok(branches.some(b=>b.to.every((v,i)=>Math.abs(v-at[i])<1e-8)),'every leaf starts at a connected petiole');
 for(const type of ['arctotisLyrateLeaf','arctotisWavyLeaf','arctotisRay','arctotisBract','arctotisFloret'])for(let i=0;i<=40;i++)for(const u of [-1,0,1])assert.ok(arctotisPoint(type,i/40,u).every(Number.isFinite));
 assert.notEqual(arctotisPoint('arctotisLyrateLeaf',.5,1)[0],arctotisPoint('arctotisWavyLeaf',.5,1)[0]);const radii=Array.from({length:100},(_,i)=>{const p=arctotisPoint('arctotisFloret',1,i*Math.PI/50);return Math.hypot(p[0],p[2]);});assert.ok(Math.max(...radii)>Math.min(...radii)*1.3,'tubular corollas have distinct five-lobed openings');assert.deepEqual(CATALOG[ids[0]].height,[.3,.4]);assert.deepEqual(CATALOG[ids[2]].spread,[.3,.6]);assert.deepEqual(CATALOG[ids[2]].colors,['pink','yellow']);
});


