test('ornata silver leaves and two Hummingbird colours keep connected unequal corollas and source-specific winter states',()=>{
 const ids=['p-f80153781c11','p-23df1beb411a','p-902ddd958778'],types=['ornata','hummingBlue','hummingPink'],adult=[[.4,.35,.25],[.25,.3,.15],[.25,.3,.15]],young=[[.16,.22,.10],[.10,.18,.06],[.10,.18,.06]];
 for(const [ci,id]of ids.entries())for(const small of [false,true])for(let month=1;month<=12;month++){
  const dims=(small?young:adult)[ci],p={...makePlant(id,43400+ci*10+(small?1:0),2,2),height:dims[0],spread:dims[1],leafHeight:dims[2]},info=CATALOG[id],g=plantModel(p,view(month)),label=id+' small='+small+' month='+month,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),flowers=count('corolla-veronica-'+types[ci]),leaves=count('leaf-veronica-'+types[ci]),winter=[12,1,2].includes(month);
  try{
   assert.equal(info.appearance.status,'partial');assert.equal(info.appearance.petals,4);assert.equal(info.appearance.stamenCount,2);assert.equal(flowers>0,info.bloom.includes(month),label);assert.equal(count('filament-veronica'),flowers*2,label);assert.equal(count('anther-veronica'),flowers*2,label);assert.equal(count('petiole-veronica'),leaves,label);assert.equal(count('midrib-veronica'),leaves*10,label);
   if(winter&&ci>0){assert.equal(g.children.length,0,label+' managed cleared winter');}else{assert.ok(leaves>0,label);assert.equal(g.userData.architecture,'veronicaReferences');if(winter)assert.equal(count('winter-bud-veronica'),9,label);}
   if(flowers)assert.ok(g.userData.flowerTargets?.length>0,label+' flower inspection');
   for(const m of g.children){for(const arr of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok([...arr].every(Number.isFinite),label);m.computeBoundingBox();const box=m.boundingBox,within=(x,y,z)=>y>=-.003&&y<p.height*1.15&&Math.max(Math.abs(x),Math.abs(z))<p.spread*.75;if(!within(box.min.x,box.min.y,box.min.z)||!within(box.max.x,box.max.y,box.max.z)){const matrix=new Matrix4(),pos=m.geometry.attributes.position;for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);const e=matrix.elements;for(let j=0;j<pos.count;j++){const x=pos.getX(j),y=pos.getY(j),z=pos.getZ(j);assert.ok(within(e[0]*x+e[4]*y+e[8]*z+e[12],e[1]*x+e[5]*y+e[9]*z+e[13],e[2]*x+e[6]*y+e[10]*z+e[14]),label+' '+m.userData.component);}}}}
  }finally{dispose(g);}
 }
 const p={...makePlant(ids[0],43400,2,2),height:.4,spread:.35,leafHeight:.25},leaves=[],branches=[];drawDetailedHerb({branch:(from,to,r,c,kind)=>branches.push({from,to,kind}),add:(shape,kind,c,x,y,z)=>{if(kind==='leaf-veronica-ornata')leaves.push([x,y,z]);}},{info:CATALOG[ids[0]],s:stateAt(p,view(8)),p,detail:1,rand:()=>.5,month:8},{bud:'bud',shade:(_,c)=>c});for(const at of leaves)assert.ok(branches.some(b=>b.kind==='petiole-veronica'&&b.to.every((v,i)=>Math.abs(v-at[i])<1e-8)),'silver leaves stay attached');
 for(let i=0;i<=48;i++)for(const u of [-1,0,1])assert.ok(veronicaPoint('veronicaOrnataLeaf',i/48,u).every(Number.isFinite));assert.equal(CATALOG[ids[0]].bloomKnown,false);assert.equal(CATALOG[ids[1]].bloomKnown,true);assert.equal(CATALOG[ids[2]].bloomKnown,true);assert.equal(CATALOG[ids[1]].spread,null);assert.equal(CATALOG[ids[2]].spread,null);assert.notEqual(CATALOG[ids[1]].flower,CATALOG[ids[2]].flower);assert.equal(CATALOG[ids[0]].appearance.leafMargin,'undulate');
});

