test('four Heliopsis references distinguish double yellow heads, red orange samples, golden ray eyes and veined variegation',()=>{
 const ids=['p-45b4f647d21e','p-a2171d200334','p-0342fe6e3772','p-a308bb535a09'],types=['bleedingHearts','asahi','summerPink','burningHearts'],sizes=[[[1,.65,.65],[.35,.3,.22]],[[.9,.65,.5],[.3,.3,.18]],[[.5,.4,.28],[.2,.25,.12]],[[1,.65,.65],[.35,.3,.22]]];
 for(const [ci,id]of ids.entries())for(const [si,size]of sizes[ci].entries())for(let month=1;month<=12;month++){
  const p={...makePlant(id,44500+ci*10+si,2,2),height:size[0],spread:size[1],leafHeight:size[2]},g=plantModel(p,view(month)),label=id+' '+si+' '+month,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);
  try{
   assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(CATALOG[id].appearance.arrangement,'opposite');assert.equal(CATALOG[id].appearance.leafMargin,'serrate');assert.equal(CATALOG[id].variegated,ci===2);
   if([12,1,2].includes(month)){assert.equal(g.userData.groundDormant,true,label);assert.equal(g.children.length,0,label);continue;}
   assert.equal(g.userData.architecture,'heliopsisReferences',label);const leaves=count('leaf-heliopsis-'+types[ci]),outer=count('bract-heliopsis-outer'),inner=count('bract-heliopsis-inner'),heads=outer/9,disc=count('disc-corolla-heliopsis'),rays=g.children.filter(m=>m.userData.component.startsWith('petal-ray-heliopsis-')).reduce((n,m)=>n+m.count,0),petaloids=count('petal-petaloid-heliopsis-asahi');assert.ok(leaves>0,label);assert.equal(count('petiole-heliopsis'),leaves,label);assert.equal(count('midrib-heliopsis'),leaves*12,label);assert.equal(count('side-vein-heliopsis'),leaves*12,label);
   assert.equal(heads>0,CATALOG[id].bloom.includes(month),label);assert.equal(inner,outer,label+' two separate involucre rows');assert.equal(count('disc-anther-tube-heliopsis'),disc,label);assert.equal(count('disc-palea-heliopsis'),disc,label);assert.equal(count('disc-style-heliopsis'),disc,label);assert.equal(count('disc-stigma-heliopsis'),disc*2,label);
   if(heads){assert.ok(g.userData.flowerTargets?.length,label);assert.equal(rays,heads*(ci===1?36:14),label);assert.equal(petaloids,ci===1?heads*120:0,label+' illustrative petaloid sample');if(ci===1){const full=count('double-receptacle-heliopsis');assert.ok(full>0&&full<heads,label+' supported full centres coexist with partial discs');assert.equal(count('petal-centre-heliopsis-asahi'),full*18,label+' inward overlapping central tissue');}else assert.equal(count('petal-centre-heliopsis-asahi'),0,label);assert.equal(count('ray-style-heliopsis'),ci===1?0:rays,label+' female ray styles separate from disc stamens');assert.equal(count('ray-stigma-heliopsis'),ci===1?0:rays*2,label);if(ci!==1)assert.equal(disc,heads*100,label);else assert.ok(disc>0&&disc<heads*100,label+' partial central discs coexist with fuller heads');if(ci===0){const colors=new Set();for(const m of g.children.filter(m=>m.userData.component.startsWith('petal-ray-heliopsis-')))for(let k=0;k<m.count;k++)colors.add(Array.from(m.instanceColor.array.slice(k*3,k*3+3)).join(','));assert.equal(colors.size,3,label+' static three-colour example');}assert.equal(g.children.find(m=>m.userData.component==='disc-corolla-heliopsis').geometry.userData.corollaLobes,5,label);}
   for(const m of g.children)assert.ok([...m.instanceMatrix.array,...m.geometry.attributes.position.array,...m.geometry.attributes.normal.array].every(Number.isFinite),label);
  }finally{dispose(g);}
 }
 assert.deepEqual(CATALOG[ids[2]].height,[.4,.6]);assert.deepEqual(CATALOG[ids[2]].spread,[.3,.5]);assert.deepEqual(CATALOG[ids[1]].bloom,[7,8,9]);assert.equal(CATALOG[ids[1]].bloomKnown,true);for(const id of [ids[0],ids[1],ids[3]]){assert.deepEqual(CATALOG[id].height,[.8,1.2]);assert.deepEqual(CATALOG[id].spread,[.5,.8]);}
});

test('Heliopsis actual leaves move with the height control and independent vein and ray eye shaders compile',()=>{
 for(const [ci,id]of ['p-45b4f647d21e','p-a2171d200334','p-0342fe6e3772','p-a308bb535a09'].entries())for(const month of [4,8]){
  const capture=leafHeight=>{const p={...makePlant(id,44500+ci*10,2,2),height:.8,spread:.6,leafHeight},g=plantModel(p,view(month));let top=-Infinity;try{for(const m of g.children){const kind=m.userData.component;if(kind.startsWith('leaf-heliopsis-')){m.computeBoundingBox();top=Math.max(top,m.boundingBox.max.y);}if(kind==='leaf-heliopsis-summerPink'||kind.startsWith('petal-ray-heliopsis-')){const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});if(kind==='leaf-heliopsis-summerPink')assert.ok(shader.fragmentShader.includes('hpNet'));else assert.equal(shader.fragmentShader.includes('hpEye'),kind.includes('-eye-'));}}return top;}finally{dispose(g);}};const low=capture(.005),high=capture(.4);assert.ok(low<.010,id+' actual low leaf ceiling');assert.ok(high>low*20,id+' actual leaf control');
 }
});


test('Helenium references retain alternate foliage and distinguish short rays, red heads and rolled two-sided rays',()=>{
 const ids=['p-988f1c92ff3e','p-6c0aa5755d23','p-6329f45d64e8'],types=['lollipop','siesta','tieDye'],sizes=[[[.5,.35,.30],[.2,.22,.11]],[[.5,.35,.30],[.2,.22,.11]],[[.7,.45,.42],[.25,.25,.14]]];
 for(const [ci,id]of ids.entries())for(const [si,size]of sizes[ci].entries())for(let month=1;month<=12;month++){
  const p={...makePlant(id,44600+ci*10+si,2,2),height:size[0],spread:size[1],leafHeight:size[2]},g=plantModel(p,view(month)),label=id+' '+si+' '+month,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);
  try{
   assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(CATALOG[id].appearance.arrangement,'alternate');assert.equal(CATALOG[id].bloomKnown,false);
   if([12,1,2].includes(month)){assert.equal(g.userData.groundDormant,true,label);assert.equal(g.children.length,0,label);continue;}
   assert.equal(g.userData.architecture,'heleniumReferences',label);const leaves=count('leaf-helenium-'+types[ci]),heads=count('disc-foundation-helenium'),discs=count('disc-corolla-helenium-'+types[ci]),anthers=count('disc-anther-tube-helenium');assert.ok(leaves>0,label);assert.equal(count('midrib-helenium'),leaves*12,label);assert.equal(count('side-vein-helenium'),leaves*10,label);assert.equal(count('stem-wing-helenium'),count('stem-helenium-'+types[ci])*2,label);assert.equal(heads>0,[6,7,8,9,10,11].includes(month),label);assert.equal(discs,heads*240,label+' sampled discs');assert.equal(count('bract-helenium-outer'),heads*8,label);assert.equal(count('bract-helenium-inner'),heads*8,label);assert.equal(count('disc-style-helenium'),anthers,label);assert.equal(count('disc-stigma-helenium'),anthers*2,label);
   if(heads){assert.ok(g.userData.flowerTargets?.length,label);assert.equal(g.children.find(m=>m.userData.component==='disc-corolla-helenium-'+types[ci]).geometry.userData.corollaLobes,ci===0?4:5,label);if(ci===2){assert.ok(count('petal-ray-helenium-tieDye-rolled')>0&&count('petal-ray-helenium-tieDye-open')>0,label);for(const m of g.children.filter(m=>m.userData.component.startsWith('petal-ray-helenium-tieDye'))){const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});assert.ok(shader.fragmentShader.includes('hlTip'));}}}
   for(const m of g.children)assert.ok([...m.instanceMatrix.array,...m.geometry.attributes.position.array,...m.geometry.attributes.normal.array].every(Number.isFinite),label);
  }finally{dispose(g);}
 }
 for(const type of ['heleniumLeaf','heleniumWing','heleniumBract','heleniumRay','heleniumRolledRay','heleniumDiscFour','heleniumDiscFive'])for(let i=0;i<=64;i++)for(const u of [-1,0,1])assert.ok(heleniumPoint(type,i/64,u).every(Number.isFinite));
 for(const [i,id]of ids.entries()){assert.deepEqual(CATALOG[id].height,[[.4,.5],[.3,.5],[.5,.7]][i]);assert.deepEqual(CATALOG[id].spread,[[.3,.4],[.3,.4],[.4,.5]][i]);}
});

