test('Tall Eupatorieae five references distinguish whorls, divided leaves, first bloom and uncut winter heads',()=>{
 const ids=['p-b3b855299a2d','p-d28c29b01eb2','p-581f18659de0','p-68fdba716e0b','p-7df8310e02e1'],types=['pinkFrost','japonicumWhite','ivory','atropurpureum','hagoromo'],sizes=[[[1,.65,.85],[.25,.25,.15]],[[1.5,.7,1.25],[.35,.28,.2]],[[1.8,.9,1.5],[.45,.3,.25]],[[1.8,.9,1.5],[.45,.3,.25]],[[1,.6,.85],[.25,.25,.15]]];
 for(const [ci,id]of ids.entries())for(const [si,size]of sizes[ci].entries())for(let month=1;month<=12;month++){
  const info=CATALOG[id],p={...makePlant(id,45300+ci*10+si,2,2),height:size[0],spread:size[1],leafHeight:size[2]},season=seasonAt(info,month),g=plantModel(p,view(month)),label=id+' '+si+' '+month,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);
  try{
   assert.equal(info.appearance.status,'partial');assert.equal(info.life,'perennial');assert.equal(info.bloomKnown,ci===1||ci===2);assert.equal(info.appearance.arrangement,ci===2||ci===3?'whorled':'opposite');
   if(season.groundDormant){assert.equal(g.userData.groundDormant,true,label);assert.equal(g.children.length,0,label);continue;}
   assert.equal(g.userData.architecture,'tallEupatorieae',label);const leaves=g.children.filter(m=>m.userData.component.startsWith('leaf-tallEupa-')).reduce((n,m)=>n+m.count,0),petioles=count('petiole-tallEupa'),corollas=count('corolla-tallEupa-'+types[ci]);assert.equal(leaves>0,season.leafDensity>0,label);if(ci===2)assert.equal(petioles%5,0,label+' illustrative five-leaf whorls');else if(ci===3)assert.equal(petioles%4,0,label+' illustrative four-leaf whorls');else assert.equal(petioles%2,0,label+' opposite pairs');if(ci===4)assert.equal(leaves,petioles*3,label+' connected divisions of a simple leaf, not compound leaflets');if(ci===1&&leaves)assert.ok(leaves>petioles,label+' lower divided and upper simple leaves');
   assert.equal(corollas>0,season.bloom,label);assert.equal(count('fused-anthers-tallEupa'),corollas,label);assert.equal(count('style-tallEupa'),corollas,label);assert.equal(count('stigma-branch-tallEupa'),corollas*2,label);assert.equal(!!g.userData.flowerTargets?.length,season.bloom,label);assert.equal(count('dry-head-tallEupa')>0,season.seedHeads,label);if(ci===3&&month===6){assert.ok(count('bud-head-tallEupa')>0);assert.equal(corollas,0,'early-summer buds are not open flowers');}
   assert.ok(!g.children.some(m=>/ray-tallEupa|pappus-tallEupa|achene-tallEupa/.test(m.userData.component)),label+' unresolved rays, pappus and fruit interiors are not invented');
   for(const mesh of g.children){assert.ok(mesh.instanceMatrix.array.every(Number.isFinite),label);assert.ok(mesh.geometry.attributes.normal.array.every(Number.isFinite),label);if(mesh.userData.component.startsWith('corolla-tallEupa-')){assert.equal(mesh.geometry.userData.corollaLobes,5);assert.equal(mesh.castShadow,false);assert.equal(mesh.receiveShadow,false);}}
  }finally{dispose(g);}
 }
 assert.deepEqual(CATALOG[ids[2]].bloom,[6,7]);assert.match(CATALOG[ids[2]].bloomText,/切戻し|切り戻し/);assert.equal(seasonAt(CATALOG[ids[2]],10).bloom,false,'conditional October rebloom is not automatic');assert.deepEqual(CATALOG[ids[1]].bloom,[8,9]);assert.equal(CATALOG[ids[1]].spread,null);assert.equal(CATALOG[ids[4]].latin,"Eupatorium 'Hagoromo'");assert.match(CATALOG[ids[4]].appearance.unconfirmed.join(' '),/未確定/);
});

test('Tall Eupatorieae low independent leaf heights remain attached and above ground without moving the input dimensions',()=>{
 const ids=['p-b3b855299a2d','p-d28c29b01eb2','p-581f18659de0','p-68fdba716e0b','p-7df8310e02e1'];
 for(const [ci,id]of ids.entries())for(const month of [4,6]){
  const tops=[];for(const leafHeight of [.005,.5]){const p={...makePlant(id,45350+ci,2,2),height:.8,spread:.6,leafHeight},before=structuredClone(p),g=plantModel(p,view(month)),matrix=new Matrix4(),v=new Vector3();let top=-Infinity,min=Infinity;try{for(const mesh of g.children){const comp=mesh.userData.component;if(comp.startsWith('leaf-tallEupa-')){mesh.computeBoundingBox();top=Math.max(top,mesh.boundingBox.max.y);min=Math.min(min,mesh.boundingBox.min.y);}if(comp==='stem-tallEupa'){const positions=mesh.geometry.attributes.position;for(let j=0;j<mesh.count;j++){mesh.getMatrixAt(j,matrix);for(let k=0;k<positions.count;k++)min=Math.min(min,v.fromBufferAttribute(positions,k).applyMatrix4(matrix).y);}}}assert.ok(top<=leafHeight+.00004,id+' '+month+' leaf ceiling');assert.ok(min>=-.00003,id+' '+month+' stem base '+min);
 const stems=g.children.find(m=>m.userData.component==='stem-tallEupa'),petioles=g.children.find(m=>m.userData.component==='petiole-tallEupa'),lines=[],nearest=new Vector3();for(let j=0;j<stems.count;j++){stems.getMatrixAt(j,matrix);lines.push(new Line3(new Vector3(0,-.5,0).applyMatrix4(matrix),new Vector3(0,.5,0).applyMatrix4(matrix)));}for(let j=0;j<petioles.count;j++){petioles.getMatrixAt(j,matrix);const start=new Vector3(0,-.5,0).applyMatrix4(matrix);assert.ok(Math.min(...lines.map(line=>line.closestPointToPoint(start,true,nearest).distanceTo(start)))<1e-6,id+' attached petiole');}
 tops.push(top);assert.deepEqual(p,before);}finally{dispose(g);}}assert.ok(tops[1]>tops[0]*40,id+' leaf-height response');
 }
});

