test('Calamagrostis references distinguish variegated blades, early open plumes and later narrow dry panicles',()=>{
 const ids=['p-4a3b5b196068','p-d5b3dcc9a2e9','p-896d6c23553d'],types=['overdam','karlFoerster','waldenbuch'],sizes=[[[1,.6,.5],[.3,.25,.16]],[[1.5,.65,.7],[.4,.28,.20]],[[1.2,.7,.6],[.35,.3,.18]]];
 for(const [ci,id]of ids.entries())for(const [si,size]of sizes[ci].entries())for(let month=1;month<=12;month++){
  const info=CATALOG[id],p={...makePlant(id,45600+ci*10+si,2,2),height:size[0],spread:size[1],leafHeight:size[2]},s=seasonAt(info,month),g=plantModel(p,view(month)),label=id+' '+si+' '+month,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);
  try{assert.equal(info.appearance.status,'partial');assert.equal(info.appearance.arrangement,'alternate');assert.equal(info.bloomKnown,false);assert.equal(info.variegated,ci===0);assert.equal(info.life,'perennial');assert.equal(g.userData.architecture,'calamagrostisReferences',label);
   assert.ok(g.children.some(m=>m.userData.component.startsWith('leaf-cala-'+types[ci])),label);assert.ok(count('leaf-sheath-cala')>0,label);const envelopes=count('spikelet-envelope-cala');assert.equal(envelopes>0,s.bloom||s.seedHeads,label);assert.equal(envelopes%2,0,label+' exterior envelopes occur in pairs');assert.equal(count('basal-hair-cala')>0,s.bloom||s.seedHeads,label);assert.equal(!!g.userData.flowerTargets?.length,s.bloom,label);assert.ok(!g.children.some(m=>/lemma-cala|palea-cala|anther-cala|pollen-cala|grain-cala|style-cala/.test(m.userData.component)),label+' no unverified floret interior or fertile-seed claim');if(ci===2)assert.match(s.label,/差があります/);
   for(const mesh of g.children){assert.ok(mesh.instanceMatrix.array.every(Number.isFinite),label);assert.ok(mesh.geometry.attributes.normal.array.every(Number.isFinite),label);if(mesh.geometry.userData.exteriorEnvelopeReference){assert.equal(mesh.castShadow,false);assert.equal(mesh.receiveShadow,false);}if(mesh.userData.component.startsWith('leaf-cala-')){const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};mesh.material.onBeforeCompile(shader,{});assert.equal(shader.fragmentShader.includes('crEdge'),ci===0&&![11,12,1,2].includes(month),label+' white/pink marginal reference, fading in the dry-leaf stage');}}
  }finally{dispose(g);}
 }
 for(const [ci,id]of ids.entries()){assert.deepEqual(CATALOG[id].height,[[.8,1.2],[1,1.8],[.8,1.5]][ci]);assert.deepEqual(CATALOG[id].spread,[[.4,.8],[.5,.8],[.6,.8]][ci]);assert.equal(seasonAt(CATALOG[id],5).bloom,false,'early-summer rather than a seven-month flowering window');assert.equal(seasonAt(CATALOG[id],6).bloom,true);assert.equal(seasonAt(CATALOG[id],1).bloom,false);assert.equal(seasonAt(CATALOG[id],1).seedHeads,true,'retained plumes do not establish viable seeds');}
 assert.equal(seasonAt(CATALOG[ids[0]],8).bloom,false);assert.equal(seasonAt(CATALOG[ids[1]],8).bloom,false);assert.equal(seasonAt(CATALOG[ids[2]],8).bloom,true,'Waldenbuch has a separate approximate timing and a visible source difference');
});
test('Calamagrostis independent leaf heights remain attached to culms and above ground without moving inputs',()=>{
 for(const [ci,id]of ['p-4a3b5b196068','p-d5b3dcc9a2e9','p-896d6c23553d'].entries())for(const month of [4,6]){
  const tops=[];for(const leafHeight of [.005,.5]){const p={...makePlant(id,45650+ci,2,2),height:.8,spread:.6,leafHeight},before=structuredClone(p),g=plantModel(p,view(month)),matrix=new Matrix4(),v=new Vector3();let top=-Infinity,min=Infinity;try{for(const mesh of g.children){if(mesh.userData.component.startsWith('leaf-cala-')){mesh.computeBoundingBox();top=Math.max(top,mesh.boundingBox.max.y);min=Math.min(min,mesh.boundingBox.min.y);}if(mesh.userData.component==='culm-cala'){const positions=mesh.geometry.attributes.position;for(let j=0;j<mesh.count;j++){mesh.getMatrixAt(j,matrix);for(let k=0;k<positions.count;k++)min=Math.min(min,v.fromBufferAttribute(positions,k).applyMatrix4(matrix).y);}}}assert.ok(top<=leafHeight+.00004,id+' '+month+' leaf ceiling');assert.ok(min>=-.00003,id+' '+month+' root '+min);
  const stems=g.children.find(m=>m.userData.component==='culm-cala'),lines=[],nearest=new Vector3();for(let j=0;j<stems.count;j++){stems.getMatrixAt(j,matrix);lines.push(new Line3(new Vector3(0,-.5,0).applyMatrix4(matrix),new Vector3(0,.5,0).applyMatrix4(matrix)));}for(const mesh of g.children)if(mesh.userData.component.startsWith('leaf-cala-'))for(let j=0;j<mesh.count;j++){mesh.getMatrixAt(j,matrix);const start=new Vector3(0,0,0).applyMatrix4(matrix);assert.ok(Math.min(...lines.map(line=>line.closestPointToPoint(start,true,nearest).distanceTo(start)))<1e-6,id+' exact segmented stem attachment');}
  tops.push(top);assert.deepEqual(p,before);}finally{dispose(g);}}assert.ok(tops[1]>tops[0]*30,id+' foliage response');
 }
});
