test('Three stipoid lineages distinguish long awns, lemma body hairs and Jarava apical crowns with evidence-specific winter states',()=>{
 const ids=['p-6dd68d8c4da0','p-1a393f5d4932','p-a84aacf22197'],types=['nassella','allgau','ichu'],sizes=[[[.75,.5,.43],[.25,.25,.15]],[[.8,.5,.38],[.25,.25,.15]],[[.8,.5,.35],[.25,.25,.15]]],awnLengths=[];
 for(const [ci,id]of ids.entries())for(const [si,size]of sizes[ci].entries())for(let month=1;month<=12;month++){
  const info=CATALOG[id],p={...makePlant(id,45700+ci*10+si,2,2),height:size[0],spread:size[1],leafHeight:size[2]},s=seasonAt(info,month),g=plantModel(p,view(month)),label=id+' '+si+' '+month,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);
  try{assert.equal(info.appearance.status,'partial');assert.equal(info.appearance.arrangement,'alternate');assert.equal(info.bloomKnown,ci===0);assert.equal(info.life,'perennial');
   if(ci===2&&[12,1,2].includes(month)){assert.equal(g.userData.groundDormant,true,label);assert.equal(g.children.length,0,label);assert.match(s.label,/低温管理株/);continue;}
   assert.equal(g.userData.architecture,'stipoidReferences',label);assert.ok(count('leaf-stipoid-'+types[ci]+'-basal')>0,label);assert.ok(count('leaf-stipoid-'+types[ci]+'-cauline')>0,label);const lemmas=count('lemma-stipoid-'+types[ci]);assert.equal(lemmas>0,s.bloom||s.seedHeads,label);assert.equal(count('glume-stipoid-'+types[ci]),lemmas*2,label);assert.equal(count('palea-stipoid-'+types[ci]),lemmas,label);assert.equal(count('lemma-hair-stipoid-allgau')>0,ci===1&&(s.bloom||s.seedHeads),label);assert.equal(count('apical-hair-stipoid-ichu')>0,ci===2&&(s.bloom||s.seedHeads),label);assert.equal(!!g.userData.flowerTargets?.length,s.bloom,label);assert.ok(!g.children.some(m=>/anther-stipoid|pollen-stipoid|grain-stipoid|pappus-stipoid/.test(m.userData.component)),label+' no grains, pappus or unverified anthers');
   if(si===0&&month===7){const awns=g.children.find(m=>m.userData.component==='lemma-awn-stipoid-'+types[ci]),matrix=new Matrix4();let length=0;for(let j=0;j<3;j++){awns.getMatrixAt(j,matrix);length+=new Vector3().setFromMatrixColumn(matrix,1).length();}awnLengths[ci]=length;}
   for(const mesh of g.children){assert.ok(mesh.instanceMatrix.array.every(Number.isFinite),label);assert.ok(mesh.geometry.attributes.normal.array.every(Number.isFinite),label);if(mesh.geometry.userData.singleFloretStipoidReference){assert.equal(mesh.castShadow,false);assert.equal(mesh.receiveShadow,false);}}
  }finally{dispose(g);}
 }
 assert.ok(awnLengths[0]>awnLengths[1]*4,'Nassella has much longer awns than Allgäu');assert.ok(awnLengths[2]>awnLengths[1]&&awnLengths[2]<awnLengths[1]*2,'Jarava awn remains short relative to Nassella');
 assert.equal(CATALOG[ids[0]].latin,'Nassella tenuissima');assert.equal(CATALOG[ids[0]].spread,null);assert.deepEqual(CATALOG[ids[0]].height,[.6,.9]);assert.deepEqual(CATALOG[ids[0]].bloom,[7,8,9,10]);assert.match(CATALOG[ids[0]].bloomText,/通称名/);assert.equal(CATALOG[ids[1]].latin,"Achnatherum calamagrostis 'Allgäu'");assert.equal(CATALOG[ids[2]].latin,'Jarava ichu');for(const id of ids.slice(1)){assert.deepEqual(CATALOG[id].height,[.6,1]);assert.deepEqual(CATALOG[id].spread,[.4,.6]);}
 assert.equal(seasonAt(CATALOG[ids[0]],1).seedHeads,false,'unknown domestic winter heads are not asserted');assert.equal(seasonAt(CATALOG[ids[1]],1).seedHeads,true,'Allgäu has explicit retained winter-head evidence');assert.equal(seasonAt(CATALOG[ids[2]],10).seedHeads,true,'Jarava cotton-like autumn remnant is separate from open flowering');
});
