test('Hakonechloa foliage types retain cauline leaves, source-limited identities and seven-floret reference spikelets through the year',()=>{
 const ids=['p-c95abb73a5ae','p-d580e6411693','p-df588ce2daa0'],types=['green','striped','gold'];
 for(const [ci,id]of ids.entries())for(const [si,size]of [[.3,.7,.27],[.12,.3,.08]].entries())for(let month=1;month<=12;month++){
  const p={...makePlant(id,45800+ci*10+si,2,2),height:size[0],spread:size[1],leafHeight:size[2]},before=structuredClone(p),info=CATALOG[id],s=seasonAt(info,month),g=plantModel(p,view(month)),label=id+' '+si+' '+month,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);
  try{
   assert.equal(info.appearance.status,'partial');assert.equal(info.latin,'Hakonechloa macra');assert.equal(info.appearance.architecture,'hakonechloaReferences');assert.equal(g.userData.architecture,'hakonechloaReferences');assert.equal(info.bloomKnown,false);assert.deepEqual(info.height,[.2,.4]);assert.equal(info.spread,null);assert.match(info.care,/60cm以上で上限未確認/);assert.equal(info.variegated,ci===1);assert.equal(info.appearance.arrangement,'alternate');assert.equal(s.groundDormant,false);assert.equal(s.seedHeads,false,'unknown winter heads not invented');
   const leaf=g.children.find(m=>m.userData.component.startsWith('leaf-hakone-'+types[ci]));assert.ok(leaf?.count>0,label);assert.equal(count('node-sheath-hakone'),40*7,label+' seven nodes per illustrated culm');assert.equal(count('lower-glume-hakone')>0,s.bloom,label);assert.equal(count('upper-glume-hakone'),count('lower-glume-hakone'));assert.equal(count('fertile-lemma-hakone'),count('lower-glume-hakone')*7);assert.equal(count('fertile-palea-hakone'),count('fertile-lemma-hakone'));assert.equal(count('apical-reduced-lemma-hakone'),count('lower-glume-hakone'));assert.equal(count('lemma-awn-hakone'),count('fertile-lemma-hakone'));assert.equal(count('anther-hakone'),s.bloom?3:0,'one illustrative open floret has three anthers');assert.equal(!!g.userData.flowerTargets?.length,s.bloom);assert.ok(!g.children.some(m=>/pollen-hakone|fruit-hakone|basal-leaf-hakone/.test(m.userData.component)));
   for(const mesh of g.children){assert.ok(mesh.instanceMatrix.array.every(Number.isFinite),label);assert.ok(mesh.geometry.attributes.normal.array.every(Number.isFinite),label);if(mesh.geometry.userData.hakonechloaSpikeletReference){assert.equal(mesh.castShadow,false);assert.equal(mesh.receiveShadow,false);}}
   if(month===1)assert.match(s.label,/未剪定/);if(month===3)assert.match(s.label,/管理例/);assert.deepEqual(p,before);
  }finally{dispose(g);}
 }
 assert.match(CATALOG[ids[2]].season,/同一性.*未確認/);assert.ok(!CATALOG[ids[1]].latin.includes('Aureola'));assert.ok(!CATALOG[ids[2]].latin.includes('All Gold'));
});
