test('Other Carex references separate cold-region dormancy UK brown winter foliage and unresolved retail identity',()=>{
 const ids=['p-ffb1ed48fe6b','p-2f94b58411e5','p-b519b598a40b','p-ac08810dd4cc'],heights=[[.4,.7],[.3,.5],[.1,.5],[.1,.2]],spreads=[[.4,.6],null,[.5,1],null];
 for(const [ci,id]of ids.entries())for(const [si,size]of [[.3,.45,.25],[.12,.22,.08]].entries())for(let month=1;month<=12;month++){
  const p={...makePlant(id,46400+ci*10+si,2,2),height:size[0],spread:size[1],leafHeight:size[2]},before=structuredClone(p),info=CATALOG[id],s=seasonAt(info,month),g=plantModel(p,view(month)),label=id+' '+si+' '+month,cold=ci===0||ci===3,dormant=cold&&[12,1,2].includes(month),bloom=(ci===2?[3,4,5]:[4,5,6]).includes(month),count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);
  try{
   assert.equal(info.appearance.status,'partial');assert.deepEqual(info.height,heights[ci]);assert.deepEqual(info.spread,spreads[ci]);assert.equal(info.bloomKnown,false);assert.equal(info.variegated,ci!==1);assert.equal(info.appearance.arrangement,ci===3?'alternate':'basal');assert.equal(s.groundDormant,dormant,label);assert.equal(s.bloom,bloom,label);assert.equal(s.seedHeads,false);
   if(dormant){assert.equal(g.children.length,0,label);assert.equal(g.userData.groundDormant,true);assert.match(s.label,/寒冷地/);}else{assert.equal(g.userData.architecture,'otherCarexReferences');assert.ok(g.children.some(m=>m.userData.component.startsWith('leaf-other-carex-')),label);assert.equal(count('culm-other-carex')>0,bloom,label);assert.equal(count('spike-scale-other-carex-exterior')>0,bloom,label);assert.equal(!!g.userData.flowerTargets?.length,bloom,label);assert.equal(count('leafy-shoot-other-carex-banana')>0,ci===3,label);}
   if(ci===1&&month===1){const color=new Color(s.leafColor).getHSL({},SRGBColorSpace);assert.ok(color.h>.05&&color.h<.2&&color.s>.1&&s.leafDensity>0,'UK brown retained foliage');assert.match(s.label,/英国/);}if(ci===2&&month===1)assert.equal(s.leafDensity,1,'evergreen variegated reference is retained');
   assert.ok(!g.children.some(m=>/anther.*other-carex|stigma.*other-carex|grain.*other-carex|pollen.*other-carex|utricle.*other-carex|tepal.*other-carex/.test(m.userData.component)),label);
   for(const m of g.children){assert.ok(m.instanceMatrix.array.every(Number.isFinite),label);assert.ok(m.geometry.attributes.normal.array.every(Number.isFinite),label);if(m.userData.component.endsWith('-other-carex-exterior')){assert.equal(m.castShadow,false);assert.equal(m.receiveShadow,false);}}assert.deepEqual(p,before);
  }finally{dispose(g);}
 }
 assert.match(CATALOG[ids[2]].latin,/morrowii.*fortunei.*同定未確認/);assert.match(CATALOG[ids[2]].appearance.sourceConflict,/同義語と断定/);assert.equal(CATALOG[ids[2]].appearance.leafPattern,'margin');assert.equal(CATALOG[ids[3]].appearance.leafPattern,'center');assert.match(CATALOG[ids[3]].appearance.sourceConflict,/Unresolved/);assert.match(CATALOG[ids[1]].appearance.sourceConflict,/Knoll.*RHS/);
});
