test('Four tussock references preserve seasonal identities domestic dimensions and distinct leaf exteriors',()=>{
 const ids=['p-de19f78331f2','p-74ff1805830b','p-43b0f639ca52','p-5dd3a3b2b975'],heights=[[.3,.3],[.4,.5],[1.5,1.5],[.1,.2]],spreads=[null,[.5,.75],null,[.15,.25]];
 for(const [ci,id]of ids.entries()){
  assert.equal(CATALOG[id].appearance.status,'partial');assert.deepEqual(CATALOG[id].height,heights[ci]);assert.deepEqual(CATALOG[id].spread,spreads[ci]);assert.equal(CATALOG[id].bloomKnown,false);
  for(const size of [[ci===2?1.4:.4,.6,.24],[.10,.20,.06]])for(let month=1;month<=12;month++){
   const p={...makePlant(id,47100+ci,2,2),height:size[0],spread:size[1],leafHeight:size[2]},before=structuredClone(p),s=stateAt(p,view(month)),bloom=CATALOG[id].appearance.flowerMonths.includes(month),label=id+' '+size+' '+month;
   assert.equal(s.groundDormant,false,label);assert.equal(s.bloom,bloom,label);assert.deepEqual(p,before);
   if(![1,4,7,10].includes(month))continue;const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);
   try{assert.equal(g.userData.architecture,'tussockReferences');assert.ok(g.children.some(m=>m.userData.component.startsWith('leaf-tussock-')),label);assert.equal(!!g.userData.flowerTargets?.length,bloom,label);assert.ok(!g.children.some(m=>/gynoecium.*matrush|seed.*tussock|fruit.*tussock|hook.*fruit/.test(m.userData.component)),label);
    if(ci===1&&bloom){assert.ok(count('flower-tussock-matrush-exterior')>0);assert.equal(count('anther-tussock-matrush'),6*count('flower-tussock-matrush-exterior'));assert.equal(count('filament-tussock-matrush'),count('anther-tussock-matrush'));}
    if(ci===2&&s.seedHeads)assert.ok(count('spikelet-tussock-snow-exterior')>0);
    if(ci===3){assert.ok(count('membrane-tussock-crystal')>0);assert.ok(!g.children.some(m=>m.userData.component==='hair-tussock-crystal'));}
    for(const mesh of g.children)for(const arr of [mesh.instanceMatrix.array,mesh.geometry.attributes.position.array,mesh.geometry.attributes.normal.array])assert.ok(arr.every(Number.isFinite),label);
    if(ci===0||ci===3){const leaf=g.children.find(m=>m.userData.component.startsWith('leaf-tussock-')),shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};leaf.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,ci===0?/trRed/:/trMembrane/);}
   }finally{dispose(g);}
  }
 }
 assert.match(CATALOG[ids[0]].appearance.phenologyRegion,/米国/);assert.match(CATALOG[ids[1]].appearance.sourceConflict,/雄花のみ/);assert.match(CATALOG[ids[2]].appearance.phenologyRegion,/未剪定/);assert.match(CATALOG[ids[3]].appearance.sourceConflict,/無毛/);
});
