test('Rheum reference leaves panicles and seasonal reproductive organs retain separate genus anatomy',()=>{
 const ids=['p-e4c7675f584d','p-b35599393990'];
 for(const [ci,id]of ids.entries())for(const size of [[1.8,1.5,1],[.7,.6,.35]])for(let month=1;month<=12;month++){
  const p={...makePlant(id,51200+ci,2,2),height:size[0],spread:size[1],leafHeight:size[2]},v={...view(month),year:2},before=structuredClone(p),s=stateAt(p,v),g=plantModel(p,v),winter=[1,2,3,11,12].includes(month),bloom=CATALOG[id].appearance.flowerMonths.includes(month),count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),label=id+' '+size+' '+month;
  try{
   assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(s.groundDormant,winter,label);assert.equal(s.bloom,bloom,label);assert.equal(s.seedHeads,false,label);assert.equal(!!g.userData.flowerTargets?.length,bloom,label);
   if(winter)assert.equal(g.children.length,0,label);else{assert.equal(g.userData.architecture,'rheumReferences');assert.ok(g.children.some(m=>m.geometry.userData.rheumOrgan===(ci?'rhPalmateLeafRef':'rhBroadLeafRef')),label);assert.ok(count('petiole-rheum-basal-'+CATALOG[id].appearance.shootProfile)>0,label);}
   const flowers=count('ovary-rheum-ref');assert.equal(flowers>0,bloom,label);assert.equal(count('tepal-rheum-ref-'+CATALOG[id].appearance.shootProfile),flowers*6,label);assert.equal(count('anther-rheum-ref'),flowers*9,label);assert.equal(count('filament-rheum-ref'),flowers*9,label);assert.equal(count('style-rheum-ref'),flowers*3,label);assert.equal(count('stigma-rheum-ref'),flowers*3,label);
   assert.ok(!g.children.some(m=>/hosta|corolla|petal|fruit|seed|achene/.test(m.userData.component)),label);for(const m of g.children)for(const a of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok(a.every(Number.isFinite),label);assert.deepEqual(p,before);
  }finally{dispose(g);}
 }
 assert.deepEqual(CATALOG[ids[0]].height,[1.5,1.5]);assert.equal(CATALOG[ids[0]].spread,null);assert.deepEqual(CATALOG[ids[1]].height,[1.5,2]);assert.deepEqual(CATALOG[ids[1]].spread,[.8,1.5]);assert.equal(CATALOG[ids[1]].appearance.minFloweringYearsAfterPlanting,2);for(const id of ids){assert.equal(CATALOG[id].appearance.tepalCount,6);assert.equal(CATALOG[id].appearance.stamenCount,9);assert.equal(CATALOG[id].appearance.styleCount,3);assert.equal(CATALOG[id].appearance.petals,undefined);}
 const p={...makePlant(ids[1],51299,2,2),height:1.8,spread:1.5,leafHeight:1};for(const year of [0,1,2]){const g=plantModel(p,{...view(6),year});try{assert.equal(!!g.userData.flowerTargets?.length,year===2);assert.equal(g.children.some(m=>m.userData.component.startsWith('axis-rheum-ref-')),year===2);assert.equal(inspectionSeasonActive(p,{...view(6),year}),year===2);}finally{dispose(g);}}
});
