test('Peltate herb independent tiny dimensions keep every leaf flower and scape inside its physical inputs',()=>{
 for(const id of ['p-827b8ccfd9f3','p-3a2a2413a49e'])for(const size of [[1.2,1.5,.7],[.35,.6,.2],[.005,.08,.005],[.12,.005,.005],[.7,.8,.005],[.005,.005,.005]]){
  const p={...makePlant(id,51399,2,2),height:size[0],spread:size[1],leafHeight:size[2]},matrix=new Matrix4(),point=new Vector3(),label=id+' '+size;
  for(const month of id==='p-3a2a2413a49e'?[4,6]:[6]){const g=plantModel(p,view(month));try{let maxLeaf=0;for(const mesh of g.children){const pos=mesh.geometry.attributes.position;for(let k=0;k<mesh.count;k++){mesh.getMatrixAt(k,matrix);for(let j=0;j<pos.count;j++){point.set(pos.getX(j),pos.getY(j),pos.getZ(j)).applyMatrix4(matrix);assert.ok(point.toArray().every(Number.isFinite),label);assert.ok(point.y>=-1e-7&&point.y<=p.height*1.05+.00001,label+' height '+mesh.userData.component+' '+point.y);assert.ok(Math.hypot(point.x,point.z)<=p.spread*.54+.00001,label+' footprint '+mesh.userData.component);if(mesh.userData.component.startsWith('blade-peltate-'))maxLeaf=Math.max(maxLeaf,point.y);}}}assert.ok(maxLeaf<=p.leafHeight+.000001,label+' leaf ceiling '+maxLeaf);}finally{dispose(g);}}
 }
});
test('Peltate herb macro views target actual petals including Darmera before foliage exists',()=>{
 for(const [id,month]of [['p-827b8ccfd9f3',6],['p-3a2a2413a49e',4]])for(const size of [[1.2,1.5,.7],[.35,.6,.2]]){
  const p={...makePlant(id,51399,2,2),height:size[0],spread:size[1],leafHeight:size[2]},g=plantModel(p,view(month));try{assert.equal(flowerInspectionDistanceFloor(g),.045);g.position.set(-2,.012,-1);g.updateMatrixWorld(true);const cv=flowerInspectionView(g,349/388,40);assert.ok(cv);const cam=new PerspectiveCamera(40,349/388,.01,650);cam.position.fromArray(cv.position);cam.lookAt(...cv.target);cam.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),cam);const hit=ray.intersectObject(g,true)[0];assert.ok(hit&&hit.object.userData.component.startsWith('petal-peltate-ref-'),id+' first visible '+hit?.object.userData.component);}finally{dispose(g);}
 }
});

test('Rodgersia cultivar references retain compound leaf groups apetalous calyces and distinct style counts',()=>{
 const ids=['p-9f0c01d739d3','p-7be9169bb024','p-1880c67c191a'];
 for(const [ci,id]of ids.entries())for(const size of [[.8,1.2,.45],[.25,.4,.14]])for(let month=1;month<=12;month++){
  const p={...makePlant(id,51400+ci,2,2),height:size[0],spread:size[1],leafHeight:size[2]},v={...view(month),year:1},before=structuredClone(p),s=stateAt(p,v),g=plantModel(p,v),winter=[1,2,3,11,12].includes(month),bloom=[5,6].includes(month),retained=ci===0&&[7,8].includes(month),type=CATALOG[id].appearance.shootProfile,label=id+' '+size+' '+month,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);
  try{assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(s.groundDormant,winter,label);assert.equal(s.bloom,bloom,label);assert.equal(s.seedHeads,false,label);assert.equal(!!g.userData.flowerTargets?.length,bloom,label);assert.equal(inspectionSeasonActive(p,v),bloom,label);
   if(winter)assert.equal(g.children.length,0,label);else{assert.equal(g.userData.architecture,'rodgersiaCultivarReferences');assert.ok(count('rachis-rodgersia-ref-'+type)>0,label);const leaves=g.children.filter(m=>m.userData.component.startsWith('blade-rodgersia-ref-')).reduce((n,m)=>n+m.count,0);assert.equal(leaves,count('rachis-rodgersia-ref-'+type)*7,label);}
   const flowers=count('ovary-rodgersia-ref-'+type);assert.equal(flowers>0,bloom,label);assert.equal(count('calyx-rodgersia-ref-'+type+'-active'),flowers,label);assert.equal(count('calyx-rodgersia-ref-'+type+'-retained')>0,retained,label);for(const [part,n]of [['anther',10],['filament',10],['style',ci===1?3:2],['stigma',ci===1?3:2]])assert.equal(count(part+'-rodgersia-ref-'+type),flowers*n,label+' '+part);
   for(const mesh of g.children){if(mesh.userData.component.startsWith('calyx-'))assert.equal(mesh.geometry.userData.calyxLobes,5);for(const a of [mesh.instanceMatrix.array,mesh.geometry.attributes.position.array,mesh.geometry.attributes.normal.array])assert.ok(a.every(Number.isFinite),label);}assert.ok(!g.children.some(m=>/petal|hosta|peltate|rheum|seed|fruit/.test(m.userData.component)),label);assert.deepEqual(p,before);
  }finally{dispose(g);}
 }
 assert.deepEqual(CATALOG[ids[0]].height,[.6,.8]);assert.deepEqual(CATALOG[ids[0]].spread,[.8,1.5]);assert.deepEqual(CATALOG[ids[1]].height,[.4,.6]);assert.deepEqual(CATALOG[ids[1]].spread,[.6,.8]);assert.deepEqual(CATALOG[ids[2]].height,[.8,.8]);assert.equal(CATALOG[ids[2]].spread,null);for(const id of ids){assert.equal(CATALOG[id].appearance.petals,0);assert.equal(CATALOG[id].appearance.leaflets,7);}
 for(const id of ids.slice(0,2))for(const month of [6,7]){const p=makePlant(id,51499,2,2),g=plantModel(p,{...view(month),year:0});try{assert.equal(g.children.some(m=>/^(calyx|scape)-rodgersia-ref/.test(m.userData.component)),false);}finally{dispose(g);}}
});
