test('Heuchera cultivar references retain simple evergreen blades and separate five-petal five-stamen flowers',()=>{
 const ids=['p-1b9b17629405','p-499dafc89e81','p-54fcac98aafb'];
 for(const [ci,id]of ids.entries())for(const size of [[.4,.5,.24],[.15,.2,.08]])for(let month=1;month<=12;month++){
  const p={...makePlant(id,51500+ci,2,2),height:size[0],spread:size[1],leafHeight:size[2]},before=structuredClone(p),s=stateAt(p,view(month)),g=plantModel(p,view(month)),bloom=[5,6].includes(month),type=CATALOG[id].appearance.shootProfile,label=id+' '+size+' '+month,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);
  try{assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(CATALOG[id].latin,'');assert.equal(CATALOG[id].appearance.compoundType,undefined);assert.equal(CATALOG[id].appearance.persistence,'evergreen');assert.equal(s.groundDormant,false,label);assert.equal(s.bloom,bloom,label);assert.equal(s.seedHeads,false,label);assert.equal(g.userData.architecture,'heucheraCultivarReferences');assert.ok(g.children.some(m=>m.userData.component.startsWith('blade-hu-ref-')),label);assert.equal(!!g.userData.flowerTargets?.length,bloom,label);assert.equal(inspectionSeasonActive(p,view(month)),bloom,label);
   const flowers=count('ovary-hu-ref-'+type);assert.equal(flowers>0,bloom,label);assert.equal(count('calyx-hu-ref-'+type),flowers,label);for(const [part,n]of [['petal',5],['filament',5],['anther',5],['style',2],['stigma',2]])assert.equal(count(part+'-hu-ref-'+type),flowers*n,label+' '+part);if(ci===1&&bloom)assert.equal(flowers,count('scape-hu-ref-'+type)*3,label+' sparse Paprika');
   for(const mesh of g.children){if(mesh.userData.component.startsWith('calyx-'))assert.equal(mesh.geometry.userData.calyxLobes,5);for(const a of [mesh.instanceMatrix.array,mesh.geometry.attributes.position.array,mesh.geometry.attributes.normal.array])assert.ok(a.every(Number.isFinite),label);}assert.ok(!g.children.some(m=>/pollen|seed|fruit|hosta|rodgersia/.test(m.userData.component)),label);assert.deepEqual(p,before);
   if(month===7){const leaf=g.children.find(m=>m.userData.component.startsWith('blade-hu-ref-')),shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};leaf.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/huVein/);assert.match(shader.fragmentShader,/huBranch/);assert.match(shader.fragmentShader,/gl_FrontFacing/);assert.ok(!shader.fragmentShader.includes('${'));}
  }finally{dispose(g);}
 }
 assert.deepEqual(CATALOG[ids[0]].height,[.15,.2]);assert.deepEqual(CATALOG[ids[0]].spread,[.2,.35]);assert.deepEqual(CATALOG[ids[1]].height,[.2,.3]);assert.deepEqual(CATALOG[ids[1]].spread,[.35,.45]);assert.deepEqual(CATALOG[ids[2]].height,[.3,.4]);assert.deepEqual(CATALOG[ids[2]].spread,[.45,.55]);for(const id of ids){assert.equal(CATALOG[id].appearance.petals,5);assert.equal(CATALOG[id].appearance.stamenCount,5);assert.equal(CATALOG[id].appearance.styleCount,2);assert.equal(CATALOG[id].appearance.minFloweringYearsAfterPlanting,undefined);}
 const p=makePlant(ids[0],51599,2,2);assert.notEqual(stateAt(p,view(1)).leafColor,stateAt(p,view(4)).leafColor);assert.notEqual(stateAt(p,view(4)).leafColor,stateAt(p,view(7)).leafColor);
});
