test('Three summer Chrysanthemum references separate natural flowering from forced sale months and retain distinct observed colours',()=>{
 for(const [id,P,rays,cells]of [['p-707e29d12304','dorothy',24,120],['p-4ab5e07a5145','subaru',48,160],['p-9432d2c52083','summerSakura',144,0]])for(const size of [[.75,.5,.60],[.35,.3,.26]])for(let month=1;month<=12;month++){
  const p={...makePlant(id,54000,2,2),height:size[0],spread:size[1],leafHeight:size[2]},before=structuredClone(p),s=stateAt(p,view(month)),g=plantModel(p,view(month)),winter=[1,2,12].includes(month),live=[5,6,7].includes(month),bud=month===4,active=live?16:0,count=k=>g.children.filter(m=>m.userData.component===k+'-chrysanthemum-ref').reduce((n,m)=>n+m.count,0),label=id+' '+size+' '+month;
  try{assert.equal(s.bloom,live,label);assert.equal(s.groundDormant,false,label);assert.ok(g.children.length>0,label);assert.equal(g.userData.architecture,'chrysanthemumReferences');assert.equal(count('basal-shoot'),winter?6:0,label);assert.equal(count('head-stalk'),live||bud?18:0,label);assert.equal(count('head-bud'),live?2:bud?18:0,label);assert.equal(g.children.filter(m=>m.userData.component==='ray-chrysanthemum-ref-'+P).reduce((n,m)=>n+m.count,0),active*rays,label);if(winter)assert.equal(count('leaf'),36,label);const disc=active*(cells-Math.floor(cells*.15));assert.equal(count('disc-corolla'),disc,label);assert.equal(count('disc-filament'),disc*5,label);assert.equal(count('disc-anther-tube'),disc,label);assert.equal(count('disc-stigma-branch'),disc*2,label);if(!cells)assert.ok(!g.children.some(m=>/ovary|filament|anther|style|stigma/.test(m.userData.component)),label+' unresolved double centre');assert.ok(!g.children.some(m=>/pollen|nectar|fruit|seed|dew/.test(m.userData.component)),label);assert.equal(!!g.userData.flowerTargets?.length,live,label);
   if(live){const ray=g.children.find(m=>m.userData.component==='ray-chrysanthemum-ref-'+P);assert.equal(ray.geometry.userData.chrysanthemumReferenceOrgan,P==='summerSakura'?'gcChrysMiltonRayRef':'gcChrysBoatRayRef',label);for(let j=0;j<ray.count;j++){const c=new Color();ray.getColorAt(j,c);if(P==='dorothy')assert.ok(Math.min(c.r,c.g,c.b)>.45&&Math.max(c.r,c.g,c.b)-Math.min(c.r,c.g,c.b)<.40,label+' cream base');else{const hsl={};c.getHSL(hsl);if(P==='subaru')assert.ok(hsl.h>.08&&hsl.h<.20&&hsl.s>.55&&hsl.l>.3,label+' yellow base');else assert.ok(hsl.h>.88&&hsl.s>.4&&hsl.l>.08,label+' pink double base');}}
    const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};ray.material.onBeforeCompile(shader);const hex=P==='dorothy'?'#742a56':P==='subaru'?'#8a2636':'#e9bcd0',rgb=new Color(hex).toArray().map(v=>v.toFixed(6)).join(',');assert.ok(shader.fragmentShader.includes('vec3('+rgb+')'),label+' distinct second colour');assert.ok(shader.fragmentShader.includes(P==='summerSakura'?'chSakuraEdge':'chSummerBase'),label+' source colour region');
   }
   for(const m of g.children)for(const a of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok(a.every(Number.isFinite),label);assert.deepEqual(p,before);
  }finally{dispose(g);}
 }
 for(const id of ['p-707e29d12304','p-4ab5e07a5145','p-9432d2c52083']){const info=CATALOG[id];assert.equal(info.latin,'');assert.equal(info.height,null);assert.equal(info.spread,null);assert.deepEqual(info.bloom,[5,6,7]);assert.equal(info.bloomKnown,true);assert.match(info.appearance.sourceConflict,/30～40cm/);assert.match(info.appearance.sourceConflict,/60cm以上/);assert.match(info.appearance.sourceConflict,/電照/);assert.equal(info.appearance.flowerPalette.regime,'naturalMayJuly');for(const month of [8,9])assert.equal(seasonAt(info,month).bloom,false,id+' no forced condition inferred');}
});
