 const legacy=(t,u)=>{const az=(u+1)*Math.PI,r=.065+.085*t;return [Math.cos(az)*r,Math.sin(az)*r+.04*t*t,.76*t];},points=[],oldPoints=[],rows=32,cols=24;let endpoints=0,maxRadius=0,minAreaSq=Infinity,minNormalDot=Infinity,triangles=0;
