 assert.equal(points.length,825);assert.equal(endpoints,50);assert.equal(triangles,1536);assert.ok(maxRadius>.15*1.05,'belly is broader than the terminal opening');assert.ok(Math.hypot(...catmintPoint('dreamsTube',.5,-1).slice(0,1),catmintPoint('dreamsTube',.5,-1)[1]-.01)>.16,'rounded midsection retained');
 const doc=emptyDocument(10,6);doc.plans.A.plants=[[.6,.5,.30],[.14,.2,.06]].map((dims,i)=>({...makePlant('p-9017037456b9',616000+i,2+i*3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.1'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
