test('Pink Dreams upper lip retains a broad rounded two-tip hood with an unchanged attached quarter and no longitudinal fold',()=>{
 const legacy=(t,u)=>{const sn=Math.max(0,Math.sin(Math.PI*t));return [u*(.03+.21*sn),.08+.10*sn,.67+.27*t-.055*Math.exp(-u*u*70)*t**4];},points=[],terminal=[],rows=32,cols=24;let preserved=0,maxWidth=0,terminalWidth=0,minAreaSq=Infinity,maxXZDet=-Infinity,triangles=0;
 for(let row=0;row<=rows;row++)for(let col=0;col<=cols;col++){const t=row/rows,u=col/cols*2-1,p=catmintPoint('dreamsHood',t,u);assert.ok(p.every(Number.isFinite));if(t<=.25){assert.deepEqual(p,legacy(t,u),'attached first quarter remains exact');preserved++;}if(row)assert.ok(p[2]>points[(row-1)*25+col][2],'all axial columns remain forward-monotone');maxWidth=Math.max(maxWidth,Math.abs(p[0]));if(row===rows){terminal.push(p);terminalWidth=Math.max(terminalWidth,Math.abs(p[0]));}points.push(p.map(Math.fround));}
 for(let row=0;row<rows;row++)for(let col=0;col<cols;col++){const k=row*25+col;for(const ids of[[k,k+25,k+1],[k+1,k+25,k+26]]){const[a,b,c]=ids.map(i=>new Vector3(...points[i])),det=(b.x-a.x)*(c.z-a.z)-(b.z-a.z)*(c.x-a.x),area=b.clone().sub(a).cross(c.clone().sub(a)).lengthSq();assert.ok(area>1e-16&&Number.isFinite(area),'finite nondegenerate hood face');assert.ok(det< -1e-12,'consistent XZ orientation without a folded terminal');minAreaSq=Math.min(minAreaSq,area);maxXZDet=Math.max(maxXZDet,det);triangles++;}}
 const peaks=terminal.map((p,i)=>i>0&&i<cols&&p[2]>terminal[i-1][2]&&p[2]>terminal[i+1][2]?i:null).filter(i=>i!==null);
 assert.equal(points.length,825);assert.equal(preserved,225);assert.equal(triangles,1536);assert.ok(terminalWidth/maxWidth>.6&&terminalWidth/maxWidth<.85,'rounded end remains broad');assert.equal(peaks.length,2,'two shallow terminal tips');assert.equal(peaks[0]+peaks[1],24,'paired tips are symmetric');assert.ok(terminal[peaks[0]][2]-terminal[12][2]>.01&&terminal[peaks[0]][2]-terminal[12][2]<.03,'shallow central notch');assert.ok(terminal[12][1]>.15,'terminal roof stays raised instead of collapsing to base height');
 const doc=emptyDocument(10,6);doc.plans.A.plants=[[.6,.5,.30],[.14,.2,.06]].map((dims,i)=>({...makePlant('p-9017037456b9',617000+i,2+i*3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.2'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 console.log('PINK_DREAMS_617_HOOD '+JSON.stringify({vertices:points.length,triangles,preservedBaseVertices:preserved,minAreaSq,maxXZDet,terminalWidthRatio:terminalWidth/maxWidth,peakColumns:peaks}));
});

test('Pink Dreams lower-lip display colours reach only the intended material in working-linear space with finite stronger markings',()=>{
 let models=0;
 for(const[si,dims]of [[.6,.5,.30],[.14,.2,.06]].entries()){
  const p={...makePlant('p-9017037456b9',61300,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{...view(6),year:1});models++;
  try{const lip=g.children.find(m=>m.userData.component==='petal-dreams');assert.ok(lip?.count>0);for(const m of g.children){const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});const code=shader.fragmentShader;assert.ok(!code.includes('\\n'),'GLSL uses real newlines');if(m!==lip){assert.ok(!code.includes('pdTip')&&!code.includes('pdSpot'),'lip painting excludes '+m.userData.component);continue;}assert.ok(code.includes('float pdTip=smoothstep(.35,.90,vUv.y);'),'existing tip weighting');assert.ok(code.includes('cos(vUv.x*39.0+sin(vUv.y*23.0))*cos(vUv.y*48.0)),4.0)'),'spatial phase/frequencies retained with broader peaks');const tip=code.match(/vec3\(([\d.,]+)\),pdTip\*\.44/),spots=code.match(/vec3\(([\d.,]+)\),pdSpot\*pdTip\*\.90/);assert.ok(tip&&spots,'actual shader receives both display colours');for(const[match,hex]of [[tip,'#d6adde'],[spots,'#87588f']]){const actual=match[1].split(',').map(Number),expected=new Color(hex).toArray();assert.equal(actual.length,3);actual.forEach((v,i)=>assert.ok(Number.isFinite(v)&&v>=0&&v<=1&&Math.abs(v-expected[i])<=5.1e-9,'working-linear finite channel'));}assert.ok(spots[1].split(',').map(Number).every((v,i)=>v<Number(tip[1].split(',')[i])),'spots remain darker than the tip tint');}
  }finally{dispose(g);}
 }assert.equal(models,2);
 const doc=emptyDocument(10,6);doc.plans.A.plants=[[.6,.5,.30],[.14,.2,.06]].map((dims,i)=>({...makePlant('p-9017037456b9',618000+i,2+i*3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.3'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
});

test('Upright Faassenii flower observation selects an actual visible lower lip across saved sizes seasons and viewport shapes',()=>{
 const id='p-40d0fce02917',sizes=[[.4,.45,.20],[.10,.18,.04]],saved=[];let models=0,cameraChecks=0;
 assert.deepEqual(CATALOG[id].appearance.flowerMonths,[5,6,7,8,9,10,11]);assert.equal(CATALOG[id].spread,null,'domestic spread remains unknown');assert.equal(CATALOG[id].appearance.persistence,undefined,'winter habit remains unknown');
 for(const[si,dims]of sizes.entries())for(let month=1;month<=12;month++){
  const p={...makePlant(id,61900,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={...view(month),year:1},st=stateAt(p,v),g=plantModel(p,v),label=dims.join('/')+' month='+month;models++;
  try{assert.equal(g.userData.architecture,'uprightFaassenii');assert.equal(g.userData.flowerTargets?.length??0,st.bloom?1:0,label+' actual flower target exists only while blooming');if(!st.bloom)assert.equal(flowerInspectionView(g,.8,40),null);for(const m of g.children)for(const a of[m.instanceMatrix.array,m.geometry.getAttribute('position').array,m.geometry.getAttribute('normal').array])assert.ok(a.every(Number.isFinite),label+' finite organ data');
   if(month===6){
    g.updateMatrixWorld(true);const matrix=new Matrix4(),point=new Vector3();let top=-Infinity,radius=0,ground=Infinity,leafTop=-Infinity,petioleTop=-Infinity,vertices=0;
    for(const m of g.children){const pos=m.geometry.getAttribute('position'),leaf=m.userData.component==='leaf-catmint',petiole=m.userData.component==='petiole-catmint';for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);matrix.premultiply(m.matrixWorld);for(let j=0;j<pos.count;j++){point.fromBufferAttribute(pos,j).applyMatrix4(matrix);vertices++;assert.ok(point.toArray().every(Number.isFinite));top=Math.max(top,point.y);ground=Math.min(ground,point.y);radius=Math.max(radius,Math.hypot(point.x,point.z));if(leaf)leafTop=Math.max(leafTop,point.y);if(petiole)petioleTop=Math.max(petioleTop,point.y);}}}
    console.log('FAASSENII_619_DIMENSIONS '+JSON.stringify({size:si?'small':'large',input:{height:st.height,spread:st.spread,leafHeight:st.leafHeight},actualHeight:top,actualSpread:radius*2,actualLeafHeight:leafTop,actualPetioleHeight:petioleTop,ground,vertices}));
    assert.equal(flowerInspectionDistanceFloor(g),.055);const anchor=g.userData.flowerTargets[0],target=new Vector3(...anchor.origin),lip=g.children.find(m=>m.userData.component==='petal-catmint'),hood=g.children.find(m=>m.userData.component==='hood-catmint'),tube=g.children.find(m=>m.userData.component==='tube-catmint'),index=26*25+12;assert.ok(lip?.count>0&&hood?.count===lip.count&&tube?.count===lip.count);const pos=lip.geometry.getAttribute('position');assert.ok(lip.geometry.userData.catmintLip);assert.equal(pos.count,33*25);let nearest=Infinity,observedInstance=-1;
    for(let i=0;i<lip.count;i++){lip.getMatrixAt(i,matrix);const distance=new Vector3().fromBufferAttribute(pos,index).applyMatrix4(matrix).distanceTo(target);if(distance<nearest){nearest=distance;observedInstance=i;}}assert.ok(nearest<2e-7,'target lies on actual row26/column12');lip.getMatrixAt(observedInstance,matrix);const axis=new Vector3().setFromMatrixColumn(matrix,2).normalize(),fl=new Vector3().setFromMatrixColumn(matrix,0).length();assert.ok(axis.dot(new Vector3(...anchor.axis))>1-1e-6);assert.ok(Math.abs(anchor.radius-fl*1.2)<2e-7);
    g.position.set(p.x-5,.012,p.z-3);g.updateMatrixWorld(true);const worldTarget=g.localToWorld(target.clone());
    for(const aspect of[.8,1.65]){cameraChecks++;const pose=flowerInspectionView(g,aspect,40);assert.ok(pose);assert.ok(new Vector3(...pose.target).distanceTo(worldTarget)<1e-9,'zero offset targets actual surface');const camera=new PerspectiveCamera(40,aspect,.01,650);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.ok(hit?.object===lip,label+' selected lip is the first visible hit');assert.equal(hit.instanceId,observedInstance);assert.ok(hit.point.distanceTo(worldTarget)<2e-6);
     const projected=new Vector3();for(const organ of[tube,hood,lip]){organ.getMatrixAt(observedInstance,matrix);matrix.premultiply(organ.matrixWorld);const organPos=organ.geometry.getAttribute('position');for(let j=0;j<organPos.count;j++){projected.fromBufferAttribute(organPos,j).applyMatrix4(matrix).project(camera);assert.ok(Math.abs(projected.x)<=.98&&Math.abs(projected.y)<=.98&&projected.z>=-1&&projected.z<=1,label+' selected flower organs fit viewport');}}
    }saved.push({...structuredClone(p),id:619000+si});
   }assert.deepEqual(p,before);
  }finally{dispose(g);}
 }assert.equal(models,24);assert.equal(cameraChecks,4);
 const doc=emptyDocument(10,6);doc.plans.A.plants=saved;doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.4'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
});

test('Upright Faassenii saved dimensions bound attached opposite leaves through months and legal minimum inputs without adding winter basal leaves',()=>{
 const id='p-40d0fce02917',sizes=[[.4,.45,.20],[.10,.18,.04]],tiny=[[.01,.1,.005],[.5,.1,.005],[.01,.6,.005]],eps=1e-7,attachEps2=(2e-7)**2;let models=0,directPairs=0;
 const check=(dims,month)=>{
  const p={...makePlant(id,61900,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={...view(month),year:1},st=stateAt(p,v),g=plantModel(p,v),matrix=new Matrix4(),point=new Vector3(),segments=[],blades=[],petioleBases=[],petioleTips=[],label=dims.join('/')+' month='+month;let leaves=0,petioles=0,vertices=0;models++;
  try{g.updateMatrixWorld(true);g.traverse(mesh=>{
   if(!mesh.isMesh)return;const pos=mesh.geometry.getAttribute('position'),normal=mesh.geometry.getAttribute('normal'),tag=mesh.userData.component,leaf=tag==='leaf-catmint',petiole=tag==='petiole-catmint',shoot=/^(stem|branch|axis)-catmint$/.test(tag),count=mesh.isInstancedMesh?mesh.count:1;
   assert.ok(pos&&normal&&normal.array.every(Number.isFinite),label+' finite geometry normals');assert.ok(!/winter/.test(tag),label+' no newly inferred basal winter organs');if(mesh.isInstancedMesh)assert.ok(mesh.instanceMatrix.array.every(Number.isFinite));if(mesh.instanceColor)assert.ok(mesh.instanceColor.array.every(Number.isFinite));if(leaf){leaves+=count;assert.ok(mesh.geometry.userData.catmintLeaf);}if(petiole)petioles+=count;
   for(let i=0;i<count;i++){if(mesh.isInstancedMesh){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);}else matrix.copy(mesh.matrixWorld);
    if(shoot)segments.push(new Line3(new Vector3(0,-.5,0).applyMatrix4(matrix),new Vector3(0,.5,0).applyMatrix4(matrix)));if(leaf)blades.push(new Vector3().applyMatrix4(matrix));if(petiole){petioleBases.push(new Vector3(0,-.5,0).applyMatrix4(matrix));petioleTips.push(new Vector3(0,.5,0).applyMatrix4(matrix));}
    for(let j=0;j<pos.count;j++){point.fromBufferAttribute(pos,j).applyMatrix4(matrix);vertices++;if(!point.toArray().every(Number.isFinite))assert.fail(label+' nonfinite '+tag);if(point.y < -eps||point.y>st.height+eps)assert.fail(label+' ground/height '+tag+' '+point.y);if(Math.hypot(point.x,point.z)*2>st.spread+eps)assert.fail(label+' spread '+tag);if((leaf||petiole)&&point.y>Math.min(st.height,st.leafHeight)+eps)assert.fail(label+' leaf ceiling '+tag+' '+point.y);}
   }
  });assert.ok(vertices>0&&leaves>0&&segments.length>0);assert.equal(leaves%2,0);assert.equal(petioles%2,0);assert.ok(petioles<=leaves);const matched=(p,ends)=>ends.some(end=>p.distanceToSquared(end)<=attachEps2),onShoot=p=>segments.some(line=>line.closestPointToPoint(p,true,new Vector3()).distanceToSquared(p)<=attachEps2),direct=blades.filter(p=>!matched(p,petioleTips));
   for(const p of blades)assert.ok(matched(p,petioleTips)||onShoot(p),label+' blade attached to matching petiole or actual stem');for(const p of petioleBases)assert.ok(onShoot(p),label+' petiole begins on real shoot');for(const p of petioleTips)assert.ok(matched(p,blades),label+' petiole supports a retained blade');assert.equal(direct.length,leaves-petioles);assert.equal(direct.length%2,0);for(const p of direct){assert.ok(onShoot(p));const sameNode=direct.filter(q=>p.distanceToSquared(q)<=attachEps2).length;assert.ok(sameNode>=2&&sameNode%2===0,label+' complete existing pairs at direct node');}directPairs+=direct.length/2;assert.deepEqual(p,before);
  }finally{dispose(g);}
 };
 for(const dims of sizes)for(let month=1;month<=12;month++)check(dims,month);for(const dims of tiny)for(const month of[6,10])check(dims,month);assert.equal(models,30);assert.ok(directPairs>0,'legal minima exercise complete direct pairs');
 const doc=emptyDocument(10,6);doc.plans.A.plants=[...sizes,...tiny].map((dims,i)=>({...makePlant(id,620000+i,1+i*1.8,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.5'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 console.log('FAASSENII_620_CAPS '+JSON.stringify({models,directPairs}));
});

