test('Blue Moon dedicated lower lip keeps its attached quarter and observed vertex while broadening two rounded terminal lobes without folds',()=>{
 const rows=32,cols=24,points=[],terminal=[];let preserved=0,maxWidth=0,terminalWidth=0,triangles=0,minAreaSq=Infinity,maxXZDet=-Infinity;
 for(let row=0;row<=rows;row++)for(let col=0;col<=cols;col++){const t=row/rows,u=col/cols*2-1,p=catmintPoint('nervosaLip',t,u);assert.ok(p.every(Number.isFinite));if(t<=.25){assert.deepEqual(p,catmintPoint('catmintLip',t,u));preserved++;}if(row)assert.ok(p[2]>points[(row-1)*25+col][2],'forward-monotone axial columns');if(col)assert.ok(p[0]>points[row*25+col-1][0],'laterally monotone rows');maxWidth=Math.max(maxWidth,Math.abs(p[0]));if(row===rows){terminal.push(p);terminalWidth=Math.max(terminalWidth,Math.abs(p[0]));}points.push(p.map(Math.fround));}
 assert.deepEqual(points[26*25+12],catmintPoint('catmintLip',.8125,0).map(Math.fround),'actual Float32 center anchor unchanged');
 for(let row=0;row<rows;row++)for(let col=0;col<cols;col++){const k=row*25+col;for(const ids of[[k,k+25,k+1],[k+1,k+25,k+26]]){const[a,b,c]=ids.map(i=>new Vector3(...points[i])),det=(b.x-a.x)*(c.z-a.z)-(b.z-a.z)*(c.x-a.x),area=b.clone().sub(a).cross(c.clone().sub(a)).lengthSq();assert.ok(Number.isFinite(area)&&area>1e-16,'nondegenerate surface');assert.ok(det< -1e-12,'consistent unfolded XZ orientation');minAreaSq=Math.min(minAreaSq,area);maxXZDet=Math.max(maxXZDet,det);triangles++;}}
 const lobes=terminal.map((p,i)=>i>0&&i<cols&&p[1]<terminal[i-1][1]&&p[1]<terminal[i+1][1]?i:null).filter(i=>i!==null),notch=terminal[12][1]-Math.min(...terminal.map(p=>p[1]));
 assert.equal(points.length,825);assert.equal(preserved,225);assert.equal(triangles,1536);assert.equal(lobes.length,2);assert.equal(lobes[0]+lobes[1],24);assert.ok(notch>.02&&notch<.03);assert.ok(terminalWidth/maxWidth>.75&&terminalWidth/maxWidth<.95,'rounded end retains broad width');
 const doc=emptyDocument(10,6);doc.plans.A.plants=[[.4,.35,.20],[.12,.16,.04]].map((dims,i)=>({...makePlant('p-f8f380b8f606',624000+i,2+i*3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.9'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 console.log('BLUE_MOON_624_LIP '+JSON.stringify({vertices:points.length,triangles,preservedBaseVertices:preserved,minAreaSq,maxXZDet,terminalWidthRatio:terminalWidth/maxWidth,lobeColumns:lobes,notch}));
});

test('Blue Moon lower-lip display tint uses working-linear colours only on the intended organ with a forward pale region and bounded throat markings',()=>{
 let models=0;
 for(const dims of [[.4,.35,.20],[.12,.16,.04]]){
  const p={...makePlant('p-f8f380b8f606',62100,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{...view(6),year:1});models++;
  try{const lip=g.children.find(m=>m.userData.component==='petal-nervosa');assert.ok(lip?.count>0);for(const m of g.children){const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});const code=shader.fragmentShader;assert.ok(!code.includes('\\n'));if(m!==lip){assert.ok(!code.includes('bmTip')&&!code.includes('bmThroat'),'new tint confined to lower lip');continue;}assert.ok(code.includes('float bmTip=smoothstep(.32,.82,vUv.y);'),'forward region becomes paler rather than the attachment');assert.ok(code.includes('bmThroat=smoothstep(.20,.42,vUv.y)*(1.0-smoothstep(.58,.87,vUv.y))'),'markings fade before terminal edge');const pale=code.match(/vec3\(([\d.,]+)\),bmTip\*\.65/),spots=code.match(/vec3\(([\d.,]+)\),bmSpot\*bmThroat\*\.55/);assert.ok(pale&&spots);for(const[match,hex]of [[pale,'#d4d1ee'],[spots,'#7967ad']]){const actual=match[1].split(',').map(Number),expected=new Color(hex).toArray();assert.equal(actual.length,3);actual.forEach((v,i)=>assert.ok(Number.isFinite(v)&&v>=0&&v<=1&&Math.abs(v-expected[i])<=5.1e-9));}assert.ok(spots[1].split(',').map(Number).every((v,i)=>v<Number(pale[1].split(',')[i])),'markings darker than pale display tint');}
  }finally{dispose(g);}
 }assert.equal(models,2);
 const doc=emptyDocument(10,6);doc.plans.A.plants=[[.4,.35,.20],[.12,.16,.04]].map((dims,i)=>({...makePlant('p-f8f380b8f606',625000+i,2+i*3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.10'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
});

test('Blue Moon rounded upper hood preserves its attached quarter and two shallow tips without longitudinal folds',()=>{
 const legacy=(t,u)=>catmintPoint('catmintHood',t,u),points=[],terminal=[],rows=32,cols=24;let preserved=0,maxWidth=0,terminalWidth=0,minAreaSq=Infinity,maxXZDet=-Infinity,triangles=0;
 for(let row=0;row<=rows;row++)for(let col=0;col<=cols;col++){const t=row/rows,u=col/cols*2-1,p=catmintPoint('nervosaHood',t,u);assert.ok(p.every(Number.isFinite));if(t<=.25){assert.deepEqual(p,legacy(t,u),'attached first quarter remains exact');preserved++;}if(row)assert.ok(p[2]>points[(row-1)*25+col][2],'all axial columns remain forward-monotone');maxWidth=Math.max(maxWidth,Math.abs(p[0]));if(row===rows){terminal.push(p);terminalWidth=Math.max(terminalWidth,Math.abs(p[0]));}points.push(p.map(Math.fround));}
 for(let row=0;row<rows;row++)for(let col=0;col<cols;col++){const k=row*25+col;for(const ids of[[k,k+25,k+1],[k+1,k+25,k+26]]){const[a,b,c]=ids.map(i=>new Vector3(...points[i])),det=(b.x-a.x)*(c.z-a.z)-(b.z-a.z)*(c.x-a.x),area=b.clone().sub(a).cross(c.clone().sub(a)).lengthSq();assert.ok(area>1e-16&&Number.isFinite(area),'finite nondegenerate hood face');assert.ok(det< -1e-12,'consistent XZ orientation without a folded terminal');minAreaSq=Math.min(minAreaSq,area);maxXZDet=Math.max(maxXZDet,det);triangles++;}}
 const peaks=terminal.map((p,i)=>i>0&&i<cols&&p[2]>terminal[i-1][2]&&p[2]>terminal[i+1][2]?i:null).filter(i=>i!==null);
 assert.equal(points.length,825);assert.equal(preserved,225);assert.equal(triangles,1536);assert.ok(terminalWidth/maxWidth>.55&&terminalWidth/maxWidth<.8,'rounded end remains broad');assert.equal(peaks.length,2,'two shallow terminal tips');assert.equal(peaks[0]+peaks[1],24,'paired tips are symmetric');assert.ok(terminal[peaks[0]][2]-terminal[12][2]>.005&&terminal[peaks[0]][2]-terminal[12][2]<.02,'shallow central notch');assert.ok(terminal[12][1]>.10,'terminal roof stays raised instead of collapsing to base height');
 const doc=emptyDocument(10,6);doc.plans.A.plants=[[.4,.35,.20],[.12,.16,.04]].map((dims,i)=>({...makePlant('p-f8f380b8f606',626000+i,2+i*3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.11'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 console.log('BLUE_MOON_626_HOOD '+JSON.stringify({vertices:points.length,triangles,preservedBaseVertices:preserved,minAreaSq,maxXZDet,terminalWidthRatio:terminalWidth/maxWidth,peakColumns:peaks}));
});

test('Blue Moon tube retains both attached end rings and a finite smooth belly without reversed surface faces',()=>{
 const legacy=(t,u)=>catmintPoint('catmintTube',t,u),points=[],oldPoints=[],rows=32,cols=24;let endpoints=0,maxRadius=0,minAreaSq=Infinity,minNormalDot=Infinity,triangles=0;
 for(let row=0;row<=rows;row++)for(let col=0;col<=cols;col++){const t=row/rows,u=col/cols*2-1,p=catmintPoint('nervosaTube',t,u),old=legacy(t,u);assert.ok(p.every(Number.isFinite));assert.equal(p[2],old[2],'axial placement unchanged');const radius=Math.hypot(p[0],p[1]-.025*t*t);assert.ok(radius>=.05-1e-12&&radius<.145,'finite bounded tube radius');maxRadius=Math.max(maxRadius,radius);if(row===0||row===rows){assert.deepEqual(p,old,'both end rings remain exact');endpoints++;}points.push(p.map(Math.fround));oldPoints.push(old.map(Math.fround));}
 for(let row=0;row<rows;row++)for(let col=0;col<cols;col++){const k=row*(cols+1)+col;for(const ids of[[k,k+cols+1,k+1],[k+1,k+cols+1,k+cols+2]]){const normal=data=>{const[a,b,c]=ids.map(i=>new Vector3(...data[i]));return b.sub(a).cross(c.sub(a));},n=normal(points),old=normal(oldPoints),area=n.lengthSq(),dot=n.clone().normalize().dot(old.normalize());assert.ok(area>1e-16&&Number.isFinite(area),'nondegenerate triangle');assert.ok(dot>0,'orientation retained against original tube');minAreaSq=Math.min(minAreaSq,area);minNormalDot=Math.min(minNormalDot,dot);triangles++;}}
 for(let row=0;row<=rows;row++){const a=new Vector3(...points[row*25]),b=new Vector3(...points[row*25+24]);assert.ok(a.distanceTo(b)<1e-12,'circumferential seam remains closed');}
 assert.equal(points.length,825);assert.equal(endpoints,50);assert.equal(triangles,1536);assert.ok(maxRadius>.13,'belly is broader than the terminal opening');assert.ok(Math.hypot(...catmintPoint('nervosaTube',.5,-1).slice(0,1),catmintPoint('nervosaTube',.5,-1)[1]-.00625)>.13,'rounded midsection retained');
 const doc=emptyDocument(10,6);doc.plans.A.plants=[[.4,.35,.20],[.12,.16,.04]].map((dims,i)=>({...makePlant('p-f8f380b8f606',626100+i,2+i*3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.11'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 console.log('BLUE_MOON_626_TUBE '+JSON.stringify({vertices:points.length,triangles,preservedEndpointVertices:endpoints,maxRadius,minAreaSq,minNormalDot}));
});

test('Nuda and Tuberosa observations select actual visible lower lips across saved sizes seasons and viewport shapes',()=>{
 const entries=[['p-d01134b29939',62710,'nuda',[[1,.5,.35],[.18,.25,.06]]],['p-99357da7e268',62720,'tuberosa',[[.7,.5,.25],[.15,.22,.05]]]],saved=[];let models=0,cameraChecks=0;for(const[ei,[id,pid,profile,sizes]]of entries.entries()){
 assert.deepEqual(CATALOG[id].appearance.flowerMonths,profile==='tuberosa'?[5,6,7,8,9,10,11]:[5,6,7,8]);assert.deepEqual(CATALOG[id].height,profile==='tuberosa'?[.6,.8]:[.8,1.2]);assert.equal(CATALOG[id].appearance.status,'partial');
 for(const[si,dims]of sizes.entries())for(let month=1;month<=12;month++){
  const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={...view(month),year:1},st=stateAt(p,v),g=plantModel(p,v),label=profile+' '+dims.join('/')+' month='+month;models++;
  try{assert.equal(g.userData.architecture,'tallNepetaSpires');assert.equal(g.userData.flowerTargets?.length??0,st.bloom?1:0,label+' actual flower target exists only while blooming');if(!st.bloom)assert.equal(flowerInspectionView(g,.8,40),null);for(const m of g.children)for(const a of[m.instanceMatrix.array,m.geometry.getAttribute('position').array,m.geometry.getAttribute('normal').array])assert.ok(a.every(Number.isFinite),label+' finite organ data');
   if(month===6){
    g.updateMatrixWorld(true);const matrix=new Matrix4(),point=new Vector3();let top=-Infinity,radius=0,ground=Infinity,leafTop=-Infinity,petioleTop=-Infinity,vertices=0;
    for(const m of g.children){const pos=m.geometry.getAttribute('position'),leaf=/^(leaf-nuda|leaf-tuberosa|leaf-tall-nepeta-winter)$/.test(m.userData.component),petiole=m.userData.component.startsWith('petiole-tall-nepeta');for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);matrix.premultiply(m.matrixWorld);for(let j=0;j<pos.count;j++){point.fromBufferAttribute(pos,j).applyMatrix4(matrix);vertices++;assert.ok(point.toArray().every(Number.isFinite));top=Math.max(top,point.y);ground=Math.min(ground,point.y);radius=Math.max(radius,Math.hypot(point.x,point.z));if(leaf)leafTop=Math.max(leafTop,point.y);if(petiole)petioleTop=Math.max(petioleTop,point.y);}}}
    console.log('TALL_NEPETA_627_DIMENSIONS '+JSON.stringify({profile,size:si?'small':'large',input:{height:st.height,spread:st.spread,leafHeight:st.leafHeight},actualHeight:top,actualSpread:radius*2,actualLeafHeight:leafTop,actualPetioleHeight:petioleTop,ground,vertices}));
    assert.equal(flowerInspectionDistanceFloor(g),.020);const anchor=g.userData.flowerTargets[0],target=new Vector3(...anchor.origin),lip=g.children.find(m=>m.userData.component===(profile==='tuberosa'?'petal-catmint':'petal-nuda')),hood=g.children.find(m=>m.userData.component==='hood-tall-nepeta'),tube=g.children.find(m=>m.userData.component==='tube-tall-nepeta'),index=26*25+12;assert.ok(lip?.count>0&&hood?.count===lip.count&&tube?.count===lip.count);const pos=lip.geometry.getAttribute('position');assert.ok(lip.geometry.userData.catmintLip);assert.equal(pos.count,33*25);let nearest=Infinity,observedInstance=-1;
    for(let i=0;i<lip.count;i++){lip.getMatrixAt(i,matrix);const distance=new Vector3().fromBufferAttribute(pos,index).applyMatrix4(matrix).distanceTo(target);if(distance<nearest){nearest=distance;observedInstance=i;}}assert.ok(nearest<2e-7,'target lies on actual row26/column12');lip.getMatrixAt(observedInstance,matrix);const axis=new Vector3().setFromMatrixColumn(matrix,2).normalize(),fl=new Vector3().setFromMatrixColumn(matrix,0).length();assert.ok(axis.dot(new Vector3(...anchor.axis))>1-1e-6);assert.ok(Math.abs(anchor.radius-fl*1.2)<2e-7);
    g.position.set(p.x-5,.012,p.z-3);g.updateMatrixWorld(true);const worldTarget=g.localToWorld(target.clone());
    for(const aspect of[.8,1.65]){cameraChecks++;const pose=flowerInspectionView(g,aspect,40);assert.ok(pose);assert.ok(new Vector3(...pose.target).distanceTo(worldTarget)<1e-9,'zero offset targets actual surface');const camera=new PerspectiveCamera(40,aspect,.01,650);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.ok(hit?.object===lip,label+' selected lip is the first visible hit');assert.equal(hit.instanceId,observedInstance);assert.ok(hit.point.distanceTo(worldTarget)<2e-6);
     const projected=new Vector3();for(const organ of[tube,hood,lip]){organ.getMatrixAt(observedInstance,matrix);matrix.premultiply(organ.matrixWorld);const organPos=organ.geometry.getAttribute('position');for(let j=0;j<organPos.count;j++){projected.fromBufferAttribute(organPos,j).applyMatrix4(matrix).project(camera);assert.ok(Math.abs(projected.x)<=.98&&Math.abs(projected.y)<=.98&&projected.z>=-1&&projected.z<=1,label+' selected flower organs fit viewport');}}
    }saved.push({...structuredClone(p),id:627000+ei*2+si});
   }assert.deepEqual(p,before);
  }finally{dispose(g);}
 }}assert.equal(models,48);assert.equal(cameraChecks,8);
 const doc=emptyDocument(10,6);doc.plans.A.plants=saved;doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.12'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
});

test('Nuda and Tuberosa saved dimensions bound attached opposite leaves and winter basal pairs through months and legal minima',()=>{
 const entries=[['p-d01134b29939',62710,[[1,.5,.35],[.18,.25,.06]]],['p-99357da7e268',62720,[[.7,.5,.25],[.15,.22,.05]]]],tiny=[[.01,.1,.005],[.5,.1,.005],[.01,.6,.005]],eps=1e-7,attachEps2=(2e-7)**2;let models=0,directPairs=0;
 const check=(id,pid,dims,month)=>{
  const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={...view(month),year:1},st=stateAt(p,v),g=plantModel(p,v),matrix=new Matrix4(),point=new Vector3(),segments=[],blades=[],petioleBases=[],petioleTips=[],label=dims.join('/')+' month='+month;let leaves=0,petioles=0,vertices=0;models++;
  try{g.updateMatrixWorld(true);g.traverse(mesh=>{
   if(!mesh.isMesh)return;const pos=mesh.geometry.getAttribute('position'),normal=mesh.geometry.getAttribute('normal'),tag=mesh.userData.component,leaf=/^(leaf-nuda|leaf-tuberosa|leaf-tall-nepeta-winter)$/.test(tag),petiole=tag.startsWith('petiole-tall-nepeta'),shoot=/^(stem|branch|axis)-tall-nepeta$/.test(tag),count=mesh.isInstancedMesh?mesh.count:1;
   assert.ok(pos&&normal&&normal.array.every(Number.isFinite),label+' finite geometry normals');if(/winter/.test(tag))assert.ok([12,1,2].includes(month),label+' basal organs only in existing winter months');if(mesh.isInstancedMesh)assert.ok(mesh.instanceMatrix.array.every(Number.isFinite));if(mesh.instanceColor)assert.ok(mesh.instanceColor.array.every(Number.isFinite));if(leaf){leaves+=count;assert.ok(mesh.geometry.userData[id==='p-99357da7e268'?'tuberosaLeaf':'nudaLeaf']);}if(petiole)petioles+=count;
   for(let i=0;i<count;i++){if(mesh.isInstancedMesh){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);}else matrix.copy(mesh.matrixWorld);
    if(shoot)segments.push(new Line3(new Vector3(0,-.5,0).applyMatrix4(matrix),new Vector3(0,.5,0).applyMatrix4(matrix)));if(leaf)blades.push(new Vector3().applyMatrix4(matrix));if(petiole){petioleBases.push(new Vector3(0,-.5,0).applyMatrix4(matrix));petioleTips.push(new Vector3(0,.5,0).applyMatrix4(matrix));}
    for(let j=0;j<pos.count;j++){point.fromBufferAttribute(pos,j).applyMatrix4(matrix);vertices++;if(!point.toArray().every(Number.isFinite))assert.fail(label+' nonfinite '+tag);if(point.y < -eps||point.y>st.height+eps)assert.fail(label+' ground/height '+tag+' '+point.y);if(Math.hypot(point.x,point.z)*2>st.spread+eps)assert.fail(label+' spread '+tag);if((leaf||petiole)&&point.y>Math.min(st.height,st.leafHeight)+eps)assert.fail(label+' leaf ceiling '+tag+' '+point.y);}
   }
  });assert.ok(vertices>0&&segments.length>0);assert.ok(leaves>0,label+' retained opposite leaves or winter basal pairs');assert.equal(g.children.some(m=>m.userData.component==='leaf-tall-nepeta-winter'),[12,1,2].includes(month),label+' existing winter basal leaves retained');assert.equal(leaves%2,0);assert.equal(petioles%2,0);assert.ok(petioles<=leaves);const matched=(p,ends)=>ends.some(end=>p.distanceToSquared(end)<=attachEps2),onShoot=p=>segments.some(line=>line.closestPointToPoint(p,true,new Vector3()).distanceToSquared(p)<=attachEps2),direct=blades.filter(p=>!matched(p,petioleTips));
   for(const p of blades)assert.ok(matched(p,petioleTips)||onShoot(p),label+' blade attached to matching petiole or actual stem');for(const p of petioleBases)assert.ok(onShoot(p),label+' petiole begins on real shoot');for(const p of petioleTips)assert.ok(matched(p,blades),label+' petiole supports a retained blade');assert.equal(direct.length,leaves-petioles);assert.equal(direct.length%2,0);for(const p of direct){assert.ok(onShoot(p));const sameNode=direct.filter(q=>p.distanceToSquared(q)<=attachEps2).length;assert.ok(sameNode>=2&&sameNode%2===0,label+' complete existing pairs at direct node');}directPairs+=direct.length/2;assert.deepEqual(p,before);
  }finally{dispose(g);}
 };
 for(const[id,pid,sizes]of entries){for(const dims of sizes)for(let month=1;month<=12;month++)check(id,pid,dims,month);for(const dims of tiny)for(const month of[6,10])check(id,pid,dims,month);}assert.equal(models,60);assert.ok(directPairs>0,'legal minima exercise complete direct pairs');
 const doc=emptyDocument(24,6);doc.plans.A.plants=entries.flatMap(([id,pid,sizes])=>[...sizes,...tiny].map(dims=>({id,dims}))).map(({id,dims},i)=>({...makePlant(id,627100+i,1+i*1.8,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.12'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 console.log('TALL_NEPETA_627_CAPS '+JSON.stringify({models,directPairs}));
});

test('Engei Six Hills Giant indicative height remains a source note while saved reference inputs and the other listing keep their own bounds',()=>{
 const id='p-38412b54ce8d',info=CATALOG[id],a=APPEARANCE_DATA[id],other=CATALOG['p-93be65945f4d'];assert.equal(info.height,null);assert.equal(info.spread,null);assert.match(info.care,/80cm/);assert.match(info.care,/上下限/);assert.match(info.care,/未確認/);assert.equal(info.source,'https://www.engei.net/products/detail?id=101144');assert.equal(info.sourceChecked,'2026-10-24');assert.equal(info.bloomKnown,true);assert.deepEqual(info.bloom,[4,5,6,7,8,9,10]);assert.equal(a.status,'partial');assert.equal(a.architecture,'giantCatmintShoots');assert.equal(a.shootProfile,'sixHills');assert.ok(a.unconfirmed.some(x=>x.includes('80cm')&&x.includes('上下限')));assert.deepEqual(other.height,[.7,.9]);assert.deepEqual(other.spread,[.6,.9]);assert.equal(other.sourceChecked,'2026-10-14');
 const doc=emptyDocument(10,6);
 for(const[i,dims]of [[.8,.75,.30],[.16,.24,.05]].entries()){const p={...makePlant(id,628000+i,2+i*3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p);for(const reference of[false,true]){const s=stateAt(p,{month:6,year:1,reference});assert.deepEqual([s.height,s.spread,s.leafHeight],dims,'unknown ranges keep supplied dimensions instead of inventing fixed height');assert.match(s.basis,/年次成長は未設定/);}assert.deepEqual(p,before);doc.plans.A.plants.push(p);}doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.13'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
});

test('Six Hills Giant listings focus actual visible lower lips across saved sizes seasons and viewport shapes',()=>{
 const entries=[['p-93be65945f4d',62910,'ogis',[[.8,.75,.30],[.16,.24,.05]]],['p-38412b54ce8d',62920,'engei',[[.8,.75,.30],[.16,.24,.05]]]],saved=[];let models=0,cameraChecks=0;for(const[ei,[id,pid,profile,sizes]]of entries.entries()){
 assert.deepEqual(CATALOG[id].appearance.flowerMonths,profile==='ogis'?[5,6,7,8,9,10,11]:[4,5,6,7,8,9,10]);assert.deepEqual(CATALOG[id].height,profile==='ogis'?[.7,.9]:null);assert.deepEqual(CATALOG[id].spread,profile==='ogis'?[.6,.9]:null);assert.equal(CATALOG[id].appearance.status,'partial');
 for(const[si,dims]of sizes.entries())for(let month=1;month<=12;month++){
  const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={...view(month),year:1},st=stateAt(p,v),g=plantModel(p,v),label=profile+' '+dims.join('/')+' month='+month;models++;
  try{assert.equal(g.userData.architecture,'giantCatmintShoots');assert.equal(g.userData.flowerTargets?.length??0,st.bloom?1:0,label+' actual flower target exists only while blooming');if(!st.bloom)assert.equal(flowerInspectionView(g,.8,40),null);for(const m of g.children)for(const a of[m.instanceMatrix.array,m.geometry.getAttribute('position').array,m.geometry.getAttribute('normal').array])assert.ok(a.every(Number.isFinite),label+' finite organ data');
   if(month===6){
    g.updateMatrixWorld(true);const matrix=new Matrix4(),point=new Vector3();let top=-Infinity,radius=0,ground=Infinity,leafTop=-Infinity,petioleTop=-Infinity,vertices=0;
    for(const m of g.children){const pos=m.geometry.getAttribute('position'),leaf=/^(leaf-catmint|leaf-catmint-winter)$/.test(m.userData.component),petiole=m.userData.component.startsWith('petiole-catmint');for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);matrix.premultiply(m.matrixWorld);for(let j=0;j<pos.count;j++){point.fromBufferAttribute(pos,j).applyMatrix4(matrix);vertices++;assert.ok(point.toArray().every(Number.isFinite));top=Math.max(top,point.y);ground=Math.min(ground,point.y);radius=Math.max(radius,Math.hypot(point.x,point.z));if(leaf)leafTop=Math.max(leafTop,point.y);if(petiole)petioleTop=Math.max(petioleTop,point.y);}}}
    console.log('SIX_HILLS_629_DIMENSIONS '+JSON.stringify({profile,size:si?'small':'large',input:{height:st.height,spread:st.spread,leafHeight:st.leafHeight},actualHeight:top,actualSpread:radius*2,actualLeafHeight:leafTop,actualPetioleHeight:petioleTop,ground,vertices}));
    assert.equal(flowerInspectionDistanceFloor(g),.020);const anchor=g.userData.flowerTargets[0],target=new Vector3(...anchor.origin),lip=g.children.find(m=>m.userData.component==='petal-catmint'),hood=g.children.find(m=>m.userData.component==='hood-catmint'),tube=g.children.find(m=>m.userData.component==='tube-catmint'),index=26*25+12;assert.ok(lip?.count>0&&hood?.count===lip.count&&tube?.count===lip.count);const pos=lip.geometry.getAttribute('position');assert.ok(lip.geometry.userData.catmintLip);assert.equal(pos.count,33*25);let nearest=Infinity,observedInstance=-1;
    for(let i=0;i<lip.count;i++){lip.getMatrixAt(i,matrix);const distance=new Vector3().fromBufferAttribute(pos,index).applyMatrix4(matrix).distanceTo(target);if(distance<nearest){nearest=distance;observedInstance=i;}}assert.ok(nearest<2e-7,'target lies on actual row26/column12');lip.getMatrixAt(observedInstance,matrix);const axis=new Vector3().setFromMatrixColumn(matrix,2).normalize(),fl=new Vector3().setFromMatrixColumn(matrix,0).length();assert.ok(axis.dot(new Vector3(...anchor.axis))>1-1e-6);assert.ok(Math.abs(anchor.radius-fl*1.2)<2e-7);
    g.position.set(p.x-5,.012,p.z-3);g.updateMatrixWorld(true);const worldTarget=g.localToWorld(target.clone());
    for(const aspect of[.8,1.65]){cameraChecks++;const pose=flowerInspectionView(g,aspect,40);assert.ok(pose);assert.ok(new Vector3(...pose.target).distanceTo(worldTarget)<1e-9,'zero offset targets actual surface');const camera=new PerspectiveCamera(40,aspect,.01,650);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.ok(hit?.object===lip,label+' selected lip is the first visible hit');assert.equal(hit.instanceId,observedInstance);assert.ok(hit.point.distanceTo(worldTarget)<2e-6);
     const projected=new Vector3();for(const organ of[tube,hood,lip]){organ.getMatrixAt(observedInstance,matrix);matrix.premultiply(organ.matrixWorld);const organPos=organ.geometry.getAttribute('position');for(let j=0;j<organPos.count;j++){projected.fromBufferAttribute(organPos,j).applyMatrix4(matrix).project(camera);assert.ok(Math.abs(projected.x)<=.98&&Math.abs(projected.y)<=.98&&projected.z>=-1&&projected.z<=1,label+' selected flower organs fit viewport');}}
    }saved.push({...structuredClone(p),id:629000+ei*2+si});
   }assert.deepEqual(p,before);
  }finally{dispose(g);}
 }}assert.equal(models,48);assert.equal(cameraChecks,8);
 const doc=emptyDocument(10,6);doc.plans.A.plants=saved;doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.14'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
});

test('Six Hills Giant saved dimensions bound attached opposite leaves and winter basal pairs through months and legal minima',()=>{
 const entries=[['p-93be65945f4d',62910,[[.8,.75,.30],[.16,.24,.05]]],['p-38412b54ce8d',62920,[[.8,.75,.30],[.16,.24,.05]]]],tiny=[[.01,.1,.005],[.5,.1,.005],[.01,.6,.005]],eps=1e-7,attachEps2=(2e-7)**2;let models=0,directPairs=0;
 const check=(id,pid,dims,month)=>{
  const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={...view(month),year:1},st=stateAt(p,v),g=plantModel(p,v),matrix=new Matrix4(),point=new Vector3(),segments=[],blades=[],petioleBases=[],petioleTips=[],label=dims.join('/')+' month='+month;let leaves=0,petioles=0,vertices=0;models++;
  try{g.updateMatrixWorld(true);g.traverse(mesh=>{
   if(!mesh.isMesh)return;const pos=mesh.geometry.getAttribute('position'),normal=mesh.geometry.getAttribute('normal'),tag=mesh.userData.component,leaf=/^(leaf-catmint|leaf-catmint-winter)$/.test(tag),petiole=tag.startsWith('petiole-catmint'),shoot=/^(stem|branch|axis)-catmint$/.test(tag),count=mesh.isInstancedMesh?mesh.count:1;
   assert.ok(pos&&normal&&normal.array.every(Number.isFinite),label+' finite geometry normals');if(/winter/.test(tag))assert.ok([12,1,2].includes(month),label+' basal organs only in existing winter months');if(mesh.isInstancedMesh)assert.ok(mesh.instanceMatrix.array.every(Number.isFinite));if(mesh.instanceColor)assert.ok(mesh.instanceColor.array.every(Number.isFinite));if(leaf){leaves+=count;assert.ok(mesh.geometry.userData.giantCatmintLeaf);}if(petiole)petioles+=count;
   for(let i=0;i<count;i++){if(mesh.isInstancedMesh){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);}else matrix.copy(mesh.matrixWorld);
    if(shoot)segments.push(new Line3(new Vector3(0,-.5,0).applyMatrix4(matrix),new Vector3(0,.5,0).applyMatrix4(matrix)));if(leaf)blades.push(new Vector3().applyMatrix4(matrix));if(petiole){petioleBases.push(new Vector3(0,-.5,0).applyMatrix4(matrix));petioleTips.push(new Vector3(0,.5,0).applyMatrix4(matrix));}
    for(let j=0;j<pos.count;j++){point.fromBufferAttribute(pos,j).applyMatrix4(matrix);vertices++;if(!point.toArray().every(Number.isFinite))assert.fail(label+' nonfinite '+tag);if(point.y < -eps||point.y>st.height+eps)assert.fail(label+' ground/height '+tag+' '+point.y);if(Math.hypot(point.x,point.z)*2>st.spread+eps)assert.fail(label+' spread '+tag);if((leaf||petiole)&&point.y>Math.min(st.height,st.leafHeight)+eps)assert.fail(label+' leaf ceiling '+tag+' '+point.y);}
   }
  });assert.ok(vertices>0&&segments.length>0);assert.ok(leaves>0,label+' retained opposite leaves or winter basal pairs');assert.equal(g.children.some(m=>m.userData.component==='leaf-catmint-winter'),[12,1,2].includes(month),label+' existing winter basal leaves retained');assert.equal(leaves%2,0);assert.equal(petioles%2,0);assert.ok(petioles<=leaves);const matched=(p,ends)=>ends.some(end=>p.distanceToSquared(end)<=attachEps2),onShoot=p=>segments.some(line=>line.closestPointToPoint(p,true,new Vector3()).distanceToSquared(p)<=attachEps2),direct=blades.filter(p=>!matched(p,petioleTips));
   for(const p of blades)assert.ok(matched(p,petioleTips)||onShoot(p),label+' blade attached to matching petiole or actual stem');for(const p of petioleBases)assert.ok(onShoot(p),label+' petiole begins on real shoot');for(const p of petioleTips)assert.ok(matched(p,blades),label+' petiole supports a retained blade');assert.equal(direct.length,leaves-petioles);assert.equal(direct.length%2,0);for(const p of direct){assert.ok(onShoot(p));const sameNode=direct.filter(q=>p.distanceToSquared(q)<=attachEps2).length;assert.ok(sameNode>=2&&sameNode%2===0,label+' complete existing pairs at direct node');}directPairs+=direct.length/2;assert.deepEqual(p,before);
  }finally{dispose(g);}
 };
 for(const[id,pid,sizes]of entries){for(const dims of sizes)for(let month=1;month<=12;month++)check(id,pid,dims,month);for(const dims of tiny)for(const month of[6,10])check(id,pid,dims,month);}assert.equal(models,60);assert.ok(directPairs>0,'legal minima exercise complete direct pairs');
 const doc=emptyDocument(24,6);doc.plans.A.plants=entries.flatMap(([id,pid,sizes])=>[...sizes,...tiny].map(dims=>({id,dims}))).map(({id,dims},i)=>({...makePlant(id,629100+i,1+i*1.8,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.14'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 console.log('SIX_HILLS_629_CAPS '+JSON.stringify({models,directPairs}));
});

