test('Explicit surface inspection distances are finite and bounded while existing architecture defaults remain intact',()=>{
 assert.equal(flowerInspectionDistanceFloor({userData:{surfaceInspectionDistance:.035}}),.035);assert.equal(flowerInspectionDistanceFloor({userData:{surfaceInspectionDistance:.012}}),.012);assert.equal(flowerInspectionDistanceFloor({userData:{surfaceInspectionDistance:.14}}),.14);
 for(const value of[null,undefined,NaN,Infinity,-1,0,.011,.141,'0.035']){assert.equal(flowerInspectionDistanceFloor({userData:{surfaceInspectionDistance:value}}),.14);assert.equal(flowerInspectionDistanceFloor({userData:{architecture:'physostegiaRows',surfaceInspectionDistance:value}}),.08);}
 assert.equal(flowerInspectionDistanceFloor({userData:{architecture:'officinalisMounds'}}),.14);assert.equal(flowerInspectionDistanceFloor({userData:{architecture:'cherrySageBranches'}}),.14);
});

test('Violin Music closeup tones use working-linear colours only on the three existing corolla components while preserving the saved plan',()=>{
 const palette={lip:'#8f62bf',pale:'#d3c7dc',tip:'#65478e',tube:'#c7b9d5'};let models=0;
 for(const dims of[[.6,.5,.30],[.12,.18,.04]]){const p={...makePlant('p-1d9f9cba7fba',64220,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),g=plantModel(p,{...view(6),year:1});models++;try{let organs=0;for(const m of g.children){const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});const code=shader.fragmentShader,tag=m.userData.component;assert.ok(!code.includes('\\n'));const type=tag==='petal-cherry-violin'?'lip':tag==='hood-cherry-violin'?'hood':tag==='tube-cherry-violin'?'tube':null;if(!type){assert.ok(!code.includes('vmLip')&&!code.includes('vmPale')&&!code.includes('vmTube'),'other components keep their original paint');continue;}organs++;assert.ok(code.includes('vUv.y'));for(const key of type==='hood'?['pale','tip']:[type]){const values=new Color(palette[key]).toArray().map(v=>v.toFixed(8)).join(',');assert.ok(code.includes('vec3('+values+')'),type+' colour is converted from sRGB to the working-linear space');}if(type==='hood'){assert.ok(code.includes('1.0-smoothstep(.42,.90,vUv.y)'),'hood base is pale');assert.ok(code.includes('smoothstep(.62,.96,vUv.y)'),'darker tip is confined toward the end');assert.ok(code.includes('vmHair'),'hair is a bounded surface tone, without extra reproductive organs');}if(type==='tube')assert.ok(code.includes('smoothstep(.08,.32,vUv.y)*(1.0-smoothstep(.78,.98,vUv.y))'),'tube end rings retain their base colour');}assert.equal(organs,3);assert.deepEqual(p,before);}finally{dispose(g);}}
 assert.equal(models,2);const doc=emptyDocument(10,6);doc.plans.A.plants=[[.6,.5,.30],[.12,.18,.04]].map((dims,i)=>({...makePlant('p-1d9f9cba7fba',643000+i,2+i*3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.28'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
});

