test('Common and Purple Sage observations reach actual visible lower-lip triangle centres at saved and known reference sizes',()=>{
 let models=0,cameraChecks=0;const saved=[];
 const check=(c,dims,month,reference=false)=>{
  const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={month,year:1,reference},s=stateAt(p,v),g=plantModel(p,v),label=c.label+' '+dims.join('/')+' month='+month+' reference='+reference;models++;
  try{assert.equal(g.userData.architecture,c.architecture);assert.equal(g.userData.surfaceInspectionDistance,.035);assert.equal(flowerInspectionDistanceFloor(g),.035);assert.equal(g.userData.flowerTargets?.length??0,s.bloom?1:0,label);for(const m of g.children)for(const a of[m.instanceMatrix.array,m.geometry.getAttribute('position').array,m.geometry.getAttribute('normal').array])assert.ok(a.every(Number.isFinite),label+' finite organs');
   if(!s.bloom)assert.equal(flowerInspectionView(g,.8,40),null);
   if(month===6){
    const lip=g.children.find(m=>m.userData.component===c.lip),tube=g.children.find(m=>m.userData.component===c.tube),hood=g.children.find(m=>m.userData.component===c.hood);assert.ok(lip?.count>0&&tube?.count===lip.count&&hood?.count===lip.count);assert.ok(lip.geometry.userData[c.lipFlag]);const pos=lip.geometry.getAttribute('position'),ix=lip.geometry.getIndex(),row=32,col=c.cols/2,k=row*(c.cols+1)+col,face=(row*c.cols+col)*2,ids=[ix.getX(face*3),ix.getX(face*3+1),ix.getX(face*3+2)];assert.equal(pos.count,49*(c.cols+1));assert.deepEqual(ids,[k,k+c.cols+1,k+1],'exact existing indexed triangle');
    const anchor=g.userData.flowerTargets[0],target=new Vector3(...anchor.origin),matrix=new Matrix4();let best=Infinity,instance=-1,normal,fl;
    for(let i=0;i<lip.count;i++){lip.getMatrixAt(i,matrix);const vs=ids.map(j=>new Vector3().fromBufferAttribute(pos,j).applyMatrix4(matrix)),centre=vs[0].clone().add(vs[1]).add(vs[2]).multiplyScalar(1/3),distance=centre.distanceTo(target);if(distance<best){best=distance;instance=i;normal=vs[1].clone().sub(vs[0]).cross(vs[2].clone().sub(vs[0])).normalize();fl=new Vector3().setFromMatrixColumn(matrix,0).length()/c.lipX;}}assert.ok(best<2e-7,label+' anchor is an actual Float32 triangle centre');assert.ok(normal.dot(new Vector3(...anchor.axis))>1-1e-6,label+' camera axis follows actual lip face');assert.ok(Math.abs(anchor.radius-fl*1.30)<2e-7);
    g.position.set(-2,.012,0);g.updateMatrixWorld(true);const worldTarget=g.localToWorld(target.clone());for(const aspect of[.8,1.65]){cameraChecks++;const pose=flowerInspectionView(g,aspect,40);assert.ok(pose);assert.ok(new Vector3(...pose.target).distanceTo(worldTarget)<1e-9,'surface marker has no forward offset');const camera=new PerspectiveCamera(40,aspect,.01,650);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.ok(hit?.object===lip,label+' lower lip is first visible hit');assert.equal(hit.instanceId,instance);assert.ok(hit.point.distanceTo(worldTarget)<2e-6,label+' centre ray reaches marker');for(const organ of[tube,hood,lip]){organ.getMatrixAt(instance,matrix);matrix.premultiply(organ.matrixWorld);const pp=organ.geometry.getAttribute('position'),point=new Vector3();for(let j=0;j<pp.count;j++){point.fromBufferAttribute(pp,j).applyMatrix4(matrix).project(camera);assert.ok(Math.abs(point.x)<=.98&&Math.abs(point.y)<=.98&&point.z>=-1&&point.z<=1,label+' selected corolla fits viewport');}}}
    if(!reference)saved.push({...structuredClone(p),id:644000+saved.length});
   }assert.deepEqual(p,before);
  }finally{dispose(g);}
 };
 for(const c of SAGE_SURFACE_CASES_644){assert.deepEqual(CATALOG[c.id].appearance.flowerMonths,c.months);assert.equal(CATALOG[c.id].appearance.status,'partial');assert.equal(CATALOG[c.id].sourceChecked,'2026-10-10');for(const dims of c.sizes)for(let month=1;month<=12;month++)check(c,dims,month);}for(const c of SAGE_SURFACE_CASES_644)check(c,c.sizes[1],6,true);assert.equal(models,50);assert.equal(cameraChecks,12);
 const doc=emptyDocument(10,6);doc.plans.A.plants=saved;doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.29'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 console.log('SAGES_644_OBSERVATIONS '+JSON.stringify({models,cameraChecks,knownReferenceModels:2}));
});
test('Common and Purple Sage independent dimensions bound attached foliage on real wood stems and branches through legal minima',()=>{
 const tiny=[[.01,.1,.005],[.5,.1,.005],[.01,.6,.005],[.01,.1,.006]],eps=1e-7,attachEps2=(2e-7)**2;let models=0,directPairs=0;const diagnostics=[];
 const check=(c,dims,month)=>{
  const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={month,year:1,reference:false},s=stateAt(p,v),g=plantModel(p,v),matrix=new Matrix4(),point=new Vector3(),segments=[],blades=[],petioleBases=[],petioleTips=[],label=c.label+' '+dims.join('/')+' month='+month;let leaves=0,petioles=0,top=-Infinity,ground=Infinity,radius=0,leafTop=-Infinity,petioleTop=-Infinity,vertices=0;models++;
  try{g.updateMatrixWorld(true);g.traverse(mesh=>{
   if(!mesh.isMesh)return;const pos=mesh.geometry.getAttribute('position'),normal=mesh.geometry.getAttribute('normal'),tag=mesh.userData.component,leaf=c.leaf.test(tag),petiole=c.petiole.test(tag),shoot=/^(wood|stem|branch|axis|twig)-(officinalis|cherry)$/.test(tag),count=mesh.isInstancedMesh?mesh.count:1;assert.ok(pos&&normal&&normal.array.every(Number.isFinite),label+' finite normals');assert.ok(!tag.includes('-winter'),'no new basal winter organs');if(mesh.isInstancedMesh)assert.ok(mesh.instanceMatrix.array.every(Number.isFinite));if(mesh.instanceColor)assert.ok(mesh.instanceColor.array.every(Number.isFinite));if(leaf){leaves+=count;assert.ok(mesh.geometry.userData[c.leafFlag]);}if(petiole)petioles+=count;
   for(let i=0;i<count;i++){if(mesh.isInstancedMesh){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);}else matrix.copy(mesh.matrixWorld);if(shoot)segments.push(new Line3(new Vector3(0,-.5,0).applyMatrix4(matrix),new Vector3(0,.5,0).applyMatrix4(matrix)));if(leaf)blades.push(new Vector3().applyMatrix4(matrix));if(petiole){petioleBases.push(new Vector3(0,-.5,0).applyMatrix4(matrix));petioleTips.push(new Vector3(0,.5,0).applyMatrix4(matrix));}
    for(let j=0;j<pos.count;j++){point.fromBufferAttribute(pos,j).applyMatrix4(matrix);vertices++;assert.ok(point.toArray().every(Number.isFinite));assert.ok(point.y>=-eps&&point.y<=s.height+eps,label+' ground/height '+tag);assert.ok(Math.hypot(point.x,point.z)*2<=s.spread+eps,label+' spread '+tag);if(leaf||petiole)assert.ok(point.y<=Math.min(s.height,s.leafHeight)+eps,label+' leaf ceiling '+tag);top=Math.max(top,point.y);ground=Math.min(ground,point.y);radius=Math.max(radius,Math.hypot(point.x,point.z));if(leaf)leafTop=Math.max(leafTop,point.y);if(petiole)petioleTop=Math.max(petioleTop,point.y);}
   }
  });assert.ok(vertices>0&&segments.length>0);if(s.leafHeight<=c.root)assert.equal(leaves,0,label+' omit zero-clearance leaves');else assert.ok(leaves>0,label+' retain paired foliage');assert.equal(leaves%2,0);assert.equal(petioles%2,0);assert.ok(petioles<=leaves);const matched=(p,ends)=>ends.some(end=>p.distanceToSquared(end)<=attachEps2),onShoot=p=>segments.some(line=>line.closestPointToPoint(p,true,new Vector3()).distanceToSquared(p)<=attachEps2),direct=blades.filter(p=>!matched(p,petioleTips));for(const p of blades)assert.ok(matched(p,petioleTips)||onShoot(p),label+' blade attached');for(const p of petioleBases)assert.ok(onShoot(p),label+' petiole starts on actual wood/shoot');for(const p of petioleTips)assert.ok(matched(p,blades),label+' petiole supports blade');assert.equal(direct.length,leaves-petioles);assert.equal(direct.length%2,0);for(const p of direct){assert.ok(onShoot(p));const n=direct.filter(q=>p.distanceToSquared(q)<=attachEps2).length;assert.ok(n>=2&&n%2===0,label+' complete direct pair');}directPairs+=direct.length/2;if(month===6&&c.sizes.includes(dims))diagnostics.push({id:c.id,dims,actualHeight:top,actualSpread:radius*2,actualLeafHeight:leafTop,actualPetioleHeight:petioleTop,ground,vertices});assert.deepEqual(p,before);
  }finally{dispose(g);}
 };
 for(const c of SAGE_SURFACE_CASES_644){for(const dims of c.sizes)for(let month=1;month<=12;month++)check(c,dims,month);for(const dims of tiny)for(const month of[6,10])check(c,dims,month);}assert.equal(models,64);assert.ok(directPairs>0);
 const doc=emptyDocument(24,6);doc.plans.A.plants=SAGE_SURFACE_CASES_644.flatMap(c=>[...c.sizes,...tiny].map(dims=>({id:c.id,dims}))).map(({id,dims},i)=>({...makePlant(id,644100+i,1+i*1.8,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.29'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 console.log('SAGES_644_CAPS '+JSON.stringify({models,directPairs,diagnostics}));
});

