{"id":"p-b1a5190c3968","pid":64620,"label":"night","architecture":"cherrySageBranches","sizes":[[0.4,0.4,0.24],[0.12,0.18,0.04]],"months":[5,6,7,8,9,10,11],"lip":"petal-cherry-night","tube":"tube-cherry-night","hood":"hood-cherry-night","lipFlag":"cherryLip","cols":24,"lipX":0.94,"leafFlag":"cherryJamensisLeaf","root":0.005,leaf:/^leaf-cherry-jamensis$/,petiole:/^petiole-cherry$/}
