test('Salmon Yellow and Night Moth winter nursery colour examples preserve warm leaves and honest source limits',()=>{
 const cases=[{id:'p-d1c41ce2384d',pid:64610,sizes:[[.35,.45,.22],[.12,.18,.04]],height:[.25,.4],spread:[.3,.5]},{id:'p-b1a5190c3968',pid:64620,sizes:[[.4,.4,.24],[.12,.18,.04]],height:[.3,.5],spread:[.3,.5]}];let models=0;const totals=[];
 for(const c of cases){let winterRed=0,winterGreen=0;const info=CATALOG[c.id],a=APPEARANCE_DATA[c.id];assert.equal(a.status,'partial');assert.equal(info.sourceChecked,'2026-10-10');assert.deepEqual(info.height,c.height);assert.deepEqual(info.spread,c.spread);assert.deepEqual(a.flowerMonths,[5,6,7,8,9,10,11]);assert.ok(a.unconfirmed.some(x=>x.includes('低温管理されたポット苗写真')&&x.includes('無剪定の成株')&&x.includes('未確認')));
  for(const dims of c.sizes)for(const month of[12,1,2,3,6,10]){const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),g=plantModel(p,{month,year:1,reference:false});models++;try{const leaf=g.children.find(m=>m.userData.component==='leaf-cherry-jamensis');assert.ok(leaf&&leaf.count>0&&leaf.geometry.userData.cherryJamensisLeaf);let red=0,green=0;const colour=new Color();for(let i=0;i<leaf.count;i++){leaf.getColorAt(i,colour);assert.ok([colour.r,colour.g,colour.b].every(x=>Number.isFinite(x)&&x>=0&&x<=1));if(colour.r>colour.g*1.3)red++;else green++;}if([12,1,2].includes(month)){assert.ok(red>0,c.id+' '+month+' red retained leaf');winterRed+=red;winterGreen+=green;}else assert.equal(red,0,c.id+' '+month+' unchanged warm green');assert.deepEqual(p,before);}finally{dispose(g);}}
  assert.ok(winterRed>0&&winterGreen>0);totals.push({id:c.id,winterRed,winterGreen});
 }assert.equal(models,24);console.log('SAGES_652_WINTER_COLOUR '+JSON.stringify({models,totals}));
});

test('Moonlight and So Cool flower photos guide bounded working-linear lip and tube tones without altering saved plants',()=>{
 const cases=[{id:'p-a2c155eac0a4',pid:64910,types:{'petal-cherry-moonlight':['mlCentre','#f2f0e8','#e4b2d1']}},{id:'p-31fc17a4aa55',pid:64920,types:{'petal-cherry-soCool':['scLip','#c8bfee'],'tube-cherry-soCool':['scTube','#7957b5']}}];let models=0;
 for(const c of cases)for(const dims of[[.5,.45,.25],[.12,.18,.04]]){const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),g=plantModel(p,{month:6,year:1,reference:false});models++;try{let painted=0;for(const m of g.children){const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});const code=shader.fragmentShader,paint=c.types[m.userData.component];assert.ok(!code.includes('\\n'));if(!paint){assert.ok(!/mlCentre|scLip|scTube/.test(code),'other organs retain their programs');continue;}painted++;assert.ok(code.includes(paint[0]));for(const colour of paint.slice(1)){const linear=new Color(colour).toArray().map(v=>v.toFixed(8)).join(',');assert.ok(code.includes('vec3('+linear+')'),'sRGB display tint converted to working-linear space');}if(paint[0]==='mlCentre'){assert.ok(code.includes('abs(vUv.x-.5)'));assert.ok(code.includes('smoothstep(.86,.98,vUv.y)'));assert.ok(code.includes('mlEdge*.45'));}if(paint[0]==='scTube')assert.ok(code.includes('smoothstep(.08,.30,vUv.y)*(1.0-smoothstep(.84,.99,vUv.y))'));}assert.equal(painted,Object.keys(c.types).length);assert.deepEqual(p,before);assert.equal(CATALOG[c.id].sourceChecked,'2026-10-13');assert.equal(CATALOG[c.id].appearance.status,'partial');assert.deepEqual(CATALOG[c.id].appearance.flowerMonths,[5,6,7,8,9,10,11]);}finally{dispose(g);}}
 assert.equal(models,4);const doc=emptyDocument(10,6);doc.plans.A.plants=cases.map((c,i)=>({...makePlant(c.id,653000+i,2+i*3,3),height:.5,spread:.45,leafHeight:.25}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.38'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
});

const SAGE_SURFACE_CASES_654=[
{"id":"p-9bc739787fc7","pid":65410,"label":"gentian","architecture":"patensShoots","sizes":[[0.5,0.4,0.3],[0.12,0.18,0.04]],"months":[5,6,7,8,9,10,11],"modes":["open"],"leafFlag":"patensLeaf","root":0.005,leaf:/^leaf-patens$/,petiole:/^petiole-patens$/},
{"id":"p-5a3386ff68f9","pid":65420,"label":"cambridge","architecture":"patensShoots","sizes":[[0.5,0.4,0.3],[0.12,0.18,0.04]],"months":[5,6,7,8,9,10,11],"modes":["open"],"leafFlag":"patensLeaf","root":0.005,leaf:/^leaf-patens$/,petiole:/^petiole-patens$/}
];
test('Gentian Patens and Cambridge Blue observations reach actual visible lower-lip triangle centres at saved and known reference sizes',()=>{
 let models=0,cameraChecks=0;const saved=[];
 const check=(c,dims,month,reference=false)=>{
  const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={month,year:1,reference},s=stateAt(p,v),g=plantModel(p,v),label=c.label+' '+dims.join('/')+' month='+month+' reference='+reference;models++;
  try{if(s.groundDormant)assert.equal(g.children.length,0);else assert.equal(g.userData.architecture,c.architecture);assert.equal(g.userData.surfaceInspectionDistance,.035);assert.equal(flowerInspectionDistanceFloor(g),.035);assert.equal(g.userData.flowerTargets?.length??0,s.bloom?1:0,label);for(const m of g.children)for(const a of[m.instanceMatrix.array,m.geometry.getAttribute('position').array,m.geometry.getAttribute('normal').array])assert.ok(a.every(Number.isFinite),label+' finite organs');
   if(!s.bloom)assert.equal(flowerInspectionView(g,.8,40),null);
   if(month===6){
    const lips=g.children.filter(m=>m.userData.component.startsWith('petal-patens-lip-'));assert.ok(lips.length>0);const anchor=g.userData.flowerTargets[0],target=new Vector3(...anchor.origin),matrix=new Matrix4(),ids=[682,703,683];let best=Infinity,instance=-1,normal,fl,lip;
    for(const candidate of lips){const mode=candidate.userData.component.slice('petal-patens-lip-'.length);assert.ok(c.modes.includes(mode));assert.ok(candidate.geometry.userData.patensLip);const pos=candidate.geometry.getAttribute('position'),ix=candidate.geometry.getIndex();assert.equal(pos.count,1029);assert.deepEqual([0,1,2].map(j=>ix.getX(1300*3+j)),ids,'exact existing indexed triangle');for(let i=0;i<candidate.count;i++){candidate.getMatrixAt(i,matrix);const vs=ids.map(j=>new Vector3().fromBufferAttribute(pos,j).applyMatrix4(matrix)),centre=vs[0].clone().add(vs[1]).add(vs[2]).multiplyScalar(1/3),distance=centre.distanceTo(target);if(distance<best){best=distance;instance=i;lip=candidate;normal=vs[1].clone().sub(vs[0]).cross(vs[2].clone().sub(vs[0])).normalize();fl=new Vector3().setFromMatrixColumn(matrix,0).length();}}}
    assert.ok(best<2e-7,label+' anchor is an actual triangle centre in its mixed-colour batch');assert.ok(normal.dot(new Vector3(...anchor.axis))>1-1e-6);assert.ok(Math.abs(anchor.radius-fl*1.30)<2e-7);const mode=lip.userData.component.slice('petal-patens-lip-'.length),tube=g.children.find(m=>m.userData.component==='tube-patens-'+mode),hood=g.children.find(m=>m.userData.component==='petal-patens-hood-'+mode);assert.equal(tube?.count,lip.count);assert.equal(hood?.count,lip.count);
    g.position.set(-2,.012,0);g.updateMatrixWorld(true);const worldTarget=g.localToWorld(target.clone());for(const aspect of[.8,1.65]){cameraChecks++;const pose=flowerInspectionView(g,aspect,40);assert.ok(pose);assert.ok(new Vector3(...pose.target).distanceTo(worldTarget)<1e-9);const camera=new PerspectiveCamera(40,aspect,.01,650);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.ok(hit?.object===lip,label+' first visible hit is the selected lip colour batch');assert.equal(hit.instanceId,instance);assert.ok(hit.point.distanceTo(worldTarget)<2e-6);for(const organ of[tube,hood,lip]){organ.getMatrixAt(instance,matrix);matrix.premultiply(organ.matrixWorld);const pp=organ.geometry.getAttribute('position'),point=new Vector3();for(let j=0;j<pp.count;j++){point.fromBufferAttribute(pp,j).applyMatrix4(matrix).project(camera);assert.ok(Math.abs(point.x)<=.98&&Math.abs(point.y)<=.98&&point.z>=-1&&point.z<=1,label+' selected same-colour corolla fits viewport');}}}
    if(!reference)saved.push({...structuredClone(p),id:654000+saved.length});
   }assert.deepEqual(p,before);
  }finally{dispose(g);}
 };
 for(const c of SAGE_SURFACE_CASES_654){assert.deepEqual(CATALOG[c.id].appearance.flowerMonths,c.months);assert.equal(CATALOG[c.id].appearance.status,'partial');assert.equal(CATALOG[c.id].sourceChecked,'2026-10-13');for(const dims of c.sizes)for(let month=1;month<=12;month++)check(c,dims,month);}for(const c of SAGE_SURFACE_CASES_654)check(c,c.sizes[1],6,true);assert.equal(models,50);assert.equal(cameraChecks,12);
 const doc=emptyDocument(10,6);doc.plans.A.plants=saved;doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.39'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 console.log('PATENS_654_OBSERVATIONS '+JSON.stringify({models,cameraChecks,knownReferenceModels:2}));
});
test('Gentian Patens and Cambridge Blue independent dimensions bound attached foliage on real wood stems and branches through legal minima',()=>{
 const tiny=[[.01,.1,.005],[.5,.1,.005],[.01,.6,.005],[.01,.1,.006]],eps=1e-7,attachEps2=(2e-7)**2;let models=0,directPairs=0;const diagnostics=[];
 const check=(c,dims,month)=>{
  const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={month,year:1,reference:false},s=stateAt(p,v),g=plantModel(p,v),matrix=new Matrix4(),point=new Vector3(),segments=[],blades=[],petioleBases=[],petioleTips=[],label=c.label+' '+dims.join('/')+' month='+month;let leaves=0,petioles=0,top=-Infinity,ground=Infinity,radius=0,leafTop=-Infinity,petioleTop=-Infinity,vertices=0;models++;
  try{if(s.groundDormant){assert.equal(g.children.length,0);assert.deepEqual(p,before);return;}g.updateMatrixWorld(true);g.traverse(mesh=>{
   if(!mesh.isMesh)return;const pos=mesh.geometry.getAttribute('position'),normal=mesh.geometry.getAttribute('normal'),tag=mesh.userData.component,leaf=c.leaf.test(tag),petiole=c.petiole.test(tag),shoot=/^(stem|branch|axis)-patens$/.test(tag),count=mesh.isInstancedMesh?mesh.count:1;assert.ok(pos&&normal&&normal.array.every(Number.isFinite),label+' finite normals');assert.ok(!tag.includes('-winter'),'no new basal winter organs');if(mesh.isInstancedMesh)assert.ok(mesh.instanceMatrix.array.every(Number.isFinite));if(mesh.instanceColor)assert.ok(mesh.instanceColor.array.every(Number.isFinite));if(leaf){leaves+=count;assert.ok(mesh.geometry.userData[c.leafFlag]);}if(petiole)petioles+=count;
   for(let i=0;i<count;i++){if(mesh.isInstancedMesh){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);}else matrix.copy(mesh.matrixWorld);if(shoot)segments.push(new Line3(new Vector3(0,-.5,0).applyMatrix4(matrix),new Vector3(0,.5,0).applyMatrix4(matrix)));if(leaf)blades.push(new Vector3().applyMatrix4(matrix));if(petiole){petioleBases.push(new Vector3(0,-.5,0).applyMatrix4(matrix));petioleTips.push(new Vector3(0,.5,0).applyMatrix4(matrix));}
    for(let j=0;j<pos.count;j++){point.fromBufferAttribute(pos,j).applyMatrix4(matrix);vertices++;assert.ok(point.toArray().every(Number.isFinite));assert.ok(point.y>=-eps&&point.y<=s.height+eps,label+' ground/height '+tag);assert.ok(Math.hypot(point.x,point.z)*2<=s.spread+eps,label+' spread '+tag);if(leaf||petiole)assert.ok(point.y<=Math.min(s.height,s.leafHeight)+eps,label+' leaf ceiling '+tag);top=Math.max(top,point.y);ground=Math.min(ground,point.y);radius=Math.max(radius,Math.hypot(point.x,point.z));if(leaf)leafTop=Math.max(leafTop,point.y);if(petiole)petioleTop=Math.max(petioleTop,point.y);}
   }
  });assert.ok(vertices>0&&segments.length>0);if(s.leafHeight<=c.root)assert.equal(leaves,0,label+' omit zero-clearance leaves');else assert.ok(leaves>0,label+' retain paired foliage');assert.equal(leaves%2,0);assert.equal(petioles%2,0);assert.ok(petioles<=leaves);const matched=(p,ends)=>ends.some(end=>p.distanceToSquared(end)<=attachEps2),onShoot=p=>segments.some(line=>line.closestPointToPoint(p,true,new Vector3()).distanceToSquared(p)<=attachEps2),direct=blades.filter(p=>!matched(p,petioleTips));for(const p of blades)assert.ok(matched(p,petioleTips)||onShoot(p),label+' blade attached');for(const p of petioleBases)assert.ok(onShoot(p),label+' petiole starts on actual wood/shoot');for(const p of petioleTips)assert.ok(matched(p,blades),label+' petiole supports blade');assert.equal(direct.length,leaves-petioles);assert.equal(direct.length%2,0);for(const p of direct){assert.ok(onShoot(p));const n=direct.filter(q=>p.distanceToSquared(q)<=attachEps2).length;assert.ok(n>=2&&n%2===0,label+' complete direct pair');}directPairs+=direct.length/2;if(month===6&&c.sizes.includes(dims))diagnostics.push({id:c.id,dims,actualHeight:top,actualSpread:radius*2,actualLeafHeight:leafTop,actualPetioleHeight:petioleTop,ground,vertices});assert.deepEqual(p,before);
  }finally{dispose(g);}
 };
 for(const c of SAGE_SURFACE_CASES_654){for(const dims of c.sizes)for(let month=1;month<=12;month++)check(c,dims,month);for(const dims of tiny)for(const month of[6,10])check(c,dims,month);}assert.equal(models,64);assert.ok(directPairs>0);
 const doc=emptyDocument(24,6);doc.plans.A.plants=SAGE_SURFACE_CASES_654.flatMap(c=>[...c.sizes,...tiny].map(dims=>({id:c.id,dims}))).map(({id,dims},i)=>({...makePlant(id,654100+i,1+i*1.8,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.39'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 console.log('PATENS_654_CAPS '+JSON.stringify({models,directPairs,diagnostics}));
});

