 for(const c of SAGE_SURFACE_CASES_655){for(const dims of c.sizes)for(let month=1;month<=12;month++)check(c,dims,month);for(const dims of tiny)for(const month of[6,10])check(c,dims,month);}assert.equal(models,64);assert.ok(directPairs>0);
