{"id":"p-5faf36670c76","pid":65610,"label":"coahuilensis","architecture":"smallSageMounds","sizes":[[0.3,0.35,0.18],[0.1,0.16,0.035]],"months":[5,6,7,8,9,10,11],"modes":["coahuilensis"],"leafFlag":"coahLeaf","root":0.004,"lipX":1,leaf:/^leaf-small-sage-/,petiole:/^petiole-small-sage$/},
{"id":"p-a69b7655fd1e","pid":65620,"label":"germander","architecture":"smallSageMounds","sizes":[[0.3,0.25,0.18],[0.1,0.16,0.035]],"months":[5,6,7,8,9,10,11],"modes":["germander"],"leafFlag":"germanderLeaf","root":0.004,"lipX":1.06,leaf:/^leaf-small-sage-/,petiole:/^petiole-small-sage$/}
