{"id":"p-ff64e719fa5a","pid":65810,"label":"twilight","architecture":"pratensisRosettes","sizes":[[0.4,0.35,0.18],[0.12,0.18,0.04]],"months":[5,6,7,8,9,10,11],"modes":[""],"leafFlag":"pratensisLeaf","root":0.005,"lipX":1},
{"id":"p-b70506dcea20","pid":65820,"label":"skydance","architecture":"pratensisRosettes","sizes":[[0.4,0.35,0.18],[0.12,0.18,0.04]],"months":[5,6,7,8,9,10,11],"modes":[""],"leafFlag":"pratensisLeaf","root":0.005,"lipX":1}
