test('Twilight Serenade and Sky Dance Pratensis observations reach actual visible lower-lip triangle centres at saved and known reference sizes',()=>{
 let models=0,cameraChecks=0;const saved=[];
 const check=(c,dims,month,reference=false)=>{
  const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={month,year:1,reference},s=stateAt(p,v),g=plantModel(p,v),label=c.label+' '+dims.join('/')+' month='+month+' reference='+reference;models++;
  try{if(s.groundDormant)assert.equal(g.children.length,0);else assert.equal(g.userData.architecture,c.architecture);assert.equal(g.userData.surfaceInspectionDistance,.035);assert.equal(flowerInspectionDistanceFloor(g),.035);assert.equal(g.userData.flowerTargets?.length??0,s.bloom?1:0,label);for(const m of g.children)for(const a of[m.instanceMatrix.array,m.geometry.getAttribute('position').array,m.geometry.getAttribute('normal').array])assert.ok(a.every(Number.isFinite),label+' finite organs');
   if(!s.bloom)assert.equal(flowerInspectionView(g,.8,40),null);
   if(month===6){
    const lips=g.children.filter(m=>m.userData.component==='petal-pratensis');assert.ok(lips.length>0);const anchor=g.userData.flowerTargets[0],target=new Vector3(...anchor.origin),matrix=new Matrix4(),ids=[1070,1095,1071];let best=Infinity,instance=-1,normal,fl,lip;
    for(const candidate of lips){const mode='';assert.ok(c.modes.includes(mode));assert.ok(candidate.geometry.userData.pratensisLip);const pos=candidate.geometry.getAttribute('position'),ix=candidate.geometry.getIndex();assert.equal(pos.count,1625);assert.deepEqual([0,1,2].map(j=>ix.getX(2056*3+j)),ids,'exact existing indexed triangle');for(let i=0;i<candidate.count;i++){candidate.getMatrixAt(i,matrix);const vs=ids.map(j=>new Vector3().fromBufferAttribute(pos,j).applyMatrix4(matrix)),centre=vs[0].clone().add(vs[1]).add(vs[2]).multiplyScalar(1/3),distance=centre.distanceTo(target);if(distance<best){best=distance;instance=i;lip=candidate;normal=vs[1].clone().sub(vs[0]).cross(vs[2].clone().sub(vs[0])).normalize();fl=new Vector3().setFromMatrixColumn(matrix,0).length()/c.lipX;}}}
    assert.ok(best<2e-7,label+' anchor is an actual triangle centre in its mixed-colour batch');assert.ok(normal.dot(new Vector3(...anchor.axis))>1-1e-6);assert.ok(Math.abs(anchor.radius-fl*1.30)<2e-7);const mode='',tube=g.children.find(m=>m.userData.component==='tube-pratensis'),hood=g.children.find(m=>m.userData.component==='hood-pratensis');assert.equal(tube?.count,lip.count);assert.equal(hood?.count,lip.count);
    g.position.set(-2,.012,0);g.updateMatrixWorld(true);const worldTarget=g.localToWorld(target.clone());for(const aspect of[.8,1.65]){cameraChecks++;const pose=flowerInspectionView(g,aspect,40);assert.ok(pose);assert.ok(new Vector3(...pose.target).distanceTo(worldTarget)<1e-9);const camera=new PerspectiveCamera(40,aspect,.01,650);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.ok(hit?.object===lip,label+' first visible hit is the selected lip colour batch');assert.equal(hit.instanceId,instance);assert.ok(hit.point.distanceTo(worldTarget)<2e-6);for(const organ of[tube,hood,lip]){organ.getMatrixAt(instance,matrix);matrix.premultiply(organ.matrixWorld);const pp=organ.geometry.getAttribute('position'),point=new Vector3();for(let j=0;j<pp.count;j++){point.fromBufferAttribute(pp,j).applyMatrix4(matrix).project(camera);assert.ok(Math.abs(point.x)<=.98&&Math.abs(point.y)<=.98&&point.z>=-1&&point.z<=1,label+' selected same-colour corolla fits viewport');}}}
    if(!reference)saved.push({...structuredClone(p),id:658000+saved.length});
   }assert.deepEqual(p,before);
  }finally{dispose(g);}
 };
 for(const c of SAGE_SURFACE_CASES_658){assert.deepEqual(CATALOG[c.id].appearance.flowerMonths,c.months);assert.equal(CATALOG[c.id].appearance.status,'partial');assert.equal(CATALOG[c.id].sourceChecked,'2026-10-14');for(const dims of c.sizes)for(let month=1;month<=12;month++)check(c,dims,month);}for(const c of SAGE_SURFACE_CASES_658)check(c,c.sizes[1],6,true);assert.equal(models,50);assert.equal(cameraChecks,12);
 const doc=emptyDocument(10,6);doc.plans.A.plants=saved;doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.43'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 console.log('PRATENSIS_658_OBSERVATIONS '+JSON.stringify({models,cameraChecks,knownReferenceModels:2}));
});
test('Twilight Serenade and Sky Dance basal crowns and paired stem leaves remain attached and bounded through independent legal minima',()=>{
 const tiny=[[.01,.1,.005],[.5,.1,.005],[.01,.6,.005],[.01,.1,.006]],eps=1e-7,attachEps2=(2e-7)**2;let models=0,directLeaves=0;const diagnostics=[];
 const check=(c,dims,month)=>{const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={month,year:1,reference:false},s=stateAt(p,v),g=plantModel(p,v),matrix=new Matrix4(),point=new Vector3(),segments=[],blades=[],bases=[],tips=[],label=c.label+' '+dims.join('/')+' month='+month;let top=-Infinity,ground=Infinity,radius=0,leafTop=-Infinity,petioleTop=-Infinity,vertices=0,basalLeaves=0;models++;
  try{g.updateMatrixWorld(true);const crowns=[];for(let i=0;i<4;i++){const az=i*2.399,rr=s.spread*.12*(i?1:0);for(let j=0;j<12;j++)crowns.push(new Vector3(Math.sin(az)*rr,.005+j*.0006,Math.cos(az)*rr).applyMatrix4(g.matrixWorld));}for(const mesh of g.children){const pos=mesh.geometry.getAttribute('position'),tag=mesh.userData.component,leaf=tag.startsWith('leaf-pratensis-'),petiole=tag==='petiole-pratensis',shoot=/^(stem|branch|axis)-pratensis$/.test(tag);assert.ok(pos.array.every(Number.isFinite)&&mesh.geometry.getAttribute('normal').array.every(Number.isFinite));if(leaf){assert.ok(mesh.geometry.userData.pratensisLeaf);if(tag==='leaf-pratensis-basal')basalLeaves+=mesh.count;}assert.ok(mesh.instanceMatrix.array.every(Number.isFinite));if(mesh.instanceColor)assert.ok(mesh.instanceColor.array.every(Number.isFinite));
   for(let i=0;i<mesh.count;i++){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);if(shoot)segments.push(new Line3(new Vector3(0,-.5,0).applyMatrix4(matrix),new Vector3(0,.5,0).applyMatrix4(matrix)));if(leaf)blades.push(new Vector3().applyMatrix4(matrix));if(petiole){bases.push(new Vector3(0,-.5,0).applyMatrix4(matrix));tips.push(new Vector3(0,.5,0).applyMatrix4(matrix));}for(let j=0;j<pos.count;j++){point.fromBufferAttribute(pos,j).applyMatrix4(matrix);vertices++;assert.ok(point.toArray().every(Number.isFinite));assert.ok(point.y>=-eps&&point.y<=s.height+eps,label+' ground/height '+tag);assert.ok(Math.hypot(point.x,point.z)*2<=s.spread+eps,label+' width '+tag);if(leaf||petiole)assert.ok(point.y<=Math.min(s.height,s.leafHeight)+eps,label+' foliage ceiling '+tag);top=Math.max(top,point.y);ground=Math.min(ground,point.y);radius=Math.max(radius,Math.hypot(point.x,point.z));if(leaf)leafTop=Math.max(leafTop,point.y);if(petiole)petioleTop=Math.max(petioleTop,point.y);}}
  }assert.ok(vertices>0&&segments.length>0);if(s.leafHeight<=c.root)assert.equal(basalLeaves,0,'zero-clearance basal foliage omitted; lower actual stem attachments may still fit');else assert.ok(basalLeaves>0,'basal foliage retained');const matches=(p,list)=>list.some(q=>p.distanceToSquared(q)<=attachEps2),onStem=p=>segments.some(line=>line.closestPointToPoint(p,true,new Vector3()).distanceToSquared(p)<=attachEps2),attached=p=>onStem(p)||matches(p,crowns);for(const p of blades)assert.ok(matches(p,tips)||attached(p),label+' blade attaches to a petiole, real stem or original basal crown');for(const p of bases)assert.ok(attached(p),label+' petiole anchored');for(const p of tips)assert.ok(matches(p,blades),label+' petiole supports a blade');directLeaves+=blades.filter(p=>!matches(p,tips)).length;if(month===6&&c.sizes.includes(dims))diagnostics.push({id:c.id,dims,actualHeight:top,actualSpread:radius*2,actualLeafHeight:leafTop,actualPetioleHeight:petioleTop,ground,vertices});assert.deepEqual(p,before);
  }finally{dispose(g);}
 };
 for(const c of SAGE_SURFACE_CASES_658){for(const dims of c.sizes)for(let month=1;month<=12;month++)check(c,dims,month);for(const dims of tiny)for(const month of[6,10])check(c,dims,month);}assert.equal(models,64);assert.ok(directLeaves>0);const doc=emptyDocument(24,6);doc.plans.A.plants=SAGE_SURFACE_CASES_658.flatMap(c=>[...c.sizes,...tiny].map(dims=>({id:c.id,dims}))).map(({id,dims},i)=>({...makePlant(id,658100+i,1+i*1.8,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.43'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);console.log('PRATENSIS_658_CAPS '+JSON.stringify({models,directLeaves,diagnostics}));
});

