    for(const candidate of lips){const mode=candidate.userData.component.slice('lip-'.length);assert.ok(c.modes.includes(mode));assert.ok(candidate.geometry.userData.nemorosaLip);const pos=candidate.geometry.getAttribute('position'),ix=candidate.geometry.getIndex();assert.equal(pos.count,1029);assert.deepEqual([0,1,2].map(j=>ix.getX(1306*3+j)),ids,'exact existing indexed triangle');for(let i=0;i<candidate.count;i++){candidate.getMatrixAt(i,matrix);const vs=ids.map(j=>new Vector3().fromBufferAttribute(pos,j).applyMatrix4(matrix)),centre=vs[0].clone().add(vs[1]).add(vs[2]).multiplyScalar(1/3),distance=centre.distanceTo(target);if(distance<best){best=distance;instance=i;lip=candidate;normal=vs[1].clone().sub(vs[0]).cross(vs[2].clone().sub(vs[0])).normalize();fl=new Vector3().setFromMatrixColumn(matrix,0).length()/c.lipX;}}}
    assert.ok(best<2e-7,label+' anchor is an actual triangle centre in its mixed-colour batch');assert.ok(normal.dot(new Vector3(...anchor.axis))>1-1e-6);assert.ok(Math.abs(anchor.radius-fl*1.30)<2e-7);const mode=lip.userData.component.slice('lip-'.length),tube=g.children.find(m=>m.userData.component==='tube-perovskia'),hood=g.children.find(m=>m.userData.component==='hood-perovskia');assert.equal(tube?.count,lip.count);assert.equal(hood?.count,lip.count);
    g.position.set(-2,.012,0);g.updateMatrixWorld(true);const worldTarget=g.localToWorld(target.clone());for(const aspect of[.8,1.65]){cameraChecks++;const pose=flowerInspectionView(g,aspect,40);assert.ok(pose);assert.ok(new Vector3(...pose.target).distanceTo(worldTarget)<1e-9);const camera=new PerspectiveCamera(40,aspect,.01,650);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.ok(hit?.object===lip,label+' first visible hit is the selected lip colour batch');assert.equal(hit.instanceId,instance);assert.ok(hit.point.distanceTo(worldTarget)<2e-6);for(const organ of[tube,hood,lip]){organ.getMatrixAt(instance,matrix);matrix.premultiply(organ.matrixWorld);const pp=organ.geometry.getAttribute('position'),point=new Vector3();for(let j=0;j<pp.count;j++){point.fromBufferAttribute(pp,j).applyMatrix4(matrix).project(camera);assert.ok(Math.abs(point.x)<=.98&&Math.abs(point.y)<=.98&&point.z>=-1&&point.z<=1,label+' selected same-colour corolla fits viewport');}}}
