    for(let j=0;j<pos.count;j++){point.fromBufferAttribute(pos,j).applyMatrix4(matrix);vertices++;assert.ok(point.toArray().every(Number.isFinite));assert.ok(point.y>=-eps&&point.y<=s.height+eps,label+' ground/height '+tag);assert.ok(Math.hypot(point.x,point.z)*2<=s.spread+eps,label+' spread '+tag);if(leaf)assert.ok(point.y<=Math.min(s.height,s.leafHeight)+eps,label+' leaf ceiling');top=Math.max(top,point.y);ground=Math.min(ground,point.y);radius=Math.max(radius,Math.hypot(point.x,point.z));if(leaf)leafTop=Math.max(leafTop,point.y);}
