 const check=(c,dims,month)=>{
  const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={month,year:1,reference:false},s=stateAt(p,v),g=plantModel(p,v),matrix=new Matrix4(),point=new Vector3(),segments=[],blades=[],label=c.label+' '+dims.join('/')+' month='+month;let leaves=0,top=-Infinity,ground=Infinity,radius=0,leafTop=-Infinity,vertices=0;models++;
  try{if(s.groundDormant){assert.equal(g.children.length,0);assert.deepEqual(p,before);return;}assert.equal(g.userData.architecture,c.architecture);g.updateMatrixWorld(true);g.traverse(mesh=>{
   if(!mesh.isMesh)return;const pos=mesh.geometry.getAttribute('position'),normal=mesh.geometry.getAttribute('normal'),tag=mesh.userData.component,leaf=c.leaf.test(tag),shoot=/^(wood|stem|branch|axis)-leucantha$/.test(tag),count=mesh.isInstancedMesh?mesh.count:1;assert.ok(pos&&normal&&normal.array.every(Number.isFinite));if(mesh.isInstancedMesh)assert.ok(mesh.instanceMatrix.array.every(Number.isFinite));if(mesh.instanceColor)assert.ok(mesh.instanceColor.array.every(Number.isFinite));if(leaf){leaves+=count;assert.ok(mesh.geometry.userData[c.leafFlag]);assert.equal(pos.count,833);}
   for(let i=0;i<count;i++){if(mesh.isInstancedMesh){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);}else matrix.copy(mesh.matrixWorld);if(shoot)segments.push(new Line3(new Vector3(0,-.5,0).applyMatrix4(matrix),new Vector3(0,.5,0).applyMatrix4(matrix)));if(leaf)blades.push(new Vector3().applyMatrix4(matrix));
    for(let j=0;j<pos.count;j++){point.fromBufferAttribute(pos,j).applyMatrix4(matrix);vertices++;assert.ok(point.toArray().every(Number.isFinite));assert.ok(point.y>=-eps&&point.y<=s.height+eps,label+' ground/height '+tag);assert.ok(Math.hypot(point.x,point.z)*2<=s.spread+eps,label+' spread '+tag);if(leaf)assert.ok(point.y<=Math.min(s.height,s.leafHeight)+eps,label+' leaf ceiling');top=Math.max(top,point.y);ground=Math.min(ground,point.y);radius=Math.max(radius,Math.hypot(point.x,point.z));if(leaf)leafTop=Math.max(leafTop,point.y);}
   }
  });assert.ok(vertices>0&&segments.length>0);if(s.leafDensity===0||s.leafHeight<=c.root)assert.equal(leaves,0,label+' preserve winter absence');else assert.ok(leaves>0,label+' retain paired foliage');assert.equal(leaves%2,0);for(let i=0;i<blades.length;i+=2){assert.ok(blades[i].distanceToSquared(blades[i+1])<=attachEps2,label+' complete opposed pair at same node');assert.ok(segments.some(line=>line.closestPointToPoint(blades[i],true,new Vector3()).distanceToSquared(blades[i])<=attachEps2),label+' attached to actual wood/shoot');pairedLeaves+=2;}if(month===10&&c.sizes.includes(dims))diagnostics.push({id:c.id,dims,actualHeight:top,actualSpread:radius*2,actualLeafHeight:leafTop,ground,vertices});assert.deepEqual(p,before);
  }finally{dispose(g);}
 };
 for(const c of SAGE_SURFACE_CASES_667){for(const dims of c.sizes)for(let month=1;month<=12;month++)check(c,dims,month);for(const dims of tiny)for(const month of[9,10])check(c,dims,month);}assert.equal(models,96);assert.ok(pairedLeaves>0);
