test('Green and Golden pineapple sages independent dimensions bound attached foliage on real wood stems and branches through legal minima',()=>{
 const tiny=[[.01,.1,.005],[.5,.1,.005],[.01,.6,.005],[.01,.1,.006]],eps=1e-7,attachEps2=(2e-7)**2;let models=0,directPairs=0;const diagnostics=[];
 const check=(c,dims,month)=>{
  const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={month,year:1,reference:false},s=stateAt(p,v),g=plantModel(p,v),matrix=new Matrix4(),point=new Vector3(),segments=[],blades=[],petioleBases=[],petioleTips=[],label=c.label+' '+dims.join('/')+' month='+month;let leaves=0,petioles=0,top=-Infinity,ground=Infinity,radius=0,leafTop=-Infinity,petioleTop=-Infinity,vertices=0;models++;
  try{if(s.groundDormant){assert.equal(g.children.length,0);assert.deepEqual(p,before);return;}g.updateMatrixWorld(true);g.traverse(mesh=>{
   if(!mesh.isMesh)return;const pos=mesh.geometry.getAttribute('position'),normal=mesh.geometry.getAttribute('normal'),tag=mesh.userData.component,leaf=c.leaf.test(tag),petiole=c.petiole.test(tag),shoot=/^(stem|branch|axis)-pineapple$/.test(tag),count=mesh.isInstancedMesh?mesh.count:1;assert.ok(pos&&normal&&normal.array.every(Number.isFinite),label+' finite normals');assert.ok(!tag.includes('-winter'),'no new basal winter organs');if(mesh.isInstancedMesh)assert.ok(mesh.instanceMatrix.array.every(Number.isFinite));if(mesh.instanceColor)assert.ok(mesh.instanceColor.array.every(Number.isFinite));if(leaf){leaves+=count;assert.ok(mesh.geometry.userData[c.leafFlag]);}if(petiole)petioles+=count;
   for(let i=0;i<count;i++){if(mesh.isInstancedMesh){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);}else matrix.copy(mesh.matrixWorld);if(shoot)segments.push(new Line3(new Vector3(0,-.5,0).applyMatrix4(matrix),new Vector3(0,.5,0).applyMatrix4(matrix)));if(leaf)blades.push(new Vector3().applyMatrix4(matrix));if(petiole){petioleBases.push(new Vector3(0,-.5,0).applyMatrix4(matrix));petioleTips.push(new Vector3(0,.5,0).applyMatrix4(matrix));}
    for(let j=0;j<pos.count;j++){point.fromBufferAttribute(pos,j).applyMatrix4(matrix);vertices++;assert.ok(point.toArray().every(Number.isFinite));assert.ok(point.y>=-eps&&point.y<=s.height+eps,label+' ground/height '+tag);assert.ok(Math.hypot(point.x,point.z)*2<=s.spread+eps,label+' spread '+tag);if(leaf||petiole)assert.ok(point.y<=Math.min(s.height,s.leafHeight)+eps,label+' leaf ceiling '+tag);top=Math.max(top,point.y);ground=Math.min(ground,point.y);radius=Math.max(radius,Math.hypot(point.x,point.z));if(leaf)leafTop=Math.max(leafTop,point.y);if(petiole)petioleTop=Math.max(petioleTop,point.y);}
   }
  });assert.ok(vertices>0&&segments.length>0);if(s.leafDensity===0||s.leafHeight<=c.root)assert.equal(leaves,0,label+' omit zero-clearance leaves');else assert.ok(leaves>0,label+' retain paired foliage');assert.equal(leaves%2,0);assert.equal(petioles%2,0);assert.ok(petioles<=leaves);const matched=(p,ends)=>ends.some(end=>p.distanceToSquared(end)<=attachEps2),onShoot=p=>segments.some(line=>line.closestPointToPoint(p,true,new Vector3()).distanceToSquared(p)<=attachEps2),direct=blades.filter(p=>!matched(p,petioleTips));for(const p of blades)assert.ok(matched(p,petioleTips)||onShoot(p),label+' blade attached');for(const p of petioleBases)assert.ok(onShoot(p),label+' petiole starts on actual wood/shoot');for(const p of petioleTips)assert.ok(matched(p,blades),label+' petiole supports blade');assert.equal(direct.length,leaves-petioles);assert.equal(direct.length%2,0);for(const p of direct){assert.ok(onShoot(p));const n=direct.filter(q=>p.distanceToSquared(q)<=attachEps2).length;assert.ok(n>=2&&n%2===0,label+' complete direct pair');}directPairs+=direct.length/2;if(month===10&&c.sizes.includes(dims))diagnostics.push({id:c.id,dims,actualHeight:top,actualSpread:radius*2,actualLeafHeight:leafTop,actualPetioleHeight:petioleTop,ground,vertices});assert.deepEqual(p,before);
  }finally{dispose(g);}
 };
 for(const c of SAGE_SURFACE_CASES_668){for(const dims of c.sizes)for(let month=1;month<=12;month++)check(c,dims,month);for(const dims of tiny)for(const month of[8,10])check(c,dims,month);}assert.equal(models,64);assert.ok(directPairs>0);
 const doc=emptyDocument(24,6);doc.plans.A.plants=SAGE_SURFACE_CASES_668.flatMap(c=>[...c.sizes,...tiny].map(dims=>({id:c.id,dims}))).map(({id,dims},i)=>({...makePlant(id,668100+i,1+i*1.8,3),height:dims[0],spread:dims[1],leafHeight:dims[2]}));doc.view.month=10;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.53'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 console.log('PINEAPPLE_668_CAPS '+JSON.stringify({models,directPairs,diagnostics}));
});

