{"id":"p-ba2e1986e528","pid":66910,"label":"cleveland","architecture":"clevelandWhorls","sizes":[[0.7,0.4,0.28],[0.14,0.2,0.05]],"months":[5,6,7,8,9,10,11],"modes":["cleveland"],"leafFlag":"clevelandLeaf","root":0.006,"lipX":1,leaf:/^leaf-cleveland$/,petiole:/^petiole-cleveland$/}
