const SAGE_SURFACE_CASES_678=[{"id":"salvia","pid":67810,"label":"nemorosa","architecture":"nemorosaWhorls","sizes":[[0.65,0.4,0.3],[0.14,0.22,0.05]],"months":[6,7,8,9],"modes":["nemorosa-lower"],"leafFlag":"nemorosaLeaf",leaf:/^leaf-nemorosa(?:-basal)?$/,petiole:/^petiole-nemorosa$/,"root":0.006}];
test('Standard species nemorosa observations reach actual visible lower-lip triangle centres at saved and known reference sizes',()=>{
 let models=0,cameraChecks=0;const saved=[];
 const check=(c,dims,month,reference=false)=>{
  const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},before=structuredClone(p),v={month,year:1,reference},s=stateAt(p,v),g=plantModel(p,v),label=c.label+' '+dims.join('/')+' month='+month+' reference='+reference;models++;
  try{if(s.groundDormant)assert.equal(g.children.length,0);else assert.equal(g.userData.architecture,c.architecture);assert.equal(g.userData.surfaceInspectionDistance,.035);assert.equal(flowerInspectionDistanceFloor(g),.035);assert.equal(g.userData.flowerTargets?.length??0,s.bloom?1:0,label);for(const m of g.children)for(const a of[m.instanceMatrix.array,m.geometry.getAttribute('position').array,m.geometry.getAttribute('normal').array])assert.ok(a.every(Number.isFinite),label+' finite organs');
   if(!s.bloom)assert.equal(flowerInspectionView(g,.8,40),null);
   if(month===6){
    const lips=g.children.filter(m=>m.userData.component.startsWith('petal-nemorosa-lower'));assert.ok(lips.length>0);const anchor=g.userData.flowerTargets[0],target=new Vector3(...anchor.origin),matrix=new Matrix4(),ids=[686,707,687];let best=Infinity,instance=-1,normal,fl,lip;
    for(const candidate of lips){const mode=candidate.userData.component.slice('petal-'.length);assert.ok(c.modes.includes(mode));assert.ok(candidate.geometry.userData.nemorosaLip);const pos=candidate.geometry.getAttribute('position'),ix=candidate.geometry.getIndex();assert.equal(pos.count,1029);assert.deepEqual([0,1,2].map(j=>ix.getX(1308*3+j)),ids,'exact existing indexed triangle');for(let i=0;i<candidate.count;i++){candidate.getMatrixAt(i,matrix);const vs=ids.map(j=>new Vector3().fromBufferAttribute(pos,j).applyMatrix4(matrix)),centre=vs[0].clone().add(vs[1]).add(vs[2]).multiplyScalar(1/3),distance=centre.distanceTo(target);if(distance<best){best=distance;instance=i;lip=candidate;normal=vs[1].clone().sub(vs[0]).cross(vs[2].clone().sub(vs[0])).normalize();fl=new Vector3().setFromMatrixColumn(matrix,1).length()/.38;}}}
    assert.ok(best<2e-7,label+' anchor is an actual triangle centre in its mixed-colour batch');assert.ok(normal.dot(new Vector3(...anchor.axis))>1-1e-6);assert.ok(Math.abs(anchor.radius-fl*1.30)<2e-7);const mode=lip.userData.component.slice('petal-'.length),tube=g.children.find(m=>m.userData.component==='tube-nemorosa'),hood=g.children.find(m=>m.userData.component==='petal-nemorosa-upper');assert.equal(tube?.count,lip.count);assert.equal(hood?.count,lip.count);
    g.position.set(-2,.012,0);g.updateMatrixWorld(true);const worldTarget=g.localToWorld(target.clone());for(const aspect of[.8,1.65]){cameraChecks++;const pose=flowerInspectionView(g,aspect,40);assert.ok(pose);assert.ok(new Vector3(...pose.target).distanceTo(worldTarget)<1e-9);const camera=new PerspectiveCamera(40,aspect,.01,650);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.ok(hit?.object===lip,label+' first visible hit is the selected lip colour batch');assert.equal(hit.instanceId,instance);assert.ok(hit.point.distanceTo(worldTarget)<2e-6);for(const organ of[tube,hood,lip]){organ.getMatrixAt(instance,matrix);matrix.premultiply(organ.matrixWorld);const pp=organ.geometry.getAttribute('position'),point=new Vector3();for(let j=0;j<pp.count;j++){point.fromBufferAttribute(pp,j).applyMatrix4(matrix).project(camera);assert.ok(Math.abs(point.x)<=.98&&Math.abs(point.y)<=.98&&point.z>=-1&&point.z<=1,label+' selected same-colour corolla fits viewport');}}}
    if(!reference)saved.push({...structuredClone(p),id:678000+saved.length});
   }assert.deepEqual(p,before);
  }finally{dispose(g);}
 };
 for(const c of SAGE_SURFACE_CASES_678){assert.deepEqual(CATALOG[c.id].appearance.flowerMonths,c.months);assert.equal(CATALOG[c.id].appearance.status,'partial');assert.equal(CATALOG[c.id].sourceChecked,'2026-10-09');for(const dims of c.sizes)for(let month=1;month<=12;month++)check(c,dims,month);}for(const c of SAGE_SURFACE_CASES_678)check(c,c.sizes[1],6,true);assert.equal(models,25);assert.equal(cameraChecks,6);
 const doc=emptyDocument(10,6);doc.plans.A.plants=saved;doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.63'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 console.log('NEMOROSA_SPECIES_678_OBSERVATIONS '+JSON.stringify({models,cameraChecks,knownReferenceModels:1}));
});
