test('Santolina crowded yellow button heads cover their central surface at normal and small sizes',()=>{
 const results=[];for(const dims of[[.5,.5,.3],[.14,.24,.06]]){const p={...makePlant('p-bc238e853e2c',68130,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},old=structuredClone(p),g=plantModel(p,{month:6,year:1,reference:false}),petal=g.children.find(m=>m.userData.component==='petal-aromatic-santolina'),involucre=g.children.find(m=>m.userData.component==='involucre-aromatic-santolina'),count=petal.count/involucre.count,matrix=new Matrix4(),position=new Vector3(),q=new Quaternion(),scale=new Vector3();let isolated;
 try{involucre.getMatrixAt(0,matrix);matrix.decompose(position,q,scale);const R=scale.x,up=new Vector3(0,1,0).applyQuaternion(q),tip=position.addScaledVector(up,R*.12),frame=new Matrix4().compose(tip,q,new Vector3(R,R,R)).invert();isolated=new InstancedMesh(petal.geometry,petal.material,count);for(let i=0;i<count;i++){petal.getMatrixAt(i,matrix);matrix.premultiply(frame);isolated.setMatrixAt(i,matrix);}isolated.updateMatrixWorld(true);isolated.computeBoundingSphere();const ray=new Raycaster(),down=new Vector3(0,-1,0);let samples=0,yellow=0;for(let x=-8;x<=8;x++)for(let z=-8;z<=8;z++){if(x*x+z*z>64)continue;samples++;ray.set(new Vector3(x/10,2,z/10),down);if(ray.intersectObject(isolated,false).length)yellow++;}assert.equal(samples,197);assert.ok(yellow/samples>.90,'central head reads as dense yellow florets rather than open green receptacle');assert.deepEqual(p,old);results.push({dims,samples,yellowCorollaHits:yellow,coverage:yellow/samples});}finally{isolated?.dispose();dispose(g);}}
 console.log('SANTOLINA_682_HEAD_COVERAGE '+JSON.stringify(results));
});

