test('Kirigami ornamental oregano leaves and veins respect independent tiny foliage caps while original stems and bracts retain their heights',()=>{
 const c=KIRIGAMI_685,tiny=[[.01,.1,.005],[.5,.1,.005],[.01,.6,.005],[.5,.1,.006]],eps=1e-7,attachEps2=(2e-7)**2;let models=0;const diagnostics=[];
 for(const[dims,month]of[...c.sizes.flatMap(d=>Array.from({length:12},(_,i)=>[d,i+1])),...tiny.flatMap(d=>[6,1].map(m=>[d,m]))]){models++;const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},old=structuredClone(p),s=stateAt(p,{month,year:1,reference:false}),g=plantModel(p,{month,year:1,reference:false}),matrix=new Matrix4(),point=new Vector3(),segments=[],petioleRoots=[],petioleTips=[],leafRoots=[];let leaves=0,vertices=0,top=-Infinity,leafTop=-Infinity,radial=0;try{g.updateMatrixWorld(true);for(const mesh of g.children){const leaf=mesh.userData.component==='leaf-oregano-kirigami',foliage=leaf||/^(midrib|side-vein|petiole)-oregano$/.test(mesh.userData.component),petiole=mesh.userData.component==='petiole-oregano',stem=/^(stem-oregano-kirigami|winter-crown-oregano)$/.test(mesh.userData.component),pos=mesh.geometry.attributes.position;assert.ok(mesh.instanceMatrix.array.every(Number.isFinite)&&mesh.geometry.attributes.normal.array.every(Number.isFinite));if(leaf){leaves+=mesh.count;assert.equal(pos.count,1421);}for(let i=0;i<mesh.count;i++){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);if(stem)segments.push(new Line3(new Vector3(0,-.5,0).applyMatrix4(matrix),new Vector3(0,.5,0).applyMatrix4(matrix)));if(petiole){petioleRoots.push(new Vector3(0,-.5,0).applyMatrix4(matrix));petioleTips.push(new Vector3(0,.5,0).applyMatrix4(matrix));}if(leaf)leafRoots.push(new Vector3().applyMatrix4(matrix));for(let j=0;j<pos.count;j++){point.fromBufferAttribute(pos,j).applyMatrix4(matrix);vertices++;assert.ok(point.toArray().every(Number.isFinite));assert.ok(point.y>=-eps,'above soil '+JSON.stringify({dims,month,component:mesh.userData.component,y:point.y}));assert.ok(point.y<=s.height+eps,'height cap');assert.ok(Math.hypot(point.x,point.z)*2<=s.spread+eps,'spread cap');if(foliage)assert.ok(point.y<=Math.min(s.height,s.leafHeight)+eps,'leaves and vein/petiole geometry below foliage ceiling');top=Math.max(top,point.y);radial=Math.max(radial,Math.hypot(point.x,point.z));if(foliage)leafTop=Math.max(leafTop,point.y);}}}assert.ok(leaves>0&&vertices>0);const direct=leafRoots.filter(pt=>!petioleTips.some(v=>v.distanceToSquared(pt)<=attachEps2));assert.equal(leaves,petioleTips.length+direct.length);assert.equal(direct.length%2,0);for(const pt of direct){assert.ok(segments.some(l=>l.closestPointToPoint(pt,true,new Vector3()).distanceToSquared(pt)<=attachEps2),'tiny leaf directly on actual stem');const peers=direct.filter(v=>v.distanceToSquared(pt)<=attachEps2).length;assert.ok(peers>=2&&peers%2===0,'complete direct opposite pair');}for(const pt of petioleRoots)assert.ok(segments.some(l=>l.closestPointToPoint(pt,true,new Vector3()).distanceToSquared(pt)<=attachEps2),'petiole on actual stem or original winter crown');if(month===6&&c.sizes.includes(dims))diagnostics.push({dims,actualHeight:top,actualSpread:radial*2,actualFoliageTop:leafTop,leaves});assert.deepEqual(p,old);}finally{dispose(g);}}
 assert.equal(models,44);const doc=emptyDocument(14,6);doc.plans.A.plants=[...c.sizes,...tiny].map((d,i)=>({...makePlant(c.id,685100+i,1+i*1.5,3),height:d[0],spread:d[1],leafHeight:d[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-24.70'},old=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,old);console.log('KIRIGAMI_685_CAPS '+JSON.stringify({models,diagnostics}));
});

