test('Hidcote has attached thirteen-rib calyces and a continuous two-upper three-lower corolla with included stamens and unobstructed actual-lip inspection',()=>{
 const c=HIDCOTE_692,cases=[...c.sizes.map(dims=>({dims,reference:false})),{dims:c.sizes[1],reference:true},{dims:[.01,.1,.005],reference:false}],ids=[2399,2480,2400],face=4740;let models=0,cameraChecks=0,organVerticesInFrame=0;const saved=[];
 for(const {dims,reference}of cases){models++;const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},old=structuredClone(p),g=plantModel(p,{month:6,year:1,reference});
  try{assert.equal(g.userData.surfaceInspectionDistance,.012);assert.equal(flowerInspectionDistanceFloor(g),.012);assert.equal(g.userData.flowerTargets.length,1);
   const corolla=g.children.find(m=>m.userData.component==='corolla-lavender-hidcote'),calyx=g.children.find(m=>m.userData.component==='calyx-lavender'),hairs=g.children.find(m=>m.userData.component==='calyx-hair-lavender'),anther=g.children.find(m=>m.userData.component==='anther-lavender'),filament=g.children.find(m=>m.userData.component==='filament-lavender'),style=g.children.find(m=>m.userData.component==='style-lavender'),stigma=g.children.find(m=>m.userData.component==='stigma-lavender'),pos=corolla.geometry.attributes.position,index=corolla.geometry.index;
   assert.deepEqual(corolla.geometry.userData.hidcoteFloral,{upper:2,lower:3,continuousTube:true,rows:32,columns:80});assert.equal(pos.count,2673);assert.deepEqual(calyx.geometry.userData.hidcoteFloral,{veins:13,upperToothEnlarged:true,rows:20,columns:80});assert.equal(hairs.count,calyx.count*6);assert.equal(anther.count,corolla.count*4);assert.equal(filament.count,corolla.count*4);assert.equal(style.count,corolla.count);assert.equal(stigma.count,corolla.count*2);assert.deepEqual([0,1,2].map(i=>index.getX(face*3+i)),ids);
   const centre=new Vector3(...g.userData.flowerTargets[0].origin),matrix=new Matrix4();let distance=Infinity,instance=-1,normal,F,corollaMatrix;
   for(let i=0;i<corolla.count;i++){corolla.getMatrixAt(i,matrix);const vs=ids.map(j=>new Vector3().fromBufferAttribute(pos,j).applyMatrix4(matrix)),at=vs[0].clone().add(vs[1]).add(vs[2]).multiplyScalar(1/3),d=at.distanceTo(centre);if(d<distance){distance=d;instance=i;normal=vs[1].clone().sub(vs[0]).cross(vs[2].clone().sub(vs[0])).normalize();F=new Vector3().setFromMatrixColumn(matrix,1).length();corollaMatrix=matrix.clone();}}
   assert.ok(distance<2e-7);if(normal.y<0)normal.negate();assert.ok(normal.dot(new Vector3(...g.userData.flowerTargets[0].axis))>1-1e-6);assert.ok(Math.abs(g.userData.flowerTargets[0].radius-F*1.5)<2e-7);
   let matchingCalyx=-1;for(let i=0;i<calyx.count;i++){calyx.getMatrixAt(i,matrix);if(matrix.elements.every((v,j)=>Math.abs(v-corollaMatrix.elements[j])<2e-8)){matchingCalyx=i;break;}}assert.ok(matchingCalyx>=0,'calyx and corolla have exactly the same attached axis and base');
   const inverse=corollaMatrix.clone().invert();for(const mesh of[anther,filament])for(let k=0;k<4;k++){mesh.getMatrixAt(instance*4+k,matrix);matrix.premultiply(inverse);const pp=mesh.geometry.attributes.position,pt=new Vector3();for(let j=0;j<pp.count;j++){pt.fromBufferAttribute(pp,j).applyMatrix4(matrix);assert.ok(pt.y<.72+1e-6&&pt.y>.20&&Math.hypot(pt.x,pt.z)<.16,'four stamens remain inside the tube');}}
   const ends=[];for(let k=0;k<4;k++){anther.getMatrixAt(instance*4+k,matrix);ends.push(new Vector3().setFromMatrixPosition(matrix).applyMatrix4(inverse).y);}assert.ok(ends[0]>ends[2]&&ends[1]>ends[3],'anterior pair longer');
   g.position.set(-2,.012,0);g.updateMatrixWorld(true);const world=g.localToWorld(centre.clone());for(const aspect of(dims[0]===.01?[]:[.8,1.65])){cameraChecks++;const pose=flowerInspectionView(g,aspect,40),camera=new PerspectiveCamera(40,aspect,.01,650);assert.ok(new Vector3(...pose.target).distanceTo(world)<1e-9);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.equal(hit?.object,corolla,'actual flower lip is first visible at centre '+JSON.stringify({dims,reference,aspect,hit:hit?.object.userData.component}));assert.equal(hit.instanceId,instance);assert.equal(hit.faceIndex,face);assert.ok(hit.point.distanceTo(world)<2e-6);
    for(const[mesh,instances]of[[corolla,[instance]],[calyx,[matchingCalyx]],[anther,[0,1,2,3].map(k=>4*instance+k)],[filament,[0,1,2,3].map(k=>4*instance+k)],[style,[instance]],[stigma,[2*instance,2*instance+1]]])for(const i of instances){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);const pp=mesh.geometry.attributes.position,pt=new Vector3();for(let j=0;j<pp.count;j++){pt.fromBufferAttribute(pp,j).applyMatrix4(matrix).project(camera);assert.ok(Math.abs(pt.x)<=.98&&Math.abs(pt.y)<=.98&&pt.z>=-1&&pt.z<=1,'complete flower and included organs fit '+JSON.stringify({dims,reference,aspect,organ:mesh.userData.component,point:pt.toArray()}));organVerticesInFrame++;}}
   }assert.deepEqual(p,old);if(!reference)saved.push({...p,id:693000+saved.length});
  }finally{dispose(g);}
 }
 const winter=plantModel({...makePlant(c.id,c.pid,3,3),height:.08,spread:.18,leafHeight:.04},{month:1,year:1,reference:false});models++;try{assert.equal(winter.userData.flowerTargets?.length||0,0);assert.equal(flowerInspectionView(winter,.8,40),null);assert.ok(winter.children.some(m=>m.userData.component==='calyx-lavender'));assert.ok(!winter.children.some(m=>/^(corolla|anther|filament|style|stigma)-lavender/.test(m.userData.component)));}finally{dispose(winter);}
 const doc=emptyDocument(14,6);doc.plans.A.plants=saved;doc.view.month=6;doc.view.year=1;const oldSave={...structuredClone(doc),catalogVersion:'2026-10-24.78'};assert.deepEqual(validateDocument(oldSave),doc);assert.equal(models,6);assert.equal(cameraChecks,8);console.log('HIDCOTE_693_FLORAL '+JSON.stringify({models,cameraChecks,organVerticesInFrame,triangle:ids,face,kind:'actual upper lip'}));
});


