import {saxifrageLeafPoint as dumboLeafPoint} from '../site/plant-detail.js';

const DUMBO_707={id:'p-5710cb13f030',pid:70710,sizes:[[.5,.7,.45],[.08,.18,.04],[.5,.7,.005]]};
test('Dumbo rounded hairy leaves and petioles stay connected to rhizomes inside independent saved dimensions',()=>{
 const c=DUMBO_707,tiny=[[.01,.1,.005],[.5,.1,.005],[.01,.6,.005],[.5,.1,.006]],cases=[...c.sizes.flatMap(dims=>Array.from({length:12},(_,i)=>({dims,month:i+1,reference:false}))),...tiny.flatMap(dims=>[1,4].map(month=>({dims,month,reference:false}))),{dims:c.sizes[1],month:4,reference:true}],eps=1e-7;let models=0,actualVertices=0,attachedLeaves=0,attachedPetioles=0;const diagnostics=[];
 assert.deepEqual(CATALOG[c.id].height,[.4,.6]);assert.deepEqual(CATALOG[c.id].spread,[.6,.8]);assert.equal(CATALOG[c.id].latin,'Bergenia ciliata Dumbo');assert.deepEqual(CATALOG[c.id].bloom,[2,3,4,5]);assert.equal(CATALOG[c.id].sourceChecked,'2026-10-25');assert.ok(appearanceSummary(CATALOG[c.id]).includes('細かい毛'));
 for(const {dims,month,reference}of cases){models++;const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},original=structuredClone(p),s=stateAt(p,{month,year:1,reference}),g=plantModel(p,{month,year:1,reference}),matrix=new Matrix4();let minY=Infinity,maxY=-Infinity,radial=0,leafTop=-Infinity;const roots=[],petioles=[],rhizomes=[],leafMatrices=[],hairBases=[];
  try{g.updateMatrixWorld(true);assert.equal(g.userData.architecture,'bergeniaRhizomes');const count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);assert.ok(count('scape-bergenia')>0&&count('panicle-bergenia')>0&&count('pedicel-bergenia')>0);assert.equal(count('petal-bergenia')>0,[2,3,4,5].includes(month));assert.ok(!g.children.some(m=>/^(fruit|seed|capsule)-/.test(m.userData.component)));
   for(const mesh of g.children){const component=mesh.userData.component,leaf=component==='leaf-bergenia-hairy',petiole=component==='petiole-bergenia',rhizome=component==='rhizome-bergenia',pos=mesh.geometry.attributes.position.array;assert.ok(pos.every(Number.isFinite)&&mesh.geometry.attributes.normal.array.every(Number.isFinite)&&mesh.instanceMatrix.array.every(Number.isFinite));
    for(let i=0;i<mesh.count;i++){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);const m=matrix.elements;
     if(leaf){roots.push([m[12],m[13],m[14]]);leafMatrices.push(matrix.clone());}if(component==='hair-bergenia')hairBases.push([m[12]-m[4]*.5,m[13]-m[5]*.5,m[14]-m[6]*.5]);
     if(petiole||rhizome){const ends=[-0.5,0.5].map(t=>[m[12]+m[4]*t,m[13]+m[5]*t,m[14]+m[6]*t]),radius=Math.hypot(m[0],m[1],m[2]);(petiole?petioles:rhizomes).push({ends,radius});}
     for(let j=0;j<pos.length;j+=3){const x=m[0]*pos[j]+m[4]*pos[j+1]+m[8]*pos[j+2]+m[12],y=m[1]*pos[j]+m[5]*pos[j+1]+m[9]*pos[j+2]+m[13],z=m[2]*pos[j]+m[6]*pos[j+1]+m[10]*pos[j+2]+m[14];minY=Math.min(minY,y);maxY=Math.max(maxY,y);radial=Math.max(radial,Math.hypot(x,z));if(leaf||petiole||component==='hair-bergenia')leafTop=Math.max(leafTop,y);actualVertices++;}
    }
   }
   assert.ok(roots.length>0&&rhizomes.length===3);assert.equal(roots.length,petioles.length);assert.equal(hairBases.length,roots.length*26,'every leaf retains 26 schematic edge hairs at tiny size');assert.ok(minY>=-eps,'above soil '+JSON.stringify({dims,month,minY}));assert.ok(maxY<=s.height+eps,'saved full height '+JSON.stringify({dims,month,maxY,height:s.height}));assert.ok(radial*2<=s.spread+eps,'saved full width');assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+eps,'leaf and petiole cap');
   const distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),segmentDistance=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),n=d.reduce((v,x)=>v+x*x,0),t=n?Math.max(0,Math.min(1,d.reduce((v,x,i)=>v+x*(p[i]-a[i]),0)/n)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};
   const expectedHairBases=leafMatrices.flatMap(m=>Array.from({length:26},(_,j)=>new Vector3(...dumboLeafPoint('bergeniaRound',1,-Math.PI+(j+.3)*(Math.PI*2)/26)).applyMatrix4(m).toArray()));for(const point of hairBases)assert.ok(expectedHairBases.some(expected=>distance(point,expected)<eps),'scaled hair base remains on a reference leaf rim independent of short-axis batching');
   for(const pt of roots){assert.ok(petioles.some(x=>distance(pt,x.ends[1])<eps),'real blade origin meets petiole tip');attachedLeaves++;}
   for(const x of petioles){assert.ok(rhizomes.some(r=>segmentDistance(x.ends[0],...r.ends)<=r.radius+eps),'petiole base intersects thick rhizome');attachedPetioles++;}
   assert.deepEqual(p,original);if(month===4&&!reference)diagnostics.push({dims,minY,maxY,actualSpread:radial*2,actualLeafHeight:leafTop,leaves:roots.length,petioles:petioles.length,scale:g.scale.toArray()});
  }finally{dispose(g);}
 }
 assert.equal(models,45);const doc=emptyDocument(14,6);doc.plans.A.plants=[...c.sizes,...tiny].map((d,i)=>({...makePlant(c.id,707100+i,1+i*1.5,3),height:d[0],spread:d[1],leafHeight:d[2]}));doc.view.month=4;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-25.9'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);console.log('DUMBO_707_GEOMETRY '+JSON.stringify({models,actualVertices,attachedLeaves,attachedPetioles,diagnostics}));
});
const BERGENIA_SEEDLING_708={id:'p-8b63abc96633',pid:70810,sizes:[[.4,.5,.3],[.08,.18,.04],[.4,.5,.005]]};
test('Bergenia seedling reference leaves and petioles stay connected to rhizomes inside independent saved dimensions',()=>{
 const c=BERGENIA_SEEDLING_708,tiny=[[.01,.1,.005],[.5,.1,.005],[.01,.6,.005],[.5,.1,.006]],cases=[...c.sizes.flatMap(dims=>Array.from({length:12},(_,i)=>({dims,month:i+1,reference:false}))),...tiny.flatMap(dims=>[1,4].map(month=>({dims,month,reference:false}))),{dims:c.sizes[1],month:4,reference:true}],eps=1e-7;let models=0,actualVertices=0,attachedLeaves=0,attachedPetioles=0;const diagnostics=[];
 assert.deepEqual(CATALOG[c.id].height,[.4,.4]);assert.equal(CATALOG[c.id].spread,null);assert.equal(CATALOG[c.id].latin,'Bergenia hybrids');assert.deepEqual(CATALOG[c.id].bloom,[3,4,5]);assert.equal(CATALOG[c.id].sourceChecked,'2026-10-10');assert.ok(appearanceSummary(CATALOG[c.id]).includes('厚みと丸い縁'));
 for(const {dims,month,reference}of cases){models++;const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},original=structuredClone(p),s=stateAt(p,{month,year:1,reference}),g=plantModel(p,{month,year:1,reference}),matrix=new Matrix4();let minY=Infinity,maxY=-Infinity,radial=0,leafTop=-Infinity;const roots=[],petioles=[],rhizomes=[];
  try{g.updateMatrixWorld(true);assert.equal(g.userData.architecture,'bergeniaRhizomes');const count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);assert.ok(count('scape-bergenia')>0&&count('panicle-bergenia')>0&&count('pedicel-bergenia')>0);assert.equal(count('petal-bergenia')>0,[3,4,5].includes(month));assert.ok(!g.children.some(m=>/^(fruit|seed|capsule)-/.test(m.userData.component)));
   for(const mesh of g.children){const component=mesh.userData.component,leaf=component==='leaf-bergenia-glossy',petiole=component==='petiole-bergenia',rhizome=component==='rhizome-bergenia',pos=mesh.geometry.attributes.position.array;assert.ok(pos.every(Number.isFinite)&&mesh.geometry.attributes.normal.array.every(Number.isFinite)&&mesh.instanceMatrix.array.every(Number.isFinite));
    for(let i=0;i<mesh.count;i++){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);const m=matrix.elements;
     if(leaf)roots.push([m[12],m[13],m[14]]);
     if(petiole||rhizome){const ends=[-0.5,0.5].map(t=>[m[12]+m[4]*t,m[13]+m[5]*t,m[14]+m[6]*t]),radius=Math.hypot(m[0],m[1],m[2]);(petiole?petioles:rhizomes).push({ends,radius});}
     for(let j=0;j<pos.length;j+=3){const x=m[0]*pos[j]+m[4]*pos[j+1]+m[8]*pos[j+2]+m[12],y=m[1]*pos[j]+m[5]*pos[j+1]+m[9]*pos[j+2]+m[13],z=m[2]*pos[j]+m[6]*pos[j+1]+m[10]*pos[j+2]+m[14];minY=Math.min(minY,y);maxY=Math.max(maxY,y);radial=Math.max(radial,Math.hypot(x,z));if(leaf||petiole)leafTop=Math.max(leafTop,y);actualVertices++;}
    }
   }
   assert.ok(roots.length>0&&rhizomes.length===3);assert.equal(roots.length,petioles.length);assert.ok(minY>=-eps,'above soil '+JSON.stringify({dims,month,minY}));assert.ok(maxY<=s.height+eps,'saved full height '+JSON.stringify({dims,month,maxY,height:s.height}));assert.ok(radial*2<=s.spread+eps,'saved full width');assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+eps,'leaf and petiole cap');
   const distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),segmentDistance=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),n=d.reduce((v,x)=>v+x*x,0),t=n?Math.max(0,Math.min(1,d.reduce((v,x,i)=>v+x*(p[i]-a[i]),0)/n)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};
   for(const pt of roots){assert.ok(petioles.some(x=>distance(pt,x.ends[1])<eps),'real blade origin meets petiole tip');attachedLeaves++;}
   for(const x of petioles){assert.ok(rhizomes.some(r=>segmentDistance(x.ends[0],...r.ends)<=r.radius+eps),'petiole base intersects thick rhizome');attachedPetioles++;}
   assert.deepEqual(p,original);if(month===4&&!reference)diagnostics.push({dims,minY,maxY,actualSpread:radial*2,actualLeafHeight:leafTop,leaves:roots.length,petioles:petioles.length,scale:g.scale.toArray()});
  }finally{dispose(g);}
 }
 assert.equal(models,45);const doc=emptyDocument(14,6);doc.plans.A.plants=[...c.sizes,...tiny].map((d,i)=>({...makePlant(c.id,708100+i,1+i*1.5,3),height:d[0],spread:d[1],leafHeight:d[2]}));doc.view.month=4;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-25.10'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);console.log('BERGENIA_SEEDLING_708_GEOMETRY '+JSON.stringify({models,actualVertices,attachedLeaves,attachedPetioles,diagnostics}));
});
import {saxifrageLeafPoint as shichihengeLeafPoint} from '../site/plant-detail.js';

const SHICHIHENGE_709={id:'p-a437b97beb3d',pid:70910,sizes:[[.3,.4,.18],[.06,.18,.02],[.3,.4,.005]]};
test('Shichihenge hairy leaves and petioles meet child rosettes on connected runners within independent saved dimensions',()=>{
 const c=SHICHIHENGE_709,tiny=[[.01,.1,.005],[.5,.1,.005],[.01,.6,.005],[.5,.1,.006]],cases=[...c.sizes.flatMap(dims=>Array.from({length:12},(_,i)=>({dims,month:i+1,reference:false}))),...tiny.flatMap(dims=>[1,6].map(month=>({dims,month,reference:false}))),{dims:c.sizes[1],month:6,reference:true}],eps=1e-7;let models=0,actualVertices=0,attachedLeaves=0,attachedPetioles=0;const diagnostics=[];
 assert.deepEqual(CATALOG[c.id].height,[.2,.4]);assert.equal(CATALOG[c.id].spread,null);assert.equal(CATALOG[c.id].latin,'Saxifraga stolonifera');assert.deepEqual(CATALOG[c.id].bloom,[6]);assert.equal(CATALOG[c.id].sourceChecked,'2026-10-25');assert.ok(appearanceSummary(CATALOG[c.id]).includes('葉脈と毛'));
 for(const {dims,month,reference}of cases){models++;const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},original=structuredClone(p),s=stateAt(p,{month,year:1,reference}),g=plantModel(p,{month,year:1,reference}),matrix=new Matrix4();let minY=Infinity,maxY=-Infinity,radial=0,leafTop=-Infinity;const roots=[],petioles=[],rhizomes=[],leafMatrices=[],hairBases=[];
  try{g.updateMatrixWorld(true);assert.equal(g.userData.architecture,'saxifrageRosettes');const count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);assert.equal(count('scape-saxifrage')>0,month===6);if(month===6)assert.ok(count('panicle-saxifrage')>0&&count('pedicel-saxifrage')>0);assert.equal(count('petal-saxifrage-long')>0,[6].includes(month));assert.ok(!g.children.some(m=>/^(fruit|seed|capsule)-/.test(m.userData.component)));
   for(const mesh of g.children){const component=mesh.userData.component,leaf=component.startsWith('leaf-saxifrage-shichihenge-'),petiole=component==='petiole-saxifrage',rhizome=component==='runner-saxifrage',pos=mesh.geometry.attributes.position.array;assert.ok(pos.every(Number.isFinite)&&mesh.geometry.attributes.normal.array.every(Number.isFinite)&&mesh.instanceMatrix.array.every(Number.isFinite));
    for(let i=0;i<mesh.count;i++){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);const m=matrix.elements;
     if(leaf){roots.push([m[12],m[13],m[14]]);leafMatrices.push(matrix.clone());}if(component==='hair-saxifrage')hairBases.push([m[12]-m[4]*.5,m[13]-m[5]*.5,m[14]-m[6]*.5]);
     if(petiole||rhizome){const ends=[-0.5,0.5].map(t=>[m[12]+m[4]*t,m[13]+m[5]*t,m[14]+m[6]*t]),radius=Math.hypot(m[0],m[1],m[2]);(petiole?petioles:rhizomes).push({ends,radius});}
     for(let j=0;j<pos.length;j+=3){const x=m[0]*pos[j]+m[4]*pos[j+1]+m[8]*pos[j+2]+m[12],y=m[1]*pos[j]+m[5]*pos[j+1]+m[9]*pos[j+2]+m[13],z=m[2]*pos[j]+m[6]*pos[j+1]+m[10]*pos[j+2]+m[14];minY=Math.min(minY,y);maxY=Math.max(maxY,y);radial=Math.max(radial,Math.hypot(x,z));if(leaf||petiole||rhizome||component==='hair-saxifrage')leafTop=Math.max(leafTop,y);actualVertices++;}
    }
   }
   assert.ok(roots.length>0&&rhizomes.length===36);assert.equal(roots.length,petioles.length);assert.equal(hairBases.length,roots.length*26,'every leaf retains 26 schematic edge hairs at tiny size');assert.ok(minY>=-eps,'above soil '+JSON.stringify({dims,month,minY}));assert.ok(maxY<=s.height+eps,'saved full height '+JSON.stringify({dims,month,maxY,height:s.height}));assert.ok(radial*2<=s.spread+eps,'saved full width');assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+eps,'leaf and petiole cap');
   const distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),segmentDistance=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),n=d.reduce((v,x)=>v+x*x,0),t=n?Math.max(0,Math.min(1,d.reduce((v,x,i)=>v+x*(p[i]-a[i]),0)/n)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};
   const expectedHairBases=leafMatrices.flatMap(m=>Array.from({length:26},(_,j)=>new Vector3(...shichihengeLeafPoint('saxifrageCordate',1,-Math.PI+(j+.3)*(Math.PI*2)/26)).applyMatrix4(m).toArray()));for(const point of hairBases)assert.ok(expectedHairBases.some(expected=>distance(point,expected)<eps),'scaled hair base remains on a reference leaf rim independent of short-axis batching');
   for(const pt of roots){assert.ok(petioles.some(x=>distance(pt,x.ends[1])<eps),'real blade origin meets petiole tip');attachedLeaves++;}
   for(let i=0;i<rhizomes.length;i++)if(i%6!==5)assert.ok(distance(rhizomes[i].ends[1],rhizomes[i+1].ends[0])<eps,'successive runner segments meet');for(const x of petioles){assert.ok(rhizomes.some(r=>r.ends.some(point=>distance(x.ends[0],point)<eps)),'petiole base meets a connected runner endpoint');attachedPetioles++;}
   assert.deepEqual(p,original);if(month===6&&!reference)diagnostics.push({dims,minY,maxY,actualSpread:radial*2,actualLeafHeight:leafTop,leaves:roots.length,petioles:petioles.length,scale:g.scale.toArray()});
  }finally{dispose(g);}
 }
 assert.equal(models,45);const doc=emptyDocument(14,6);doc.plans.A.plants=[...c.sizes,...tiny].map((d,i)=>({...makePlant(c.id,709100+i,1+i*1.5,3),height:d[0],spread:d[1],leafHeight:d[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-25.11'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);console.log('SHICHIHENGE_709_GEOMETRY '+JSON.stringify({models,actualVertices,attachedLeaves,attachedPetioles,diagnostics}));
});
