const BLUE_UMBRELLA_712={id:'p-e0e65a82a219',pid:71210,sizes:[[.9,.8,.6],[.08,.18,.04],[.9,.8,.005]]};
test('Blue Umbrella fan leaves share crown origins and tiny umbels fit independent saved dimensions',()=>{
 const c=BLUE_UMBRELLA_712,tiny=[[.01,.1,.005],[.5,.1,.005],[.01,.6,.005],[.5,.1,.006]],cases=[...c.sizes.flatMap(dims=>Array.from({length:12},(_,i)=>({dims,month:i+1,reference:false}))),...tiny.flatMap(dims=>[1,6].map(month=>({dims,month,reference:false}))),{dims:c.sizes[1],month:6,reference:true}],eps=1e-7;let models=0,actualVertices=0,fanLeaves=0,crownOrigins=0;const diagnostics=[];
 assert.deepEqual(CATALOG[c.id].height,[.6,1.2]);assert.equal(CATALOG[c.id].spread,null);assert.equal(CATALOG[c.id].latin,'Agapanthus spp.');assert.deepEqual(CATALOG[c.id].bloom,[6,7]);assert.deepEqual(CATALOG[c.id].colors,['blue']);assert.equal(CATALOG[c.id].sourceChecked,'2026-10-25');assert.equal(CATALOG[c.id].appearance.persistence,'evergreen');
 for(const{dims,month,reference}of cases){models++;const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},original=structuredClone(p),s=stateAt(p,{month,year:1,reference}),g=plantModel(p,{month,year:1,reference}),matrix=new Matrix4();let minY=Infinity,maxY=-Infinity,radial=0,leafTop=-Infinity;const roots=[],scapes=[];
  try{g.updateMatrixWorld(true);assert.equal(g.userData.architecture,'agapanthusFans');assert.equal(s.groundDormant,false);const count=k=>g.children.filter(m=>m.userData.component.startsWith(k)).reduce((n,m)=>n+m.count,0),petals=count('petal-agapanthus'),leaves=count('leaf-agapanthus');assert.ok(leaves>=5);assert.equal(petals>0,[6,7].includes(month));assert.equal(count('scape-agapanthus')>0,[5,6,7].includes(month));assert.equal(count('spathe-agapanthus')>0,month===5);assert.equal(count('anther-agapanthus'),petals);assert.equal(count('filament-agapanthus'),petals);assert.equal(count('style-agapanthus')*6,petals);assert.ok(!g.children.some(m=>/^(fruit|seed|root|rhizome)-/.test(m.userData.component)));
   for(const mesh of g.children){const component=mesh.userData.component,leaf=component.startsWith('leaf-agapanthus'),pos=mesh.geometry.attributes.position.array;assert.ok(pos.every(Number.isFinite)&&mesh.geometry.attributes.normal.array.every(Number.isFinite)&&mesh.instanceMatrix.array.every(Number.isFinite));if(leaf){let origin=false;for(let j=0;j<pos.length;j+=3)if(Math.abs(pos[j])+Math.abs(pos[j+1])+Math.abs(pos[j+2])<1e-8){origin=true;break;}assert.ok(origin,'real blade origin vertex');}
    for(let i=0;i<mesh.count;i++){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);const m=matrix.elements;if(leaf)roots.push([m[12],m[13],m[14]]);if(component==='scape-agapanthus')scapes.push([m[12]-m[4]*.5,m[13]-m[5]*.5,m[14]-m[6]*.5]);for(let j=0;j<pos.length;j+=3){const x=m[0]*pos[j]+m[4]*pos[j+1]+m[8]*pos[j+2]+m[12],y=m[1]*pos[j]+m[5]*pos[j+1]+m[9]*pos[j+2]+m[13],z=m[2]*pos[j]+m[6]*pos[j+1]+m[10]*pos[j+2]+m[14];minY=Math.min(minY,y);maxY=Math.max(maxY,y);radial=Math.max(radial,Math.hypot(x,z));if(leaf)leafTop=Math.max(leafTop,y);actualVertices++;}}
   }
   assert.ok(minY>=-eps,'above soil '+JSON.stringify({dims,month,minY}));assert.ok(maxY<=s.height+eps,'saved full height '+JSON.stringify({dims,month,maxY,height:s.height}));assert.ok(radial*2<=s.spread+eps,'saved width');assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+eps,'independent blade cap');
   const distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),unique=[];for(const point of roots){if(!unique.some(x=>distance(x,point)<eps))unique.push(point);assert.ok(Math.hypot(point[0],point[2])<=s.spread*.13+eps);assert.ok(point[1]>=-eps&&point[1]<=Math.min(s.height,s.leafHeight)*.10+eps);if(scapes.length)assert.ok(scapes.some(x=>distance(x,point)<eps),'fan origin meets actual flower-scape base');}assert.equal(unique.length,5,'five shared crown origins retained');if(scapes.length)assert.equal(scapes.length,5);crownOrigins+=unique.length;fanLeaves+=leaves;assert.deepEqual(p,original);
   if(month===6&&!reference)diagnostics.push({dims,minY,maxY,actualSpread:radial*2,actualLeafHeight:leafTop,leaves,scapes:scapes.length,petals,anthers:count('anther-agapanthus'),scale:g.scale.toArray()});
  }finally{dispose(g);}
 }
 assert.equal(models,45);const doc=emptyDocument(14,6);doc.plans.A.plants=[...c.sizes,...tiny].map((d,i)=>({...makePlant(c.id,712100+i,1+i*1.5,3),height:d[0],spread:d[1],leafHeight:d[2]}));doc.view.month=6;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-25.14'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);console.log('BLUE_UMBRELLA_712_GEOMETRY '+JSON.stringify({models,actualVertices,fanLeaves,crownOrigins,diagnostics}));
});

