   assert.ok(minY>=-eps,'above soil '+JSON.stringify({dims,month,minY}));assert.ok(maxY<=s.height+eps,'saved full height '+JSON.stringify({dims,month,maxY,height:s.height}));assert.ok(radial*2<=s.spread+eps,'saved width');assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+eps,'independent blade cap');
   const distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),unique=[];for(const point of roots){if(!unique.some(x=>distance(x,point)<eps))unique.push(point);assert.ok(Math.hypot(point[0],point[2])<=s.spread*.13+eps);assert.ok(point[1]>=-eps&&point[1]<=Math.min(s.height,s.leafHeight)*.10+eps);if(scapes.length)assert.ok(scapes.some(x=>distance(x,point)<eps),'fan origin meets actual flower-scape base');}assert.equal(unique.length,5,'five shared crown origins retained');if(scapes.length)assert.equal(scapes.length,5);crownOrigins+=unique.length;fanLeaves+=leaves;assert.deepEqual(p,original);
