    const dist=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),onSegment=(pt,[a,b])=>{const d=b.map((x,i)=>x-a[i]),den=d.reduce((n,x)=>n+x*x,0),t=Math.max(0,Math.min(1,pt.reduce((n,x,i)=>n+(x-a[i])*d[i],0)/den));return dist(pt,a.map((x,i)=>x+d[i]*t))<eps;};
    for(const pt of petioleFrom)assert.ok(stemSegments.some(x=>onSegment(pt,x)),c.id+' petiole attaches to rendered stem');for(const pt of leafOrigins)assert.ok(petioleTo.some(x=>dist(pt,x)<eps),'real leaflet origin meets petiole tip');for(const pt of stipuleOrigins)assert.ok(petioleFrom.some(x=>dist(pt,x)<eps),'stipule origin meets stem node');leaflets+=leaves;petioles+=stalks;assert.deepEqual(p,original);
