    const dist=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),onStem=pt=>stemSegments.some(([a,b])=>{const d=b.map((x,i)=>x-a[i]),n=d.reduce((n,x)=>n+x*x,0),t=Math.max(0,Math.min(1,pt.reduce((n,x,i)=>n+(x-a[i])*d[i],0)/n));return dist(pt,a.map((x,i)=>x+d[i]*t))<eps;});for(const pt of petioleFrom)assert.ok(onStem(pt)||petioleTo.some(x=>dist(pt,x)<eps),'continuous curved petiole rooted on actual stem segment');for(const pt of leafOrigins)assert.ok(petioleTo.some(x=>dist(pt,x)<eps),'compound leaflet origins meet petiole tip');for(const pt of stipuleOrigins)assert.ok(onStem(pt),'stipule origin meets actual stem segment');leaflets+=leaves;petioleSegments+=pet;stems+=runner;assert.deepEqual(p,original);
