test('Trailing Tiarella keep connected runner leaves in independent caps and tiny complete racemes',()=>{
 let models=0,actualVertices=0,leavesTotal=0,petiolesTotal=0,scapesTotal=0;const diagnostics=[],eps=1e-7,dist=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i]));
 for(const c of TIARELLA_737){const info=CATALOG[c.id];assert.deepEqual(info.height,c.height);assert.deepEqual(info.spread,c.spread);assert.equal(info.bloomKnown,false);assert.deepEqual(info.bloom,[5,6]);assert.equal(info.sourceChecked,'2026-10-25');assert.equal(info.appearance.habit,'trailing');assert.equal(info.appearance.status,'partial');assert.deepEqual(info.colors,['white']);
 const tiny=[[.01,.1,.005],[.1,.1,.005],[.01,.6,.005],[.1,.1,.006]],cases=[...c.sizes.flatMap(dims=>Array.from({length:12},(_,i)=>({dims,month:i+1,reference:false}))),...tiny.flatMap(dims=>[1,5].map(month=>({dims,month,reference:false}))),{dims:c.sizes[1],month:5,reference:true}];
 for(const{dims,month,reference}of cases){models++;const p={...makePlant(c.id,c.pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},original=structuredClone(p),s=stateAt(p,{month,year:1,reference}),g=plantModel(p,{month,year:1,reference}),matrix=new Matrix4();let minY=Infinity,maxY=-Infinity,radial=0,leafTop=-Infinity;const froms=[],tos=[],leafOrigins=[],scapeRoots=[],runners=[];
 try{
  g.updateMatrixWorld(true);assert.equal(s.groundDormant,false);assert.equal(g.userData.surfaceInspectionDistance,undefined);
  const count=k=>g.children.filter(m=>m.userData.component.startsWith(k)).reduce((n,m)=>n+m.count,0),leaves=count('leaf-tiarella-'),pet=count('petiole-tiarella'),scapes=count('scape-tiarella'),flowers=count('receptacle-tiarella'),buds=count('bud-tiarella');
  assert.ok(leaves>=10);assert.equal(pet,leaves*2,'two connected petiole segments per blade');assert.ok(count('runner-tiarella')>0);assert.equal(scapes>0,[5,6].includes(month));assert.equal(count('raceme-tiarella'),scapes);assert.equal(count('pedicel-tiarella'),flowers+buds);assert.equal(count('petal-tiarella'),flowers*5);assert.equal(count('sepal-tiarella'),flowers*5);assert.equal(count('filament-tiarella'),flowers*10);assert.equal(count('anther-tiarella'),flowers*10);assert.equal(count('style-tiarella'),flowers*2);
  for(const mesh of g.children){const component=mesh.userData.component,foliage=component.startsWith('leaf-tiarella-')||component==='petiole-tiarella',pos=mesh.geometry.attributes.position.array;assert.ok(pos.every(Number.isFinite)&&mesh.geometry.attributes.normal.array.every(Number.isFinite)&&mesh.instanceMatrix.array.every(Number.isFinite)&&mesh.instanceColor.array.every(Number.isFinite));
   for(let i=0;i<mesh.count;i++){mesh.getMatrixAt(i,matrix);matrix.premultiply(mesh.matrixWorld);const m=matrix.elements,origin=[m[12],m[13],m[14]],ends=[-.5,.5].map(v=>[m[12]+m[4]*v,m[13]+m[5]*v,m[14]+m[6]*v]);if(component==='runner-tiarella')runners.push(ends);if(component==='petiole-tiarella'){froms.push(ends[0]);tos.push(ends[1]);}if(component==='scape-tiarella')scapeRoots.push(ends[0]);if(component.startsWith('leaf-tiarella-'))leafOrigins.push(origin);
    for(let j=0;j<pos.length;j+=3){const x=m[0]*pos[j]+m[4]*pos[j+1]+m[8]*pos[j+2]+m[12],y=m[1]*pos[j]+m[5]*pos[j+1]+m[9]*pos[j+2]+m[13],z=m[2]*pos[j]+m[6]*pos[j+1]+m[10]*pos[j+2]+m[14];minY=Math.min(minY,y);maxY=Math.max(maxY,y);radial=Math.max(radial,Math.hypot(x,z));if(foliage)leafTop=Math.max(leafTop,y);actualVertices++;}
   }
  }
  assert.ok(minY>=-eps,'above soil '+JSON.stringify({id:c.id,dims,month,minY}));assert.ok(maxY<=s.height+eps,'full height '+JSON.stringify({id:c.id,dims,month,maxY}));assert.ok(radial*2<=s.spread+eps,'full width '+JSON.stringify({id:c.id,dims,month,width:radial*2}));assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+eps,'independent leaf cap '+JSON.stringify({id:c.id,dims,month,leafTop}));
  const onRunner=pt=>runners.some(([a,b])=>{const d=b.map((x,i)=>x-a[i]),n=d.reduce((v,x)=>v+x*x,0),t=Math.max(0,Math.min(1,pt.reduce((v,x,i)=>v+(x-a[i])*d[i],0)/n));return dist(pt,a.map((x,i)=>x+d[i]*t))<eps;});
  const roots=froms.filter(pt=>!tos.some(x=>dist(pt,x)<eps));assert.equal(roots.length,leaves,'each two-segment petiole starts on an actual runner');for(const pt of roots)assert.ok(onRunner(pt),'petiole root lies on actual runner');for(const pt of scapeRoots)assert.ok(onRunner(pt),'scape starts at actual runner node');
  for(const pt of leafOrigins)assert.ok(tos.some(x=>dist(pt,x)<eps),'blade origin meets actual petiole tip');for(const pt of froms)assert.ok(onRunner(pt)||tos.some(x=>dist(pt,x)<eps),'petiole connected to runner or previous segment');
  leavesTotal+=leaves;petiolesTotal+=pet;scapesTotal+=scapes;assert.deepEqual(p,original);if(month===5&&!reference)diagnostics.push({id:c.id,dims,minY,maxY,actualSpread:radial*2,actualLeafHeight:leafTop,leaves,petioles:pet,scapes,scale:g.scale.toArray()});
 }finally{dispose(g);}
 }
 const doc=emptyDocument(10,6);doc.plans.A.plants=c.sizes.map((d,i)=>({...makePlant(c.id,737100+i,2+i*2,3),height:d[0],spread:d[1],leafHeight:d[2]}));doc.view.month=5;doc.view.year=1;const raw={...structuredClone(doc),catalogVersion:'2026-10-25.39'},before=structuredClone(raw);assert.deepEqual(validateDocument(raw),doc);assert.deepEqual(raw,before);
 }
 assert.equal(models,135);console.log('TIARELLA_737_GEOMETRY '+JSON.stringify({models,actualVertices,leaves:leavesTotal,petioles:petiolesTotal,scapes:scapesTotal,diagnostics}));
});

