 const cases=[...sizes.flatMap(dims=>[1,2,3,5,6,8,12].map(month=>({dims,month,reference:false}))),...sizes.flatMap(dims=>[{dims,month:5,reference:true},{dims:[.01,dims[1],dims[2]],month:5,reference:false},{dims:[dims[0],.1,dims[2]],month:5,reference:false}])];let models=0,actualVertices=0,openModels=0,cameraPoses=0,maxSurfaceAttempts=0,basalConnections=0,lateralConnections=0,stemConnections=0,winterCases=0;const diagnostics=[];
