 const id='p-fb328e7a0f52',info=CATALOG[id],a=info.appearance,sizes=[[.08,.25,.05],[.03,.18,.012],[.08,.25,.005]],eps=1e-7,distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),onSegment=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),len=d.reduce((n,x)=>n+x*x,0),t=len?Math.max(0,Math.min(1,d.reduce((n,x,i)=>n+x*(p[i]-a[i]),0)/len)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};
