      for(let i=first;i<first+5;i++){petals.getMatrixAt(i,matrix);matrix.premultiply(petals.matrixWorld);const pos=petals.geometry.attributes.position;for(let j=0;j<pos.count;j++){const q=new Vector3().fromBufferAttribute(pos,j).applyMatrix4(matrix).project(camera);assert.ok(Math.abs(q.x)<=1.00001&&Math.abs(q.y)<=1.00001&&q.z>=-1.00001&&q.z<=1.00001,ctx+' complete five lobes inside horizontal vertical near and far planes');}}cameraPoses++;
