 for(const aspect of [.8,1.65]){const pose=flowerInspectionView(g,aspect,40),camera=new PerspectiveCamera(40,aspect,.00001,100);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(),camera);const hit=ray.intersectObjects(g.children,false)[0];assert.ok(hit);assert.equal(hit.object,bells);assert.equal(hit.instanceId,surface.instanceId);assert.equal(hit.faceIndex,surface.faceIndex);bells.getMatrixAt(surface.instanceId,matrix);matrix.premultiply(bells.matrixWorld);for(let j=0;j<3577;j++){const q=new Vector3().fromBufferAttribute(bells.geometry.attributes.position,j).applyMatrix4(matrix).project(camera);assert.ok(Math.abs(q.x)<=1.00001&&Math.abs(q.y)<=1.00001&&q.z<1,ctx+'complete bell');}cameraPoses++;}
