 for(const aspect of [.8,1.65]){const pose=flowerInspectionView(g,aspect,40),camera=new PerspectiveCamera(40,aspect,.00001,100);camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(),camera);const hit=ray.intersectObjects(g.children,false)[0];assert.ok(hit);assert.equal(hit.object,tepals);assert.equal(hit.instanceId,surface.instanceId);assert.equal(hit.faceIndex,surface.faceIndex);const organ=surface.instanceId,parts=[[tepals,[surface.instanceId]],...(surface.component==='petal-grape-urn'?[[ovary,[organ]],[anthers,Array.from({length:6},(_,i)=>organ*6+i)],[stigmas,Array.from({length:3},(_,i)=>organ*3+i)]]:[])];for(const[m,indices]of parts)for(const i of indices){m.getMatrixAt(i,matrix);matrix.premultiply(m.matrixWorld);const pos=m.geometry.attributes.position;for(let j=0;j<pos.count;j++){const q=new Vector3().fromBufferAttribute(pos,j).applyMatrix4(matrix).project(camera);assert.ok(Math.abs(q.x)<=1.00001&&Math.abs(q.y)<=1.00001&&q.z<1,ctx+'wholefusedbellandretainedorgans');}}cameraPoses++;}
