 const rows=[{id:'p-8118e2844435',type:'cilicium',source:'https://item.rakuten.co.jp/ogis/185gc/',height:[.08,.15],normal:[.115,.125,.065],bloom:[10,11,12],flowers:10}],eps=1e-7;
