    let minY=Infinity,maxY=-Infinity,radial=0,leafTop=0;
    for(const m of g.children){assert.ok(m.instanceMatrix.array.every(Number.isFinite),ctx+' finite matrices');assert.ok(m.geometry.attributes.normal.array.every(Number.isFinite),ctx+' finite normals');const pos=m.geometry.attributes.position;
     for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);if(/petiole|peduncle|neck/.test(m.userData.component)&&new Vector3(0,-.5,0).applyMatrix4(matrix).distanceTo(new Vector3(0,.5,0).applyMatrix4(matrix))<.0001)shortAxes++;matrix.premultiply(m.matrixWorld);const e=matrix.elements;for(let j=0;j<pos.count;j++){actualVertices++;const x=pos.getX(j),y=pos.getY(j),z=pos.getZ(j),xx=e[0]*x+e[4]*y+e[8]*z+e[12],yy=e[1]*x+e[5]*y+e[9]*z+e[13],zz=e[2]*x+e[6]*y+e[10]*z+e[14];assert.ok(Number.isFinite(xx)&&Number.isFinite(yy)&&Number.isFinite(zz),ctx+' finite world vertex');minY=Math.min(minY,yy);maxY=Math.max(maxY,yy);radial=Math.max(radial,Math.hypot(xx,zz));if(m.userData.component===leafComponent||m.userData.component==='petiole-autumn-cyclamen')leafTop=Math.max(leafTop,yy);}}
    }
    assert.ok(minY>=-eps,ctx+' ground '+minY);assert.ok(maxY<=s.height+eps,ctx+' height '+maxY);assert.ok(radial*2<=s.spread+eps,ctx+' footprint '+radial*2);assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+eps,ctx+' leaf height '+leafTop);assert.ok(!g.children.some(m=>/anther|stigma|style|ovary|fruit/.test(m.userData.component)),ctx+' unresolved reproductive organs remain absent');
