   for(const [meshes,stalks]of[[leaves,petiolules],[involucres,involucreStalks]]){const used=new Set();for(const m of meshes){assert.ok(m.geometry.userData.autumnSwanLeaflet);assert.equal(m.geometry.attributes.position.count,1617);for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);const origin=new Vector3().applyMatrix4(matrix),matches=stalks.map((stalk,index)=>({stalk,index})).filter(x=>x.stalk.to.distanceTo(origin)<eps);assert.equal(matches.length,1,ctx+' leaflet attached to one actual stalk');assert.ok(!used.has(matches[0].index));used.add(matches[0].index);leafletJoins++;}}}
