    for(const aspect of[.8,1.65]){const pose=flowerInspectionView(g,aspect,40),camera=new PerspectiveCamera(40,aspect,.01,650);assert.ok(pose&&pose.position.every(Number.isFinite)&&pose.target.every(Number.isFinite));camera.position.fromArray(pose.position);camera.lookAt(new Vector3(...pose.target));camera.updateMatrixWorld(true);const ray=new Raycaster();ray.near=camera.near;ray.far=camera.far;ray.setFromCamera(new Vector2(),camera);const hit=ray.intersectObjects(g.children,false)[0];assert.ok(hit,ctx+' visible flower');assert.equal(hit.object,sepals);assert.equal(hit.instanceId,surface.instanceId);assert.equal(hit.faceIndex,surface.faceIndex);const first=Math.floor(surface.instanceId/pieces)*pieces;for(let i=first;i<first+pieces;i++){sepals.getMatrixAt(i,matrix);matrix.premultiply(sepals.matrixWorld);const pos=sepals.geometry.attributes.position;for(let j=0;j<pos.count;j++){const q=new Vector3().fromBufferAttribute(pos,j).applyMatrix4(matrix).project(camera);assert.ok(Math.abs(q.x)<=1.00001&&Math.abs(q.y)<=1.00001&&q.z>=-1.00001&&q.z<=1.00001,ctx+' complete reference flower inside actual frustum');}}cameraPoses++;}
