test('Hatsune irregular green yellow leaf mottling and pale sepal streaks compile only on the variegated reference',()=>{
 for(const[ci,id]of ['p-be413945a49b','p-0c40610ead9b','p-b46416a70d7b'].entries()){
  const p={...makePlant(id,83940+ci,3,3),height:.35,spread:.35,leafHeight:.2},g=plantModel(p,view(9));let mottled=0,striped=0;
  try{for(const m of g.children){const shader={uniforms:{},vertexShader:'#include <common>\n#include <begin_vertex>',fragmentShader:'#include <common>\n#include <color_fragment>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});const kind=m.userData.component,leaf=/^(leaf|involucre)-swan-/.test(kind),sepal=kind.startsWith('sepal-swan-');assert.equal(shader.fragmentShader.includes('hatsuneMottle'),ci===1&&leaf,kind);assert.equal(shader.fragmentShader.includes('hatsunePetalStripe'),ci===1&&sepal,kind);if(shader.fragmentShader.includes('hatsuneMottle'))mottled++;if(shader.fragmentShader.includes('hatsunePetalStripe'))striped++;}assert.equal(mottled>0,ci===1);assert.equal(striped>0,ci===1);if(ci===1){const m=g.children.find(m=>m.userData.component==='sepal-swan-hatsuneVariegated');assert.ok(m.instanceColor);const colors=new Set(Array.from({length:m.count},(_,i)=>Array.from(m.instanceColor.array.slice(i*3,i*3+3)).join(',')));assert.equal(colors.size,2);}}
  finally{dispose(g);}
 }
});

