test('Unconfirmed dimension envelopes stay visible and bound every placeholder by the input diameter and height',()=>{
 const entries=Object.entries(CATALOG).filter(([,p])=>p.form==='unmodeled');assert.ok(entries.some(([id])=>id==='p-95a790998020')&&entries.length>1);for(const[id]of entries)for(const dims of [[.2,.35,.15],[.005,.005,.005]]){const p={...makePlant(id,84890,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},v={year:1,month:2,reference:false},state=stateAt(p,v),g=plantModel(p,v);try{if(!state.present||state.groundDormant){assert.equal(g.children.length,0,'existing absence condition is preserved');continue;}assert.equal(g.userData.unmodeled,true);assert.equal(g.children.length,1);const frame=g.children[0];assert.equal(frame.isLineSegments,true);assert.equal(frame.userData.component,'dimension-frame');assert.equal(frame.material.transparent,false);assert.equal(frame.material.opacity,1);const a=frame.geometry.attributes.position;assert.ok(a.count>=16&&a.count%2===0);let top=0,maxDiameter=0;for(let j=0;j<a.count;j++){const v=new Vector3().fromBufferAttribute(a,j);assert.ok(v.toArray().every(Number.isFinite));assert.ok(v.y>=-1e-8&&v.y<=p.height+1e-7);top=Math.max(top,v.y);maxDiameter=Math.max(maxDiameter,2*Math.hypot(v.x,v.z));}assert.ok(Math.abs(top-p.height)<1e-7);assert.ok(Math.abs(maxDiameter-p.spread)<1e-7);assert.equal(flowerInspectionView(g,.8,40),null);}finally{dispose(g);}}
});

