test('Niger cultivar rooted compound leaves scapes and double flower surfaces fit independent dimensions without breaking attachments',()=>{
 const matrix=new Matrix4(),v=new Vector3(),dist=(a,b)=>Math.hypot(...a.map((x,k)=>x-b[k]));let models=0,joins=0;
 for(const id of ['p-b17e63179dfb','p-bcf1d10b9e81'])for(const dims of [[.2,.35,.15],[.03,.18,.012],[.2,.35,.005],[.005,.08,.005],[.2,.005,.005]])for(const month of [2,6]){const p={...makePlant(id,id==='p-b17e63179dfb'?84910:84911,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},copy=structuredClone(p),view={year:1,month,reference:false},s=stateAt(p,view),g=plantModel(p,view);models++;try{g.updateMatrixWorld(true);const leaves=[],ends=[];let leafTop=0,lo=Infinity,hi=-Infinity,diam=0;for(const m of g.children){const kind=m.userData.component,pos=m.geometry.attributes.position;for(const arr of [pos.array,m.geometry.attributes.normal.array,m.instanceMatrix.array])assert.ok(arr.every(Number.isFinite),id+' '+kind);for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);matrix.premultiply(m.matrixWorld);if(kind==='leaf-niger-cultivar')leaves.push(new Vector3(0,0,0).applyMatrix4(matrix).toArray());if(kind==='leaf-axis-niger-cultivar'||kind==='petiole-niger-cultivar')ends.push(new Vector3(0,.5,0).applyMatrix4(matrix).toArray());for(let j=0;j<pos.count;j++){v.fromBufferAttribute(pos,j).applyMatrix4(matrix);lo=Math.min(lo,v.y);hi=Math.max(hi,v.y);diam=Math.max(diam,2*Math.hypot(v.x,v.z));if(/^(leaf|petiole)/.test(kind))leafTop=Math.max(leafTop,v.y);}}}assert.ok(lo>=-1e-7,id+' ground '+dims+' '+lo);assert.ok(hi<=s.height+1e-7,id+' height '+dims+' '+hi);assert.ok(diam<=s.spread+1e-7,id+' width '+dims+' '+diam);assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+1e-7,id+' foliage cap '+dims+' '+leafTop);assert.ok(leaves.length>0);for(const at of leaves){assert.ok(ends.some(end=>dist(at,end)<1e-7),id+' actual leaf-axis/petiole join');joins++;}assert.equal(g.children.some(m=>m.userData.component.startsWith('sepal-niger-cultivar-')),s.bloom);assert.equal(g.children.some(m=>m.userData.component.startsWith('petaloid-niger-cultivar-')),s.bloom);assert.equal(g.children.some(m=>m.userData.component==='scape-niger-cultivar'),s.bloom);assert.equal(!!g.userData.flowerTargets?.length,s.bloom);assert.ok(!g.children.some(m=>/nectary|carpel|fruit|seed/.test(m.userData.component)));assert.deepEqual(p,copy);}finally{dispose(g);}}
 assert.ok(models>0&&joins>0);console.log('NIGER_CULTIVAR_BOUNDARIES '+JSON.stringify({models,actualLeafJoins:joins}));
});
test('Niger cultivar flower cameras intersect an actual indexed petaloid and preserve saved cultivar IDs camera and dimensions',()=>{
 for(const id of ['p-b17e63179dfb','p-bcf1d10b9e81'])for(const dims of [[.2,.35,.15],[.03,.18,.012],[.2,.35,.005]]){const p={...makePlant(id,id==='p-b17e63179dfb'?84910:84911,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{year:1,month:2,reference:false});try{assert.ok(g.userData.surfaceSelection?.matched,id+' actual surface selection');const a=g.userData.flowerTargets[0],surface=a.surface;assert.ok(surface.component.startsWith('petaloid-niger-cultivar-'));g.position.set(-2,.012,-1);g.updateMatrixWorld(true);for(const aspect of [.8,1.65]){const pose=flowerInspectionView(g,aspect,40),camera=new PerspectiveCamera(40,aspect,.01,650);assert.ok(pose);camera.position.fromArray(pose.position);camera.lookAt(...pose.target);camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.equal(hit?.object.userData.component,surface.component,id+' visible sepal');assert.equal(hit.instanceId,surface.instanceId);assert.equal(hit.faceIndex,surface.faceIndex);assert.ok(hit.point.distanceTo(new Vector3(...pose.target))<2e-6);}}finally{dispose(g);}const d=emptyDocument(10,6);d.plans.A.plants=[p];d.view={year:1,month:2,reference:false,footprints:false,camera:{position:[-1.5,.8,-.5],target:[-3,.3,-1]}};const old={...structuredClone(d),catalogVersion:'2026-10-26.63'},copy=structuredClone(old);assert.deepEqual(validateDocument(old),d);assert.deepEqual(old,copy);}
});

