test('Lividus surface winding assigns silver upper networks and pale purple lower faces without painting both sides alike',()=>{
 for(const id of ['p-c5dd453a7754','p-43c33a152eb1']){const g=plantModel(makePlant(id,85210,3,3),view(3));try{const leaves=g.children.filter(m=>m.userData.component.startsWith('leaf-lividus-ref-'));assert.ok(leaves.length);for(const m of leaves){const normal=m.geometry.attributes.normal;assert.ok(normal.getY(16*21+10)>.5);assert.match(m.geometry.userData.lividusOrgan,/^gcLividus(Central|Left|Right)Ref$/);const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/if\(gl_FrontFacing\)/);assert.match(shader.fragmentShader,/gcLividusWeb/);assert.ok(!shader.fragmentShader.includes('undefined'));}const sepals=g.children.find(m=>m.userData.component==='sepal-lividus-ref');assert.equal(sepals.geometry.userData.lividusOrgan,'gcLividusSepalRef');const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};sepals.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/gl_FrontFacing/);}finally{dispose(g);}}
});

