test('Sternii silver pigments retain distinct cultivar surfaces and stable leaf colours across flower removal',()=>{
 for(const[id,profile]of[['p-8cf8f9ce67a8','silverStar'],['p-5be8cc366a04','superSilver']])for(const dims of[[.25,.25,.16],[.03,.18,.012]]){
  let colours=null;
  for(const month of[3,12]){const p={...makePlant(id,85610,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{year:1,month,reference:false});try{const leaves=g.children.filter(m=>m.userData.component.startsWith('leaf-sternii-ref-'));assert.equal(leaves.reduce((n,m)=>n+m.count,0),27);assert.equal(new Set(leaves.map(m=>m.userData.component)).size,4);const arrays=leaves.map(m=>[m.userData.component,Buffer.from(m.instanceColor.array.buffer,m.instanceColor.array.byteOffset,m.count*12).toString('hex')]);if(colours)assert.deepEqual(arrays,colours);else colours=arrays;for(const m of leaves){assert.ok(m.userData.component.includes('-'+profile+'-'));const normal=m.geometry.attributes.normal;assert.ok(normal.getY(16*21+10)>.5);assert.match(m.geometry.userData.sterniiOrgan,/^gcSternii(Central|Left|Right)Ref$/);const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/if\(gl_FrontFacing\)/);assert.match(shader.fragmentShader,/gcSterniiWeb/);assert.ok(!shader.fragmentShader.includes('undefined'));}
   const sepals=g.children.find(m=>m.userData.component==='sepal-sternii-ref');assert.equal(!!sepals,month===3);if(sepals){assert.equal(sepals.geometry.userData.sterniiOrgan,'gcSterniiSepalRef');const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};sepals.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/if\(gl_FrontFacing\)/);assert.equal(sepals.material.customProgramCacheKey(),'garden-0.3-sepal-sternii-ref');}
  }finally{dispose(g);}}
 }
});

test('Sternii patterned retail sources separate variable foliage colours deeply serrated Rockies and flower colour identities',()=>{
 const rows=[['p-ece7f2f43884','diamondDust','100sd','sterniiSpottedLeaflets'],['p-2d28d4455739','neoGolden','100sn','sterniiGoldenLeaflets'],['p-ca5eb5a193f1','rockies','100rk','sterniiRockiesLeaflets']];
 for(const[id,profile,sku,leaf]of rows){const c=CATALOG[id],a=c.appearance;assert.equal(c.form,'botanical');assert.deepEqual(c.height,[.2,.3]);assert.deepEqual(c.spread,[.2,.3]);assert.deepEqual(c.bloom,[2,3,4,5]);assert.equal(c.bloomKnown,false);assert.deepEqual(c.colors,profile==='rockies'?['pink']:['pink','green']);assert.equal(c.source,'https://item.rakuten.co.jp/ogis/'+sku+'/');assert.equal(c.sourceChecked,'2026-10-27');assert.equal(a.status,'partial');assert.equal(a.architecture,'sterniiReferences');assert.equal(a.shootProfile,profile);assert.equal(a.leaflets,3);assert.equal(a.leafShape,leaf);assert.equal(a.flowerShape,'sterniiPinkSepals');assert.equal(a.sources[a.basis.leafShape].url,c.source);assert.equal(a.sources[a.basis.flowerShape].url,c.source);assert.equal(a.sources[a.basis.stemColor].url,c.source);assert.ok(a.sources.every(x=>['catalog-entry','species'].includes(x.scope)));assert.equal(a.leafPattern,profile==='diamondDust'?'spots':undefined);if(profile==='neoGolden'){assert.match(a.sourceConflict,/30〜50cm.*1〜3月/);assert.ok(a.sources.some(s=>s.url==='https://www.engei.net/index.php/products/detail?id=135148'));}if(profile==='rockies')assert.ok(a.unconfirmed.some(n=>/Kaleidoscope The Rockies.*別/.test(n)));assert.ok(a.unconfirmed.some(n=>/同一株12か月実物照合0/.test(n)));for(let month=1;month<=12;month++){const v=seasonAt(c,month);assert.equal(v.bloom,[2,3,4,5].includes(month));assert.equal(v.shootScale,1);assert.equal(v.leafDensity,1);assert.equal(v.groundDormant,false);assert.ok(v.phase.includes(a.sourceConflict));}for(const color of c.colors)assert.ok(searchCatalog(CATALOG,{query:c.label,color}).some(([key])=>key===id));for(const color of['unknown','yellow','white','blue'])assert.ok(!searchCatalog(CATALOG,{query:c.label,color}).some(([key])=>key===id));}
});

