test('Sternii basic seed source keeps wider domestic spread separate from named cultivars and RHS size groups',()=>{
 const id='p-d72aa1609d01',c=CATALOG[id],a=c.appearance;assert.equal(c.form,'botanical');assert.deepEqual(c.height,[.2,.3]);assert.deepEqual(c.spread,[.4,.6]);assert.deepEqual(c.bloom,[2,3,4,5]);assert.equal(c.bloomKnown,false);assert.deepEqual(c.colors,['green','white','pink']);assert.equal(c.source,'https://item.rakuten.co.jp/ogis/100s/');assert.equal(c.sourceChecked,'2026-10-27');assert.equal(a.status,'partial');assert.equal(a.architecture,'sterniiReferences');assert.equal(a.shootProfile,'greenSeed');assert.equal(a.leaflets,3);assert.equal(a.habit,'clump');assert.equal(a.leafPattern,undefined);assert.ok(a.sources.every(x=>['catalog-entry','species'].includes(x.scope)));assert.equal(a.sources[a.basis.leaflets].url,'https://www.rhs.org.uk/plants/89850/helleborus-%C3%97-sternii/details');assert.equal(a.basis.flowerShape,1);assert.ok(a.unconfirmed.some(n=>/実生.*出現率/.test(n)));assert.ok(a.unconfirmed.some(n=>/主写真.*同一個体/.test(n)));assert.ok(a.unconfirmed.some(n=>/蜜腺数.*実測値ではありません/.test(n)));assert.ok(a.unconfirmed.some(n=>/茎が二年性.*自動寿命/.test(n)));assert.ok(a.unconfirmed.some(n=>/同一株12か月実物照合0/.test(n)));assert.ok(a.sourceConflict.includes('幅40〜60cm'));for(let month=1;month<=12;month++){const v=seasonAt(c,month);assert.equal(v.bloom,[2,3,4,5].includes(month));assert.equal(v.shootScale,1);assert.equal(v.leafDensity,1);assert.equal(v.groundDormant,false);assert.ok(v.phase.includes(a.sourceConflict));}for(const color of c.colors)assert.ok(searchCatalog(CATALOG,{query:c.label,color}).some(([key])=>key===id));for(const color of['unknown','yellow','blue','orange'])assert.ok(!searchCatalog(CATALOG,{query:c.label,color}).some(([key])=>key===id));
});

test('Sternii basic seed cauline three-leaflet assemblies remain attached to actual persistent stems within independent dimensions',()=>{
 const matrix=new Matrix4(),v=new Vector3(),distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),onSegment=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),len=d.reduce((n,x)=>n+x*x,0),t=len?Math.max(0,Math.min(1,d.reduce((n,x,i)=>n+x*(p[i]-a[i]),0)/len)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};let models=0,leafJoins=0,actualCaulineRoots=0;
 for(const[id,profile,pid]of[['p-d72aa1609d01','greenSeed',86210]])for(const{dims,month,reference}of[...[[.25,.5,.16],[.03,.18,.012],[.25,.5,.005],[.005,.08,.005],[.25,.005,.005]].flatMap(dims=>[3,12].map(month=>({dims,month,reference:false}))),{dims:[.25,.5,.16],month:3,reference:true}]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},copy=structuredClone(p),view={year:1,month,reference},s=stateAt(p,view),g=plantModel(p,view);models++;try{g.updateMatrixWorld(true);const leafRoots=[],ends=[],stemSegments=[],petioleStarts=[];let lo=Infinity,hi=-Infinity,diam=0,leafTop=0,stemTop=0;for(const m of g.children){const kind=m.userData.component,pos=m.geometry.attributes.position;assert.ok(pos.array.every(Number.isFinite)&&m.geometry.attributes.normal.array.every(Number.isFinite)&&m.instanceMatrix.array.every(Number.isFinite));for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);matrix.premultiply(m.matrixWorld);const point=y=>new Vector3(0,y,0).applyMatrix4(matrix).toArray();if(kind.startsWith('leaf-sternii-ref-'))leafRoots.push(point(0));if(['petiole-sternii-ref','leaf-axis-sternii-ref'].includes(kind))ends.push(point(.5));if(kind==='petiole-sternii-ref')petioleStarts.push(point(-.5));if(kind==='stem-sternii-ref')stemSegments.push([point(-.5),point(.5)]);for(let j=0;j<pos.count;j++){v.fromBufferAttribute(pos,j).applyMatrix4(matrix);lo=Math.min(lo,v.y);hi=Math.max(hi,v.y);diam=Math.max(diam,Math.hypot(v.x,v.z)*2);if(/^(leaf|petiole)/.test(kind))leafTop=Math.max(leafTop,v.y);if(kind==='stem-sternii-ref')stemTop=Math.max(stemTop,v.y);}}}assert.ok(lo>=-1e-7&&hi<=s.height+1e-7,id+' height '+dims+' '+lo+' '+hi);assert.ok(diam<=s.spread+1e-7,id+' width '+dims+' '+diam);assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+1e-7,id+' leaf cap '+dims+' '+leafTop);assert.equal(leafRoots.length,27);assert.ok(stemTop>s.height*.55,'persistent stem not collapsed to independent leaf cap');for(const at of leafRoots){assert.ok(ends.some(end=>distance(at,end)<1e-7));leafJoins++;}for(const at of petioleStarts)if(stemSegments.some(([a,b])=>onSegment(at,a,b)<1e-7))actualCaulineRoots++;assert.ok(petioleStarts.every(at=>at[1]>0),'no basal leaf origins');assert.equal(g.children.some(m=>m.userData.component==='sepal-sternii-ref-'+profile),s.bloom);assert.equal(!!g.userData.flowerTargets?.length,s.bloom);assert.ok(!g.children.some(m=>/^(fruit|seed|carpel)-/.test(m.userData.component)));assert.deepEqual(p,copy);}finally{dispose(g);}}
 assert.ok(actualCaulineRoots>=models*9);console.log('STERNII_BASIC_ACTUAL_BOUNDARIES '+JSON.stringify({models,leafJoins,actualCaulineRoots}));
});
test('Sternii basic seed flower cameras hit actual indexed sepals at two aspects and preserve old saved source identities and dimensions',()=>{
 for(const[id,profile,pid]of[['p-d72aa1609d01','greenSeed',86210]])for(const dims of [[.25,.5,.16],[.03,.18,.012],[.25,.5,.005]]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{year:1,month:3,reference:false});try{assert.ok(g.userData.surfaceSelection?.matched,id+' '+dims);const surface=g.userData.flowerTargets[0].surface;assert.equal(surface.component,'sepal-sternii-ref-'+profile);g.position.set(-2,.012,-1);g.updateMatrixWorld(true);for(const aspect of [.8,1.65]){const pose=flowerInspectionView(g,aspect,40),camera=new PerspectiveCamera(40,aspect,.01,650);camera.position.fromArray(pose.position);camera.lookAt(...pose.target);camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.equal(hit?.object.userData.component,surface.component);assert.equal(hit.instanceId,surface.instanceId);assert.equal(hit.faceIndex,surface.faceIndex);assert.ok(hit.point.distanceTo(new Vector3(...pose.target))<2e-6);}}finally{dispose(g);}const d=emptyDocument(10,6);d.plans.A.plants=[p];d.view={year:1,month:3,reference:false,footprints:false,camera:{position:[-1.5,.8,-.5],target:[-3,.3,-1]}};const old={...structuredClone(d),catalogVersion:'2026-10-27.76'},copy=structuredClone(old);assert.deepEqual(validateDocument(old),d);assert.deepEqual(old,copy);}
});
