test('Foetidus connected seven leaflet fans and bracts remain on actual persistent stems within independent dimensions',()=>{
 const matrix=new Matrix4(),v=new Vector3(),distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),onSegment=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),len=d.reduce((n,x)=>n+x*x,0),t=len?Math.max(0,Math.min(1,d.reduce((n,x,i)=>n+x*(p[i]-a[i]),0)/len)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};let models=0,leafJoins=0,actualCaulineRoots=0,bractJoins=0;
 for(const[id,profile,pid]of[['p-e1bfc47d8dd4','basic',86310],['p-edf46b17d09a','goldBullion',86311]])for(const{dims,month,reference}of[...[[.6,.55,.4],[.03,.18,.012],[.6,.55,.005],[.005,.08,.005],[.6,.005,.005]].flatMap(dims=>[3,12].map(month=>({dims,month,reference:false}))),{dims:[.6,.55,.4],month:3,reference:true}]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},copy=structuredClone(p),view={year:1,month,reference},s=stateAt(p,view),g=plantModel(p,view);models++;try{g.updateMatrixWorld(true);const leafRoots=[],ends=[],stemSegments=[],branchSegments=[],petioleStarts=[],bracts=[];let lo=Infinity,hi=-Infinity,diam=0,leafTop=0,stemTop=0;for(const m of g.children){const kind=m.userData.component,pos=m.geometry.attributes.position;assert.ok(pos.array.every(Number.isFinite)&&m.geometry.attributes.normal.array.every(Number.isFinite)&&m.instanceMatrix.array.every(Number.isFinite));for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);matrix.premultiply(m.matrixWorld);const point=y=>new Vector3(0,y,0).applyMatrix4(matrix).toArray();if(kind.startsWith('leaf-foetidus-ref-'))leafRoots.push(point(0));if(kind==='petiole-foetidus-ref')ends.push(point(.5));if(kind==='petiole-foetidus-ref'&&i%10===0)petioleStarts.push(point(-.5));if(kind==='stem-foetidus-ref')stemSegments.push([point(-.5),point(.5)]);if(kind==='branch-foetidus-ref')branchSegments.push([point(-.5),point(.5)]);if(kind.startsWith('bract-foetidus-ref-'))bracts.push(point(0));for(let j=0;j<pos.count;j++){v.fromBufferAttribute(pos,j).applyMatrix4(matrix);lo=Math.min(lo,v.y);hi=Math.max(hi,v.y);diam=Math.max(diam,Math.hypot(v.x,v.z)*2);if(/^(leaf|petiole|bract)/.test(kind))leafTop=Math.max(leafTop,v.y);if(kind==='stem-foetidus-ref')stemTop=Math.max(stemTop,v.y);}}}assert.ok(lo>=-1e-7&&hi<=s.height+1e-7,id+' height '+dims+' '+lo+' '+hi);assert.ok(diam<=s.spread+1e-7,id+' width '+dims+' '+diam);assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+1e-7,id+' leaf and bract cap '+dims+' '+leafTop);assert.equal(leafRoots.length,105);assert.ok(stemTop>s.height*.50,'persistent stem not collapsed to independent leaf cap');for(const at of leafRoots){assert.ok(ends.some(end=>distance(at,end)<1e-7));leafJoins++;}for(const at of petioleStarts)if(stemSegments.some(([a,b])=>onSegment(at,a,b)<1e-7))actualCaulineRoots++;assert.equal(petioleStarts.length,15);for(const at of bracts){assert.ok([...stemSegments,...branchSegments].some(([a,b])=>onSegment(at,a,b)<1e-7));bractJoins++;}assert.equal(bracts.length,s.bloom?75:0);assert.equal(g.children.some(m=>m.userData.component==='sepal-foetidus-ref-'+profile),s.bloom);assert.equal(!!g.userData.flowerTargets?.length,s.bloom);const count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);assert.equal(count('sepal-foetidus-ref-'+profile),s.bloom?250:0);assert.equal(count('carpel-foetidus-ref'),s.bloom?150:0);assert.equal(count('anther-foetidus-ref'),s.bloom?1200:0);assert.ok(!g.children.some(m=>/^(fruit|seed)-/.test(m.userData.component)));assert.deepEqual(p,copy);}finally{dispose(g);}}
 assert.equal(actualCaulineRoots,models*15);console.log('FOETIDUS_ACTUAL_BOUNDARIES '+JSON.stringify({models,leafJoins,actualCaulineRoots,bractJoins}));
});
