test('Lemonnierae connected pedate foliage stays within actual plant dimensions and independent leaf caps',()=>{
 const matrix=new Matrix4(),v=new Vector3(),distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),onSegment=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),len=d.reduce((n,x)=>n+x*x,0),t=len?Math.max(0,Math.min(1,d.reduce((n,x,i)=>n+x*(p[i]-a[i]),0)/len)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};let models=0,leafJoins=0,petioleRoots=0;
 for(const[id,profile,pid,normal]of[['p-c06bfafb6048','sensas',86610,[.2,.35,.13]],['p-93a3228c383c','sifra',86611,[.25,.35,.16]],['p-a42f2ca37463','madam',86612,[.375,.5,.24]]])for(const{dims,month,reference}of[...[normal,[.03,.18,.012],[normal[0],normal[1],.005],[.005,.08,.005],[normal[0],.005,.005]].flatMap(dims=>[3,9].map(month=>({dims,month,reference:false}))),{dims:normal,month:3,reference:true}]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},copy=structuredClone(p),view={year:1,month,reference},s=stateAt(p,view),g=plantModel(p,view);models++;try{assert.deepEqual(p,copy);assert.equal(s.groundDormant,false);assert.equal(g.userData.architecture,'lemonnieraeReferences');g.updateMatrixWorld(true);const roots=[],ends=[],stemSegments=[],starts=[];let lo=Infinity,hi=-Infinity,diam=0,leafTop=0;for(const m of g.children){const kind=m.userData.component,pos=m.geometry.attributes.position;assert.ok(pos.array.every(Number.isFinite)&&m.geometry.attributes.normal.array.every(Number.isFinite)&&m.instanceMatrix.array.every(Number.isFinite));for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);matrix.premultiply(m.matrixWorld);const point=y=>new Vector3(0,y,0).applyMatrix4(matrix).toArray();if(kind.startsWith('leaf-lemonnierae-ref-'))roots.push(point(0));if(['petiole-lemonnierae-ref','leaf-axis-lemonnierae-ref'].includes(kind))ends.push(point(.5));if(kind==='petiole-lemonnierae-ref'&&i%10===0)starts.push(point(-.5));if(kind==='stem-lemonnierae-ref')stemSegments.push([point(-.5),point(.5)]);for(let j=0;j<pos.count;j++){v.fromBufferAttribute(pos,j).applyMatrix4(matrix);lo=Math.min(lo,v.y);hi=Math.max(hi,v.y);diam=Math.max(diam,Math.hypot(v.x,v.z)*2);if(/^(leaf|petiole)/.test(kind))leafTop=Math.max(leafTop,v.y);}}}assert.ok(lo>=-1e-7&&hi<=s.height+1e-7,'height '+dims+' '+month+' '+lo+' '+hi);assert.ok(diam<=s.spread+1e-7,'width '+dims+' '+diam);assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+1e-7,'leaf cap '+dims+' '+leafTop);assert.equal(roots.length,54);for(const at of roots){assert.ok(ends.some(end=>distance(at,end)<1e-7));leafJoins++;}assert.equal(starts.length,10);assert.ok(starts.slice(0,6).every(at=>at[1]>=0&&at[1]<s.height*.03));for(const at of starts.slice(6)){assert.ok(stemSegments.some(([a,b])=>onSegment(at,a,b)<1e-7));petioleRoots++;}const count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);assert.equal(count('leaf-lemonnierae-ref-'+profile+'-basal'),42);assert.equal(count('leaf-lemonnierae-ref-'+profile+'-cauline'),12);assert.equal(count('sepal-lemonnierae-ref-'+profile),s.bloom?40:0);assert.equal(count('nectary-lemonnierae-ref'),s.bloom?64:0);assert.equal(count('carpel-lemonnierae-ref'),s.bloom?24:0);assert.equal(count('anther-lemonnierae-ref'),s.bloom?320:0);assert.ok(!g.children.some(m=>/^(fruit|seed|root)-/.test(m.userData.component)));assert.equal(!!g.userData.flowerTargets?.length,s.bloom);}finally{dispose(g);}}
 assert.equal(models,33);assert.equal(leafJoins,1782);assert.equal(petioleRoots,132);console.log('LEMONNIERAE_ACTUAL_BOUNDARIES '+JSON.stringify({models,leafJoins,petioleRoots}));
});
test('Lemonnierae flower inspection hits each cultivar indexed sepal and preserves previous catalog saves',()=>{
 for(const[id,profile,pid,normal]of[['p-c06bfafb6048','sensas',86610,[.2,.35,.13]],['p-93a3228c383c','sifra',86611,[.25,.35,.16]],['p-a42f2ca37463','madam',86612,[.375,.5,.24]]])for(const dims of[normal,[.03,.18,.012],[normal[0],normal[1],.005]])for(const month of[3]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{year:1,month,reference:false});try{assert.ok(g.userData.surfaceSelection?.matched,'matched '+dims+' '+month);const surface=g.userData.flowerTargets[0].surface;assert.equal(surface.component,'sepal-lemonnierae-ref-'+profile);g.position.set(-2,.012,-1);g.updateMatrixWorld(true);for(const aspect of[.8,1.65]){const pose=flowerInspectionView(g,aspect,40),camera=new PerspectiveCamera(40,aspect,.01,650);camera.position.fromArray(pose.position);camera.lookAt(...pose.target);camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.equal(hit?.object.userData.component,surface.component);assert.equal(hit.instanceId,surface.instanceId);assert.equal(hit.faceIndex,surface.faceIndex);assert.ok(hit.point.distanceTo(new Vector3(...pose.target))<2e-6);}}finally{dispose(g);}const d=emptyDocument(10,6);d.plans.A.plants=[p];d.view={year:1,month,reference:false,footprints:false,camera:{position:[-1.5,.8,-.5],target:[-3,.3,-1]}};const old={...structuredClone(d),catalogVersion:'2026-10-27.80'},copy=structuredClone(old);assert.deepEqual(validateDocument(old),d);assert.deepEqual(old,copy);}
});
test('Lemonnierae cultivar leaf and sepal surfaces preserve foliage when flowers are removed',()=>{
 for(const[id,profile,pid,normal]of[['p-c06bfafb6048','sensas',86610,[.2,.35,.13]],['p-93a3228c383c','sifra',86611,[.25,.35,.16]],['p-a42f2ca37463','madam',86612,[.375,.5,.24]]])for(const dims of[normal,[.03,.18,.012]]){let expected=null;for(const month of[3,9]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{year:1,month,reference:false});try{const leaves=g.children.filter(m=>m.userData.component.startsWith('leaf-lemonnierae-ref-')),values=leaves.map(m=>[m.userData.component,Buffer.from(m.instanceMatrix.array.buffer,m.instanceMatrix.array.byteOffset,m.count*64).toString('hex'),Buffer.from(m.instanceColor.array.buffer,m.instanceColor.array.byteOffset,m.count*12).toString('hex')]);if(expected)assert.deepEqual(values,expected);else expected=values;for(const m of leaves){assert.equal(m.geometry.userData.lemonnieraeOrgan,'gcLemonnieraeBladeRef');assert.ok(m.geometry.attributes.normal.getY(16*21+10)>.5);const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/gl_FrontFacing/);assert.ok(!/undefined|NaN/.test(shader.fragmentShader));}const sepals=g.children.find(m=>m.userData.component==='sepal-lemonnierae-ref-'+profile);assert.equal(!!sepals,month===3);if(sepals){assert.equal(sepals.geometry.userData.lemonnieraeOrgan,'gcLemonnierae'+(profile==='madam'?'Madam':profile==='sifra'?'Sifra':'Sensas')+'SepalRef');const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};sepals.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/lemonnieraeVein/);assert.ok(!/undefined|NaN/.test(shader.fragmentShader));}}finally{dispose(g);}}}
});

test('Paradenia source-qualified white multiflower reference retains domestic size season and nursery limits',()=>{
 const id='p-5623aac732c5',c=CATALOG[id],a=c.appearance;assert.equal(c.form,'botanical');assert.deepEqual(c.height,[.25,.5]);assert.deepEqual(c.spread,[.3,.5]);assert.equal(c.bloomKnown,false);assert.deepEqual(c.colors,['white']);assert.equal(c.source,'https://item.rakuten.co.jp/ogis/100pd/');assert.equal(c.sourceChecked,'2026-10-27');assert.equal(a.architecture,'lemonnieraeReferences');assert.equal(a.shootProfile,'paradenia');assert.equal(a.status,'partial');assert.equal(a.persistence,'evergreen');assert.equal(a.leaflets,undefined);assert.equal(a.sources[a.basis.leafShape].scope,'genus');assert.ok(a.sourceConflict.includes('花径10cmは最大'));for(const pattern of[/5写真/,/最大花径10cmから下限/,/固定された小葉数/,/品種の実測計数値ではありません/,/1月下旬の温室苗/,/全国共通の固定月/,/実物照合0/])assert.ok(a.unconfirmed.some(x=>pattern.test(x)),String(pattern));for(let month=1;month<=12;month++){const v=seasonAt(c,month);assert.equal(v.bloom,[1,2,3,4,5,12].includes(month));assert.equal(v.groundDormant,false);assert.equal(v.shootScale,1);}for(const color of['white','pink','red','green','yellow','unknown'])assert.equal(searchCatalog(CATALOG,{query:c.label,color}).some(([k])=>k===id),color==='white');
});
