test('Glandorfensis next sources preserve Bianco current height and source-specific picotee and dark cups',()=>{
 const ids=['p-0f7c504c4c1a','p-ba9283c1664e','p-64d899a7bb29'],profiles=['picotee','bianco','brunello'];for(const[i,id]of ids.entries()){const c=CATALOG[id],a=c.appearance;assert.equal(c.form,'botanical');assert.deepEqual(c.height,[[.3,.5],[.5,.7],[.4,.6]][i]);assert.deepEqual(c.spread,i===0?[.3,.5]:[.4,.6]);assert.equal(c.bloomKnown,false);assert.deepEqual(c.colors,[['white','pink','red','green','mixed'],['white','pink','green','mixed'],['red','purple','mixed']][i]);assert.equal(c.source,'https://item.rakuten.co.jp/ogis/'+['100nc','100nb','100nn'][i]+'/');assert.equal(c.sourceChecked,'2026-10-27');assert.equal(a.architecture,'glandorfensisReferences');assert.equal(a.shootProfile,profiles[i]);assert.equal(a.status,'partial');assert.equal(a.persistence,'evergreen');assert.equal(a.leaflets,undefined);assert.equal(a.sources[0].scope,'catalog-entry');assert.equal(a.sources[1].scope,'genus');assert.equal(a.leafPattern,'glandorfensisPlainVeinedReference');assert.ok(a.sourceConflict.includes('最大花径'+[8,8,7][i]+'cm'));for(const pattern of[/小葉の固定数/,/計45小葉/,/品種の実測計数値/,/全国共通の開花月/,/実物照合0/,/固定月の変色/,/未確認の桃の新葉/])assert.ok(a.unconfirmed.some(x=>pattern.test(x)),id+' '+pattern);if(i===0)assert.match(a.sourceConflict,/黄色い別の花/);if(i===1){assert.match(a.sourceConflict,/旧登録の40〜70cm/);assert.match(a.unconfirmed[0],/裏の強めの桃/);}if(i===2)assert.match(a.sourceConflict,/販売スタッフの所感/);for(let month=1;month<=12;month++){const v=seasonAt(c,month);assert.equal(v.bloom,[1,2,3,4,5,12].includes(month));assert.equal(v.groundDormant,false);assert.equal(v.shootScale,1);}for(const color of['white','green','pink','red','purple','yellow','mixed','unknown'])assert.equal(searchCatalog(CATALOG,{query:c.label,color}).some(([k])=>k===id),c.colors.includes(color));}
});

test('Glandorfensis next connected pedate foliage stays within actual plant dimensions and independent leaf caps',()=>{
 const matrix=new Matrix4(),v=new Vector3(),distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),onSegment=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),len=d.reduce((n,x)=>n+x*x,0),t=len?Math.max(0,Math.min(1,d.reduce((n,x,i)=>n+x*(p[i]-a[i]),0)/len)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};let models=0,leafJoins=0,petioleRoots=0;
 for(const[id,profile,pid,normal]of[['p-0f7c504c4c1a','picotee',87710,[.4,.4,.25]],['p-ba9283c1664e','bianco',87711,[.6,.5,.35]],['p-64d899a7bb29','brunello',87712,[.5,.5,.3]]])for(const{dims,month,reference}of[...[normal,[.03,.18,.012],[normal[0],normal[1],.005],[.005,.08,.005],[normal[0],.005,.005]].flatMap(dims=>[3,9].map(month=>({dims,month,reference:false}))),{dims:normal,month:3,reference:true}]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},copy=structuredClone(p),view={year:1,month,reference},s=stateAt(p,view),g=plantModel(p,view);models++;try{assert.deepEqual(p,copy);assert.equal(s.groundDormant,false);assert.equal(g.userData.architecture,'glandorfensisReferences');g.updateMatrixWorld(true);const roots=[],ends=[],stemSegments=[],starts=[];let lo=Infinity,hi=-Infinity,diam=0,leafTop=0;for(const m of g.children){const kind=m.userData.component,pos=m.geometry.attributes.position;assert.ok(pos.array.every(Number.isFinite)&&m.geometry.attributes.normal.array.every(Number.isFinite)&&m.instanceMatrix.array.every(Number.isFinite));for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);matrix.premultiply(m.matrixWorld);const point=y=>new Vector3(0,y,0).applyMatrix4(matrix).toArray();if(kind.startsWith('leaf-glandorfensis-ref-'))roots.push(point(0));if(['petiole-glandorfensis-ref','leaf-axis-glandorfensis-ref'].includes(kind))ends.push(point(.5));if(kind==='petiole-glandorfensis-ref'&&i%10===0)starts.push(point(-.5));if(kind==='stem-glandorfensis-ref')stemSegments.push([point(-.5),point(.5)]);for(let j=0;j<pos.count;j++){v.fromBufferAttribute(pos,j).applyMatrix4(matrix);lo=Math.min(lo,v.y);hi=Math.max(hi,v.y);diam=Math.max(diam,Math.hypot(v.x,v.z)*2);if(/^(leaf|petiole)/.test(kind))leafTop=Math.max(leafTop,v.y);}}}assert.ok(lo>=-1e-7&&hi<=s.height+1e-7,'height '+dims+' '+month+' '+lo+' '+hi);assert.ok(diam<=s.spread+1e-7,'width '+dims+' '+diam);assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+1e-7,'leaf cap '+dims+' '+leafTop);assert.equal(roots.length,45);for(const at of roots){assert.ok(ends.some(end=>distance(at,end)<1e-7));leafJoins++;}assert.equal(starts.length,11);assert.ok(starts.slice(0,6).every(at=>at[1]>=0&&at[1]<s.height*.03));for(const at of starts.slice(6)){assert.ok(stemSegments.some(([a,b])=>onSegment(at,a,b)<1e-7));petioleRoots++;}const count=k=>g.children.filter(m=>m.userData.component===k||(k.startsWith('leaf-glandorfensis-ref-')&&m.userData.component.startsWith(k+'-'))).reduce((n,m)=>n+m.count,0);assert.equal(count('leaf-glandorfensis-ref-'+profile+'-basal'),30);assert.equal(count('leaf-glandorfensis-ref-'+profile+'-cauline'),15);assert.equal(count('sepal-glandorfensis-ref-'+profile),s.bloom?75:0);assert.equal(count('nectary-glandorfensis-ref'),s.bloom?120:0);assert.equal(count('carpel-glandorfensis-ref'),s.bloom?45:0);assert.equal(count('anther-glandorfensis-ref'),s.bloom?600:0);assert.ok(!g.children.some(m=>/^(fruit|seed|root)-/.test(m.userData.component)));assert.equal(!!g.userData.flowerTargets?.length,s.bloom);}finally{dispose(g);}}
 assert.equal(models,33);assert.equal(leafJoins,1485);assert.equal(petioleRoots,165);console.log('GLANDORFENSIS_NEXT_ACTUAL_BOUNDARIES '+JSON.stringify({models,leafJoins,petioleRoots}));
});
test('Glandorfensis next flower inspection hits each cultivar indexed sepal and preserves previous catalog saves',()=>{
 for(const[id,profile,pid,normal]of[['p-0f7c504c4c1a','picotee',87710,[.4,.4,.25]],['p-ba9283c1664e','bianco',87711,[.6,.5,.35]],['p-64d899a7bb29','brunello',87712,[.5,.5,.3]]])for(const dims of[normal,[.03,.18,.012],[normal[0],normal[1],.005]])for(const month of[3]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{year:1,month,reference:false});try{assert.ok(g.userData.surfaceSelection?.matched,'matched '+dims+' '+month);const surface=g.userData.flowerTargets[0].surface;assert.equal(surface.component,'sepal-glandorfensis-ref-'+profile);g.position.set(-2,.012,-1);g.updateMatrixWorld(true);for(const aspect of[.8,1.65]){const pose=flowerInspectionView(g,aspect,40),camera=new PerspectiveCamera(40,aspect,.01,650);camera.position.fromArray(pose.position);camera.lookAt(...pose.target);camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.equal(hit?.object.userData.component,surface.component);assert.equal(hit.instanceId,surface.instanceId);assert.equal(hit.faceIndex,surface.faceIndex);assert.ok(hit.point.distanceTo(new Vector3(...pose.target))<2e-6);}}finally{dispose(g);}const d=emptyDocument(10,6);d.plans.A.plants=[p];d.view={year:1,month,reference:false,footprints:false,camera:{position:[-1.5,.8,-.5],target:[-3,.3,-1]}};const old={...structuredClone(d),catalogVersion:'2026-10-27.91'},copy=structuredClone(old);assert.deepEqual(validateDocument(old),d);assert.deepEqual(old,copy);}
});
test('Glandorfensis next cultivar leaf and sepal surfaces preserve foliage when flowers are removed',()=>{
 for(const[id,profile,pid,normal]of[['p-0f7c504c4c1a','picotee',87710,[.4,.4,.25]],['p-ba9283c1664e','bianco',87711,[.6,.5,.35]],['p-64d899a7bb29','brunello',87712,[.5,.5,.3]]])for(const dims of[normal,[.03,.18,.012]]){let expected=null;for(const month of[3,9]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{year:1,month,reference:false});try{const leaves=g.children.filter(m=>m.userData.component.startsWith('leaf-glandorfensis-ref-')),values=leaves.map(m=>[m.userData.component,Buffer.from(m.instanceMatrix.array.buffer,m.instanceMatrix.array.byteOffset,m.count*64).toString('hex'),Buffer.from(m.instanceColor.array.buffer,m.instanceColor.array.byteOffset,m.count*12).toString('hex')]);if(expected)assert.deepEqual(values,expected);else expected=values;for(const m of leaves){assert.equal(m.geometry.userData.glandorfensisOrgan,profile==='picotee'?'gcGlandorfensisRoundBladeRef':profile==='bianco'?'gcGlandorfensisSerratedBladeRef':'gcGlandorfensisBladeRef');assert.ok(m.geometry.attributes.normal.getY(16*21+10)>.5);const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/gl_FrontFacing/);assert.ok(!shader.fragmentShader.includes('frostkissVein'));assert.ok(!/undefined|NaN/.test(shader.fragmentShader));}assert.equal(leaves.filter(m=>m.userData.component.endsWith('-young')).reduce((n,m)=>n+m.count,0),0);const sepals=g.children.find(m=>m.userData.component==='sepal-glandorfensis-ref-'+profile);assert.equal(!!sepals,month===3);if(sepals){assert.equal(sepals.geometry.userData.glandorfensisOrgan,profile==='picotee'?'gcGlandorfensisPicoteeSepalRef':profile==='bianco'?'gcGlandorfensisBiancoSepalRef':'gcGlandorfensisBrunelloSepalRef');const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};sepals.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/iceRoseCentre/);assert.equal(shader.fragmentShader.includes('iceBrightPicotee'),profile==='picotee');assert.equal(shader.fragmentShader.includes('icePicoteeVeins'),profile==='picotee');assert.ok(shader.fragmentShader.includes('iceRoseBack'));assert.ok(!/undefined|NaN/.test(shader.fragmentShader));}}finally{dispose(g);}}}
});

