test('Lividus Coral cauline three-leaflet assemblies remain attached to actual persistent stems within independent dimensions',()=>{
 const matrix=new Matrix4(),v=new Vector3(),distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),onSegment=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),len=d.reduce((n,x)=>n+x*x,0),t=len?Math.max(0,Math.min(1,d.reduce((n,x,i)=>n+x*(p[i]-a[i]),0)/len)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};let models=0,leafJoins=0,actualCaulineRoots=0;
 for(const[id,profile]of[['p-a7214f3d68a8','coral']])for(const{dims,month,reference}of[...[[.25,.25,.16],[.03,.18,.012],[.25,.25,.005],[.005,.08,.005],[.25,.005,.005]].flatMap(dims=>[3,9].map(month=>({dims,month,reference:false}))),{dims:[.25,.25,.16],month:3,reference:true}]){const p={...makePlant(id,88310,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},copy=structuredClone(p),view={year:1,month,reference},s=stateAt(p,view),g=plantModel(p,view);models++;try{g.updateMatrixWorld(true);const leafRoots=[],ends=[],stemSegments=[],petioleStarts=[];let lo=Infinity,hi=-Infinity,diam=0,leafTop=0,stemTop=0;for(const m of g.children){const kind=m.userData.component,pos=m.geometry.attributes.position;assert.ok(pos.array.every(Number.isFinite)&&m.geometry.attributes.normal.array.every(Number.isFinite)&&m.instanceMatrix.array.every(Number.isFinite));for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);matrix.premultiply(m.matrixWorld);const point=y=>new Vector3(0,y,0).applyMatrix4(matrix).toArray();if(kind.startsWith('leaf-lividus-ref-'))leafRoots.push(point(0));if(['petiole-lividus-ref','leaf-axis-lividus-ref'].includes(kind))ends.push(point(.5));if(kind==='petiole-lividus-ref')petioleStarts.push(point(-.5));if(kind==='stem-lividus-ref')stemSegments.push([point(-.5),point(.5)]);for(let j=0;j<pos.count;j++){v.fromBufferAttribute(pos,j).applyMatrix4(matrix);lo=Math.min(lo,v.y);hi=Math.max(hi,v.y);diam=Math.max(diam,Math.hypot(v.x,v.z)*2);if(/^(leaf|petiole)/.test(kind))leafTop=Math.max(leafTop,v.y);if(kind==='stem-lividus-ref')stemTop=Math.max(stemTop,v.y);}}}assert.ok(lo>=-1e-7&&hi<=s.height+1e-7,id+' height '+dims+' '+lo+' '+hi);assert.ok(diam<=s.spread+1e-7,id+' width '+dims+' '+diam);assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+1e-7,id+' leaf cap '+dims+' '+leafTop);assert.equal(leafRoots.length,18);assert.ok(stemTop>s.height*.55,'persistent stem not collapsed to independent leaf cap');for(const at of leafRoots){assert.ok(ends.some(end=>distance(at,end)<1e-7));leafJoins++;}for(const at of petioleStarts)if(stemSegments.some(([a,b])=>onSegment(at,a,b)<1e-7))actualCaulineRoots++;assert.ok(petioleStarts.every(at=>at[1]>0),'no basal leaf origins');assert.equal(g.children.some(m=>m.userData.component==='sepal-lividus-ref-'+profile),s.bloom);assert.equal(!!g.userData.flowerTargets?.length,s.bloom);assert.ok(!g.children.some(m=>/^(fruit|seed|carpel)-/.test(m.userData.component)));assert.deepEqual(p,copy);}finally{dispose(g);}}
 assert.equal(models,11);assert.equal(leafJoins,198);assert.ok(actualCaulineRoots>=models*6);console.log('LIVIDUS_CORAL_ACTUAL_BOUNDARIES '+JSON.stringify({models,leafJoins,actualCaulineRoots}));
});
test('Lividus Coral flower cameras hit actual indexed sepals at two aspects and preserve old saved source identities and dimensions',()=>{
 for(const[id,profile]of[['p-a7214f3d68a8','coral']])for(const dims of [[.25,.25,.16],[.03,.18,.012],[.25,.25,.005]]){const p={...makePlant(id,88310,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{year:1,month:3,reference:false});try{assert.ok(g.userData.surfaceSelection?.matched,id+' '+dims);const surface=g.userData.flowerTargets[0].surface;assert.equal(surface.component,'sepal-lividus-ref-'+profile);g.position.set(-2,.012,-1);g.updateMatrixWorld(true);for(const aspect of [.8,1.65]){const pose=flowerInspectionView(g,aspect,40),camera=new PerspectiveCamera(40,aspect,.01,650);camera.position.fromArray(pose.position);camera.lookAt(...pose.target);camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.equal(hit?.object.userData.component,surface.component);assert.equal(hit.instanceId,surface.instanceId);assert.equal(hit.faceIndex,surface.faceIndex);assert.ok(hit.point.distanceTo(new Vector3(...pose.target))<2e-6);}}finally{dispose(g);}const d=emptyDocument(10,6);d.plans.A.plants=[p];d.view={year:1,month:3,reference:false,footprints:false,camera:{position:[-1.5,.8,-.5],target:[-3,.3,-1]}};const old={...structuredClone(d),catalogVersion:'2026-10-27.97'},copy=structuredClone(old);assert.deepEqual(validateDocument(old),d);assert.deepEqual(old,copy);}
});
test('Lividus Coral surface winding assigns silver upper networks and pale purple lower faces without painting both sides alike',()=>{
 for(const[id,profile]of[['p-a7214f3d68a8','coral']]){const g=plantModel(makePlant(id,88310,3,3),view(3));try{const leaves=g.children.filter(m=>m.userData.component.startsWith('leaf-lividus-ref-'));assert.ok(leaves.length);for(const m of leaves){const normal=m.geometry.attributes.normal;assert.ok(normal.getY(16*21+10)>.5);assert.match(m.geometry.userData.lividusOrgan,/^gcLividus(Central|Left|Right)Ref$/);const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/if\(gl_FrontFacing\)/);assert.match(shader.fragmentShader,/gcLividusWeb/);assert.equal(shader.fragmentShader.includes('gcLividusPatchNoise'),profile!=='green');if(profile!=='green'){const declaration=shader.fragmentShader.indexOf('vec2 gcLividusHash(vec2 p);');assert.ok(declaration>=0&&declaration<shader.fragmentShader.indexOf('float gcLividusPatchNoise'));}assert.ok(!shader.fragmentShader.includes('NaN'));assert.ok(!shader.fragmentShader.includes('undefined'));}const sepals=g.children.find(m=>m.userData.component==='sepal-lividus-ref-'+profile);assert.equal(sepals.geometry.userData.lividusOrgan,'gcLividusSepalRef');const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};sepals.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/gl_FrontFacing/);assert.match(shader.fragmentShader,/lvCoralMosaic/);assert.ok(shader.fragmentShader.indexOf('float gcCoralHash')<shader.fragmentShader.indexOf('float gcCoralNoise'));}finally{dispose(g);}}
});

test('Argutifolius Snow Fever source keeps dense white and pink leaf ages apart from white-green flowers',()=>{
 const id='p-02566855a4d1',c=CATALOG[id],a=c.appearance;assert.equal(c.form,'botanical');assert.equal(c.leaf,'semi');assert.deepEqual(c.height,[.25,.5]);assert.deepEqual(c.spread,[.4,.6]);assert.equal(c.bloomKnown,false);assert.deepEqual(c.bloom,[2,3,4,5]);assert.deepEqual(c.colors,['white','green']);assert.equal(c.source,'https://item.rakuten.co.jp/ogis/100cf/');assert.equal(c.sourceChecked,'2026-10-27');assert.equal(a.status,'partial');assert.equal(a.architecture,'argutifoliusReferences');assert.equal(a.shootProfile,'snowFever');assert.equal(a.leaflets,3);assert.equal(a.leafPattern,'argutifoliusSnowWhitePinkReference');assert.match(a.sources[a.basis.leafShape].url,/rhs.org/);assert.match(a.sourceConflict,/旧登録の30〜50cmから高さの下限を訂正/);assert.match(a.sourceConflict,/葉色を桃色の花の検索へ転用していません/);for(const pattern of[/同一株の年間実物照合0/,/計27小葉/,/上側9小葉/,/品種の実測値ではありません/,/同じ株の時系列へ変換していません/,/固定月や気温から予測せず/])assert.ok(a.unconfirmed.some(n=>pattern.test(n)),String(pattern));for(let month=1;month<=12;month++){const v=seasonAt(c,month);assert.equal(v.bloom,[2,3,4,5].includes(month));assert.equal(v.shootScale,1);assert.equal(v.leafDensity,1);assert.equal(v.groundDormant,false);}for(const color of['green','pink','white','yellow','red','mixed','unknown'])assert.equal(searchCatalog(CATALOG,{query:c.label,color}).some(([key])=>key===id),c.colors.includes(color));
});

test('Argutifolius Snow Fever cauline three-leaflet assemblies remain attached to actual persistent stems within independent dimensions',()=>{
 const matrix=new Matrix4(),v=new Vector3(),distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),onSegment=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),len=d.reduce((n,x)=>n+x*x,0),t=len?Math.max(0,Math.min(1,d.reduce((n,x,i)=>n+x*(p[i]-a[i]),0)/len)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};let models=0,leafJoins=0,actualCaulineRoots=0;
 for(const id of ['p-02566855a4d1'])for(const{dims,month,reference}of[...[[.375,.5,.24],[.03,.18,.012],[.375,.5,.005],[.005,.08,.005],[.375,.005,.005]].flatMap(dims=>[3,9].map(month=>({dims,month,reference:false}))),{dims:[.375,.5,.24],month:3,reference:true}]){const p={...makePlant(id,88410,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},copy=structuredClone(p),view={year:1,month,reference},s=stateAt(p,view),g=plantModel(p,view);models++;try{g.updateMatrixWorld(true);const leafRoots=[],ends=[],stemSegments=[],petioleStarts=[];let lo=Infinity,hi=-Infinity,diam=0,leafTop=0,stemTop=0,upperStemRadius=0;for(const m of g.children){const kind=m.userData.component,pos=m.geometry.attributes.position;assert.ok(pos.array.every(Number.isFinite)&&m.geometry.attributes.normal.array.every(Number.isFinite)&&m.instanceMatrix.array.every(Number.isFinite));for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);matrix.premultiply(m.matrixWorld);const point=y=>new Vector3(0,y,0).applyMatrix4(matrix).toArray();if(kind.startsWith('leaf-argutifolius-ref-'))leafRoots.push(point(0));if(['petiole-argutifolius-ref','leaf-axis-argutifolius-ref'].includes(kind))ends.push(point(.5));if(kind==='petiole-argutifolius-ref')petioleStarts.push(point(-.5));if(kind==='stem-argutifolius-ref'){stemSegments.push([point(-.5),point(.5)]);upperStemRadius=Math.max(upperStemRadius,Math.hypot(matrix.elements[0],matrix.elements[1],matrix.elements[2]));}for(let j=0;j<pos.count;j++){v.fromBufferAttribute(pos,j).applyMatrix4(matrix);lo=Math.min(lo,v.y);hi=Math.max(hi,v.y);diam=Math.max(diam,Math.hypot(v.x,v.z)*2);if(/^(leaf|petiole)/.test(kind))leafTop=Math.max(leafTop,v.y);if(kind==='stem-argutifolius-ref')stemTop=Math.max(stemTop,v.y);}}}assert.ok(lo>=-1e-7&&hi<=s.height+1e-7,id+' height '+dims+' '+lo+' '+hi);assert.ok(diam<=s.spread+1e-7,id+' width '+dims+' '+diam);assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+1e-7,id+' leaf cap '+dims+' '+leafTop);assert.equal(leafRoots.length,27);if(dims[2]===.005&&dims[0]>.1&&dims[1]>.1)assert.ok(upperStemRadius>=.0029,'upper stem retains radius under tiny leaf cap');assert.ok(stemTop>s.height*.55,'persistent stem not collapsed to independent leaf cap');for(const at of leafRoots){assert.ok(ends.some(end=>distance(at,end)<1e-7));leafJoins++;}for(const at of petioleStarts)if(stemSegments.some(([a,b])=>onSegment(at,a,b)<1e-7))actualCaulineRoots++;assert.ok(petioleStarts.every(at=>at[1]>0),'no basal leaf origins');assert.equal(g.children.some(m=>m.userData.component==='sepal-argutifolius-ref-snowFever'),s.bloom);assert.equal(!!g.userData.flowerTargets?.length,s.bloom);assert.ok(!g.children.some(m=>/^(fruit|seed|carpel)-/.test(m.userData.component)));assert.deepEqual(p,copy);}finally{dispose(g);}}
 assert.equal(models,11);assert.equal(leafJoins,297);assert.ok(actualCaulineRoots>=models*9);console.log('ARGUTIFOLIUS_SNOW_FEVER_BOUNDARIES '+JSON.stringify({models,leafJoins,actualCaulineRoots}));
});
