test('Argutifolius Snow Fever mature and young pigment examples keep bounded colour streams and valid shader dependencies',()=>{
 let expected=null;for(const dims of[[.375,.5,.24],[.03,.18,.012]])for(const month of[3,9]){const p={...makePlant('p-02566855a4d1',88410,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{year:1,month,reference:false});try{const leaves=g.children.filter(m=>m.userData.component.startsWith('leaf-argutifolius-ref-snowFever-')),raw=a=>Buffer.from(a.buffer,a.byteOffset,a.byteLength).toString('hex'),colours=leaves.map(m=>[m.userData.component,raw(m.instanceColor.array)]);if(expected)assert.deepEqual(colours,expected);else expected=colours;assert.equal(leaves.filter(m=>m.userData.component.includes('-young-')).reduce((n,m)=>n+m.count,0),9);assert.equal(leaves.filter(m=>m.userData.component.includes('-mature-')).reduce((n,m)=>n+m.count,0),18);for(const m of leaves){assert.ok(m.geometry.attributes.normal.getY(16*21+10)>.5);const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/gl_FrontFacing/);assert.match(shader.fragmentShader,/gcSnowFeverNoise/);assert.ok(shader.fragmentShader.indexOf('float gcSnowFeverHash')<shader.fragmentShader.indexOf('float gcSnowFeverNoise'));assert.equal(shader.fragmentShader.includes('sfYoungPink'),m.userData.component.includes('-young-'));assert.ok(!/undefined|NaN/.test(shader.fragmentShader));}const sepals=g.children.find(m=>m.userData.component==='sepal-argutifolius-ref-snowFever');assert.equal(!!sepals,month===3);if(sepals){assert.equal(sepals.count,75);const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};sepals.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/sfCentre/);assert.ok(!shader.fragmentShader.includes('sfYoungPink'));}}finally{dispose(g);}}
});
test('Wild hellebore sources separate domestic species observations and conditional winter leaf loss',()=>{
 for(const[id,profile,height,spread,colors,sku]of[['p-78bb98fc81e6','odorus',[.25,.5],[.3,.5],['green','yellow'],'100gs'],['p-6017abe82931','atrorubens',[.25,.4],[.3,.4],['purple','red','green','mixed'],'100ga']]){const c=CATALOG[id],a=c.appearance;assert.equal(c.form,'botanical');assert.equal(c.leaf,'semi');assert.deepEqual(c.height,height);assert.deepEqual(c.spread,spread);assert.deepEqual(c.colors,colors);assert.equal(c.source,'https://item.rakuten.co.jp/ogis/'+sku+'/');assert.equal(c.sourceChecked,'2026-10-27');assert.equal(c.bloomKnown,false);assert.equal(a.status,'partial');assert.equal(a.architecture,'wildHelleboreReferences');assert.equal(a.shootProfile,profile);assert.equal(a.leaflets,undefined);assert.equal(a.sources[a.basis.leafShape].scope,'genus');assert.equal(a.sources[a.basis.flowerShape].scope,'catalog-entry');assert.ok(a.sources.every(s=>['catalog-entry','species','genus'].includes(s.scope)));for(const pattern of[/同一株の年間実物照合0/,/根生6群を各7小葉/,/花軸3本に各3花と1蕾/,/地上部全体の自然消失へ言い換えず/,/月別葉量を検証していません/])assert.ok(a.unconfirmed.some(n=>pattern.test(n)),String(pattern));assert.match(a.sourceConflict,profile==='odorus'?/秋冬に一部落葉/:/基本的に冬落葉・暖地では残葉/);for(let month=1;month<=12;month++){const s=seasonAt(c,month);assert.equal(s.bloom,[2,3,4,5].includes(month));assert.equal(s.leafDensity,profile==='atrorubens'&&[12,1].includes(month)?0:1);assert.equal(s.groundDormant,false);assert.equal(s.shootScale,1);}for(const color of['green','yellow','purple','red','pink','white','blue','mixed','unknown'])assert.equal(searchCatalog(CATALOG,{query:c.label,color}).some(([key])=>key===id),colors.includes(color));}
});
test('Wild hellebore basal and bract assemblies join real supports within independent plant dimensions including leafless winter',()=>{
 const matrix=new Matrix4(),v=new Vector3(),distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),onSegment=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),len=d.reduce((n,x)=>n+x*x,0),t=len?Math.max(0,Math.min(1,d.reduce((n,x,i)=>n+x*(p[i]-a[i]),0)/len)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};let models=0,leafJoins=0,caulineRoots=0,basalGroups=0;
 for(const[id,profile,pid,normal]of[['p-78bb98fc81e6','odorus',88510,[.375,.4,.24]],['p-6017abe82931','atrorubens',88511,[.325,.35,.21]]])for(const{dims,month,reference}of[...[normal,[.03,.18,.012],[normal[0],normal[1],.005],[.005,.08,.005],[normal[0],.005,.005]].flatMap(dims=>[3,9,1].map(month=>({dims,month,reference:false}))),{dims:normal,month:3,reference:true}]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},copy=structuredClone(p),view={year:1,month,reference},s=stateAt(p,view),g=plantModel(p,view);models++;try{g.updateMatrixWorld(true);const roots=[],ends=[],stemSegments=[],petioles=[];let lo=Infinity,hi=-Infinity,diam=0,leafTop=0;const counts={};for(const m of g.children){const kind=m.userData.component,pos=m.geometry.attributes.position;counts[kind]=(counts[kind]||0)+m.count;assert.ok(pos.array.every(Number.isFinite)&&m.geometry.attributes.normal.array.every(Number.isFinite)&&m.instanceMatrix.array.every(Number.isFinite));for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);matrix.premultiply(m.matrixWorld);const point=y=>new Vector3(0,y,0).applyMatrix4(matrix).toArray();if(kind.startsWith('leaf-wild-hellebore-ref-'))roots.push(point(0));if(['petiole-wild-hellebore-ref','leaf-axis-wild-hellebore-ref'].includes(kind))ends.push(point(.5));if(kind==='petiole-wild-hellebore-ref')petioles.push([point(-.5),point(.5)]);if(kind==='stem-wild-hellebore-ref')stemSegments.push([point(-.5),point(.5)]);for(let j=0;j<pos.count;j++){v.fromBufferAttribute(pos,j).applyMatrix4(matrix);lo=Math.min(lo,v.y);hi=Math.max(hi,v.y);diam=Math.max(diam,Math.hypot(v.x,v.z)*2);if(/^(leaf|petiole)/.test(kind))leafTop=Math.max(leafTop,v.y);}}}assert.ok(lo>=-1e-7&&hi<=s.height+1e-7,id+' height '+dims+' '+month+' '+lo+' '+hi);assert.ok(diam<=s.spread+1e-7,id+' width '+dims+' '+diam);assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+1e-7,id+' leaf cap '+dims+' '+leafTop);assert.equal(roots.length,s.leafDensity>0?(s.bloom?51:42):0);for(const root of roots){assert.ok(ends.some(end=>distance(root,end)<1e-7));leafJoins++;}const groups=[];for(let i=0;i<petioles.length;i+=10)groups.push(petioles[i][0]);assert.equal(groups.length,s.leafDensity>0?(s.bloom?9:6):0);for(const root of groups){if(stemSegments.some(([a,b])=>onSegment(root,a,b)<1e-7))caulineRoots++;else{assert.ok(root[1]<=.005&&Math.hypot(root[0],root[2])<=s.spread*.023);basalGroups++;}}assert.equal(counts['sepal-wild-hellebore-ref-'+profile]||0,s.bloom?45:0);assert.equal(counts['bud-wild-hellebore-ref-'+profile]||0,s.bloom?3:0);assert.equal(counts['nectary-wild-hellebore-ref']||0,s.bloom?72:0);assert.equal(counts['anther-wild-hellebore-ref']||0,s.bloom?288:0);assert.equal(counts['carpel-wild-hellebore-ref']||0,s.bloom?27:0);assert.equal(counts['stem-stub-wild-hellebore-ref']||0,s.bloom?0:3);assert.equal(!!g.userData.flowerTargets?.length,s.bloom);assert.ok(!g.children.some(m=>/^(fruit|seed|root)-/.test(m.userData.component)));assert.deepEqual(p,copy);}finally{dispose(g);}}
 assert.equal(models,32);assert.equal(leafJoins,1242);assert.equal(caulineRoots,36);assert.equal(basalGroups,162);console.log('WILD_HELLEBORE_ACTUAL_BOUNDARIES '+JSON.stringify({models,leafJoins,caulineRoots,basalGroups}));
});
test('Wild hellebore flower cameras hit actual indexed sepals at two aspects and preserve previous saved dimensions',()=>{
 for(const[id,profile,pid,normal]of[['p-78bb98fc81e6','odorus',88510,[.375,.4,.24]],['p-6017abe82931','atrorubens',88511,[.325,.35,.21]]])for(const dims of[normal,[.03,.18,.012],[normal[0],normal[1],.005]]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{year:1,month:3,reference:false});try{assert.equal(g.userData.architecture,'wildHelleboreReferences');assert.ok(g.userData.surfaceSelection?.matched,id+' '+dims);assert.ok(g.userData.flowerTargets.length<=8);const surface=g.userData.flowerTargets[0].surface;assert.equal(surface.component,'sepal-wild-hellebore-ref-'+profile);g.position.set(-2,.012,-1);g.updateMatrixWorld(true);for(const aspect of[.8,1.65]){const pose=flowerInspectionView(g,aspect,40),camera=new PerspectiveCamera(40,aspect,.01,650);camera.position.fromArray(pose.position);camera.lookAt(...pose.target);camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.equal(hit?.object.userData.component,surface.component);assert.equal(hit.instanceId,surface.instanceId);assert.equal(hit.faceIndex,surface.faceIndex);assert.ok(hit.point.distanceTo(new Vector3(...pose.target))<2e-6);}}finally{dispose(g);}const d=emptyDocument(10,6);d.plans.A.plants=[p];d.view={year:1,month:3,reference:false,footprints:false,camera:{position:[-1.5,.8,-.5],target:[-3,.3,-1]}};const old={...structuredClone(d),catalogVersion:'2026-10-27.99'},copy=structuredClone(old);assert.deepEqual(validateDocument(old),d);assert.deepEqual(old,copy);}
});
test('Wild hellebore surfaces preserve basal foliage after managed flower removal and separate green sepal backs',()=>{
 for(const[id,profile,pid,normal]of[['p-78bb98fc81e6','odorus',88510,[.375,.4,.24]],['p-6017abe82931','atrorubens',88511,[.325,.35,.21]]])for(const dims of[normal,[.03,.18,.012]]){let expected=null;for(const month of[3,9,1]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{year:1,month,reference:false});try{const leaves=g.children.filter(m=>m.userData.component==='leaf-wild-hellebore-ref-'+profile+'-basal'),values=leaves.map(m=>[Buffer.from(m.instanceMatrix.array.buffer,m.instanceMatrix.array.byteOffset,m.count*64).toString('hex'),Buffer.from(m.instanceColor.array.buffer,m.instanceColor.array.byteOffset,m.count*12).toString('hex')]);if(profile!=='atrorubens'||month!==1){if(expected)assert.deepEqual(values,expected);else expected=values;}else assert.equal(leaves.length,0);for(const m of g.children.filter(m=>m.userData.component.startsWith('leaf-wild-hellebore-ref-'))){assert.ok(m.geometry.attributes.normal.getY(16*21+10)>.5);assert.equal(m.geometry.userData.wildHelleboreOrgan,profile==='odorus'?'gcWildHelleboreOdorusLeafRef':'gcWildHelleboreAtrorubensLeafRef');const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/gl_FrontFacing/);assert.ok(!shader.fragmentShader.includes('frostkissVein'));assert.ok(!/undefined|NaN/.test(shader.fragmentShader));}const sepal=g.children.find(m=>m.userData.component==='sepal-wild-hellebore-ref-'+profile);assert.equal(!!sepal,month===3);if(sepal){assert.equal(sepal.geometry.userData.wildHelleboreOrgan,profile==='odorus'?'gcWildHelleboreOdorusSepalRef':'gcWildHelleboreAtrorubensSepalRef');const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};sepal.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/gl_FrontFacing/);assert.match(shader.fragmentShader,/whCentre/);assert.equal(shader.fragmentShader.includes('whVeins'),profile==='atrorubens');assert.ok(!/undefined|NaN/.test(shader.fragmentShader));}}finally{dispose(g);}}}
});

test('Wild hellebore seasonal species sources retain domestic colour variation and qualified sparse-leaf and leafless management',()=>{
 for(const[id,profile,height,spread,colors,sku]of[['p-2a7757dc9dae','purpurascens',[.25,.4],[.3,.4],['purple','red','white','green','mixed'],'100gp'],['p-cf0679944050','torquatus',[.2,.3],[.2,.3],['purple','red','green','mixed'],'100gt'],['p-59c5e35710b4','cyclophyllus',[.2,.3],[.3,.4],['green'],'100gy']]){const c=CATALOG[id],a=c.appearance;assert.equal(c.form,'botanical');assert.deepEqual(c.height,height);assert.deepEqual(c.spread,spread);assert.deepEqual(c.colors,colors);assert.equal(c.source,'https://item.rakuten.co.jp/ogis/'+sku+'/');assert.equal(c.sourceChecked,'2026-10-27');assert.equal(c.bloomKnown,false);assert.equal(a.status,'partial');assert.equal(a.architecture,'wildHelleboreReferences');assert.equal(a.shootProfile,profile);assert.equal(a.leaflets,undefined);assert.equal(a.sources[a.basis.leafShape].scope,'genus');assert.equal(a.sources[a.basis.flowerShape].scope,'catalog-entry');for(const pattern of[/同一株の年間実物照合0/,/根生6群/,/根生2群だけを残す管理例/,/国内に花径の数値がなく/,/地上部全体の自然消失へ言い換えず/,/同じ株の月別変色/])assert.ok(a.unconfirmed.some(n=>pattern.test(n)),String(pattern));for(let month=1;month<=12;month++){const v=seasonAt(c,month);assert.equal(v.bloom,[2,3,4,5].includes(month));assert.equal(v.leafDensity,[12,1].includes(month)?0:1);assert.equal(v.groundDormant,false);assert.equal(v.shootScale,1);if(month>=6&&month<=11)assert.match(v.phase,/根生葉の群を減らした少葉/);}for(const color of['green','purple','red','pink','white','yellow','blue','mixed','unknown'])assert.equal(searchCatalog(CATALOG,{query:c.label,color}).some(([key])=>key===id),colors.includes(color));if(profile==='cyclophyllus'){assert.match(a.sourceConflict,/傷んだ葉を整理/);assert.match(a.unconfirmed[0],/成株の根生葉の細部は写っておらず/);}if(profile==='torquatus')assert.match(c.bloomText,/項目名の不一致/);}
});
test('Wild hellebore seasonal species basal and bract assemblies join real supports within independent plant dimensions including leafless winter',()=>{
 const matrix=new Matrix4(),v=new Vector3(),distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),onSegment=(p,a,b)=>{const d=b.map((x,i)=>x-a[i]),len=d.reduce((n,x)=>n+x*x,0),t=len?Math.max(0,Math.min(1,d.reduce((n,x,i)=>n+x*(p[i]-a[i]),0)/len)):0;return distance(p,a.map((x,i)=>x+t*d[i]));};let models=0,leafJoins=0,caulineRoots=0,basalGroups=0;
 for(const[id,profile,pid,normal]of[['p-2a7757dc9dae','purpurascens',88610,[.325,.35,.21]],['p-cf0679944050','torquatus',88611,[.25,.25,.16]],['p-59c5e35710b4','cyclophyllus',88612,[.25,.35,.16]]])for(const{dims,month,reference}of[...[normal,[.03,.18,.012],[normal[0],normal[1],.005],[.005,.08,.005],[normal[0],.005,.005]].flatMap(dims=>[3,9,1].map(month=>({dims,month,reference:false}))),{dims:normal,month:3,reference:true}]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},copy=structuredClone(p),view={year:1,month,reference},s=stateAt(p,view),g=plantModel(p,view);models++;try{g.updateMatrixWorld(true);const roots=[],ends=[],stemSegments=[],petioles=[];let lo=Infinity,hi=-Infinity,diam=0,leafTop=0;const counts={};for(const m of g.children){const kind=m.userData.component,pos=m.geometry.attributes.position;counts[kind]=(counts[kind]||0)+m.count;assert.ok(pos.array.every(Number.isFinite)&&m.geometry.attributes.normal.array.every(Number.isFinite)&&m.instanceMatrix.array.every(Number.isFinite));for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);matrix.premultiply(m.matrixWorld);const point=y=>new Vector3(0,y,0).applyMatrix4(matrix).toArray();if(kind.startsWith('leaf-wild-hellebore-ref-'))roots.push(point(0));if(['petiole-wild-hellebore-ref','leaf-axis-wild-hellebore-ref'].includes(kind))ends.push(point(.5));if(kind==='petiole-wild-hellebore-ref')petioles.push([point(-.5),point(.5)]);if(kind==='stem-wild-hellebore-ref')stemSegments.push([point(-.5),point(.5)]);for(let j=0;j<pos.count;j++){v.fromBufferAttribute(pos,j).applyMatrix4(matrix);lo=Math.min(lo,v.y);hi=Math.max(hi,v.y);diam=Math.max(diam,Math.hypot(v.x,v.z)*2);if(/^(leaf|petiole)/.test(kind))leafTop=Math.max(leafTop,v.y);}}}assert.ok(lo>=-1e-7&&hi<=s.height+1e-7,id+' height '+dims+' '+month+' '+lo+' '+hi);assert.ok(diam<=s.spread+1e-7,id+' width '+dims+' '+diam);assert.ok(leafTop<=Math.min(s.height,s.leafHeight)+1e-7,id+' leaf cap '+dims+' '+leafTop);assert.equal(roots.length,s.leafDensity>0?(s.bloom?(profile==='purpurascens'?39:51):(profile==='purpurascens'?10:14)):0);for(const root of roots){assert.ok(ends.some(end=>distance(root,end)<1e-7));leafJoins++;}const groups=[];for(let i=0;i<petioles.length;i+=10)groups.push(petioles[i][0]);assert.equal(groups.length,s.leafDensity>0?(s.bloom?9:2):0);for(const root of groups){if(stemSegments.some(([a,b])=>onSegment(root,a,b)<1e-7))caulineRoots++;else{assert.ok(root[1]<=.005&&Math.hypot(root[0],root[2])<=s.spread*.023);basalGroups++;}}assert.equal(counts['sepal-wild-hellebore-ref-'+profile]||0,s.bloom?45:0);assert.equal(counts['bud-wild-hellebore-ref-'+profile]||0,s.bloom?3:0);assert.equal(counts['nectary-wild-hellebore-ref']||0,s.bloom?72:0);assert.equal(counts['anther-wild-hellebore-ref']||0,s.bloom?288:0);assert.equal(counts['carpel-wild-hellebore-ref']||0,s.bloom?27:0);assert.equal(counts['stem-stub-wild-hellebore-ref']||0,s.bloom?0:3);assert.equal(!!g.userData.flowerTargets?.length,s.bloom);assert.ok(!g.children.some(m=>/^(fruit|seed|root)-/.test(m.userData.component)));assert.deepEqual(p,copy);}finally{dispose(g);}}
 assert.equal(models,48);assert.equal(leafJoins,1036);assert.equal(caulineRoots,54);assert.equal(basalGroups,138);console.log('WILD_HELLEBORE_SEASONAL_ACTUAL_BOUNDARIES '+JSON.stringify({models,leafJoins,caulineRoots,basalGroups}));
});
