 for(const[id,profile,pid,normal]of[['p-2a7757dc9dae','purpurascens',88610,[.325,.35,.21]],['p-cf0679944050','torquatus',88611,[.25,.25,.16]],['p-59c5e35710b4','cyclophyllus',88612,[.25,.35,.16]]])for(const dims of[normal,[.03,.18,.012],[normal[0],normal[1],.005]]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{year:1,month:3,reference:false});try{assert.equal(g.userData.architecture,'wildHelleboreReferences');assert.ok(g.userData.surfaceSelection?.matched,id+' '+dims);assert.ok(g.userData.flowerTargets.length<=8);const surface=g.userData.flowerTargets[0].surface;assert.equal(surface.component,'sepal-wild-hellebore-ref-'+profile);g.position.set(-2,.012,-1);g.updateMatrixWorld(true);for(const aspect of[.8,1.65]){const pose=flowerInspectionView(g,aspect,40),camera=new PerspectiveCamera(40,aspect,.01,650);camera.position.fromArray(pose.position);camera.lookAt(...pose.target);camera.updateMatrixWorld(true);const ray=new Raycaster();ray.setFromCamera(new Vector2(0,0),camera);const hit=ray.intersectObject(g,true).find(h=>{const z=-h.point.clone().applyMatrix4(camera.matrixWorldInverse).z;return z>=camera.near&&z<=camera.far;});assert.equal(hit?.object.userData.component,surface.component);assert.equal(hit.instanceId,surface.instanceId);assert.equal(hit.faceIndex,surface.faceIndex);assert.ok(hit.point.distanceTo(new Vector3(...pose.target))<2e-6);}}finally{dispose(g);}const d=emptyDocument(10,6);d.plans.A.plants=[p];d.view={year:1,month:3,reference:false,footprints:false,camera:{position:[-1.5,.8,-.5],target:[-3,.3,-1]}};const old={...structuredClone(d),catalogVersion:'2026-10-27.100'},copy=structuredClone(old);assert.deepEqual(validateDocument(old),d);assert.deepEqual(old,copy);}
