test('Wild hellebore seasonal species thin whole leaf fans with attached petioles and compile distinct cup fronts and backs',()=>{
 for(const[id,profile,pid,normal,type,perFan]of[['p-2a7757dc9dae','purpurascens',88610,[.325,.35,.21],'Purpurascens',5],['p-cf0679944050','torquatus',88611,[.25,.25,.16],'Torquatus',7],['p-59c5e35710b4','cyclophyllus',88612,[.25,.35,.16],'Cyclophyllus',7]])for(const dims of[normal,[.03,.18,.012]]){let expected=null;for(const month of[3,9,1]){const p={...makePlant(id,pid,3,3),height:dims[0],spread:dims[1],leafHeight:dims[2]},g=plantModel(p,{year:1,month,reference:false});try{const leaves=g.children.filter(m=>m.userData.component==='leaf-wild-hellebore-ref-'+profile+'-basal'),values=leaves.map(m=>[Buffer.from(m.instanceMatrix.array.buffer,m.instanceMatrix.array.byteOffset,perFan*2*64).toString('hex'),Buffer.from(m.instanceColor.array.buffer,m.instanceColor.array.byteOffset,perFan*2*12).toString('hex')]);if(month===3)expected=values;else if(month===9)assert.deepEqual(values,expected);else assert.equal(leaves.length,0);assert.equal(leaves.reduce((n,m)=>n+m.count,0),month===3?perFan*6:month===9?perFan*2:0);for(const m of g.children.filter(m=>m.userData.component.startsWith('leaf-wild-hellebore-ref-'))){assert.ok(m.geometry.attributes.normal.getY(16*21+10)>.5);assert.equal(m.geometry.userData.wildHelleboreOrgan,'gcWildHellebore'+type+'LeafRef');const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};m.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/gl_FrontFacing/);assert.ok(!shader.fragmentShader.includes('frostkissVein'));assert.ok(!/undefined|NaN/.test(shader.fragmentShader));}const sepal=g.children.find(m=>m.userData.component==='sepal-wild-hellebore-ref-'+profile);assert.equal(!!sepal,month===3);if(sepal){assert.equal(sepal.geometry.userData.wildHelleboreOrgan,'gcWildHellebore'+type+'SepalRef');const shader={uniforms:{},vertexShader:'#include <common>',fragmentShader:'#include <common>\n#include <emissivemap_fragment>'};sepal.material.onBeforeCompile(shader,{});assert.match(shader.fragmentShader,/gl_FrontFacing/);assert.match(shader.fragmentShader,/whSpeciesCentre/);assert.equal(shader.fragmentShader.includes('whSpeciesVeins'),profile!=='cyclophyllus');assert.ok(!/undefined|NaN/.test(shader.fragmentShader));}if(month!==3){const stubs=g.children.find(m=>m.userData.component==='stem-stub-wild-hellebore-ref');assert.equal(stubs.count,3);assert.equal(g.children.some(m=>m.userData.component==='stem-wild-hellebore-ref'),false);}}finally{dispose(g);}}}
});
